const UPDATED="11/04 18:05";
const QS=[{"id": "p01", "u": "에너지 띠", "t": "mc", "lv": 1, "q": "고체에서 에너지 띠(band)가 형성되는 이유로 옳은 것은?", "c": ["많은 원자가 가까이 모이면 원자들의 에너지 준위가 미세하게 갈라져 촘촘한 띠를 이루기 때문", "전자가 핵에서 완전히 떨어져 나가기 때문", "원자 하나의 에너지 준위가 연속적이기 때문", "고체에서는 전자의 에너지가 양자화되지 않기 때문"], "a": 0, "ex": "원자 1개일 때는 $E_n=-E_0/n^2$로 불연속이에요. 원자가 많이 모이면 파울리 배타 원리 때문에 준위가 갈라져 띠가 되고, 띠 사이에 띠 간격(band gap)이 생겨요.", "ref": ["s2:2", "s2:3"], "s": "phys", "cx": ["원자 N개가 모이면 각 준위가 N개로 미세하게 갈라져 거의 연속적인 띠가 돼요.", "전자가 떨어져 나가는 것은 이온화이고, 띠 형성과는 관계없어요.", "원자 1개의 준위는 $E_n=-E_0/n^2$처럼 불연속이에요.", "고체에서도 에너지는 양자화돼요. 준위가 아주 촘촘해 띠처럼 보일 뿐이에요."]}, {"id": "p02", "u": "에너지 띠", "t": "mc", "lv": 1, "q": "도체·반도체·절연체의 에너지 띠 구조를 바르게 설명한 것은?", "c": ["도체는 띠가 겹치거나 전도띠가 일부만 차 있고, 반도체는 띠 간격이 작으며, 절연체는 띠 간격이 크다", "도체의 띠 간격이 가장 크다", "반도체는 원자가 띠가 비어 있다", "절연체는 원자가 띠와 전도띠가 겹친다"], "a": 0, "ex": "띠 간격이 작으면 열에너지로도 일부 전자가 전도띠로 들떠 전류가 흘러요(반도체).", "ref": ["s2:4"], "s": "phys", "cx": ["도체는 겹침, 반도체는 작은 간격, 절연체는 큰 간격으로 셋을 바르게 구분했어요.", "띠 간격이 가장 큰 것은 절연체예요. 도체는 간격이 없거나 겹쳐요.", "반도체의 원자가 띠는 (0 K 기준) 전자로 차 있어요. 비어 있는 것은 전도띠예요.", "띠가 겹치는 것은 도체예요. 절연체는 띠 간격이 커요."]}, {"id": "p03", "u": "에너지 띠", "t": "mc", "lv": 1, "q": "온도가 올라갈 때 금속과 반도체의 전기 저항 변화로 옳은 것은?", "c": ["금속은 증가, 반도체는 감소", "금속은 감소, 반도체는 증가", "둘 다 증가", "둘 다 감소"], "a": 0, "ex": "금속은 원자(양이온)의 진동이 커져 전자의 산란이 늘어요. 반도체는 전도띠로 들뜨는 전하 운반자 수가 늘어요.", "ref": ["s2:4"], "s": "phys", "cx": ["금속은 원자 진동이 커져 저항이 증가하고, 반도체는 운반자가 늘어 저항이 감소해요.", "금속과 반도체가 서로 바뀌었어요.", "반도체는 온도가 오르면 저항이 줄어요.", "금속은 온도가 오르면 저항이 늘어요."]}, {"id": "p04", "u": "도핑", "t": "mc", "lv": 1, "q": "순수한 규소(Si)에 붕소(B)를 소량 첨가하여 만든 반도체와 그 주된 전하 운반자는?", "c": ["P형 – 양공", "N형 – 전자", "P형 – 전자", "N형 – 양공"], "a": 0, "ex": "B는 원자가 전자가 3개(3족)라 결합에 전자 하나가 부족 → 양공이 생겨요. 받개 준위는 원자가 띠 바로 위에 있어요.", "ref": ["s2:5"], "s": "phys", "cx": ["B는 3족(원자가 전자 3개)이라 결합 전자가 하나 부족해 양공이 생겨요 → P형.", "N형은 5족(P, As)을 넣었을 때예요.", "B를 넣으면 다수 운반자는 전자가 아니라 양공이에요.", "B 도핑은 N형이 아니라 P형이에요."]}, {"id": "p05", "u": "도핑", "t": "mc", "lv": 1, "q": "N형 반도체를 만들기 위해 Si에 첨가하는 원소로 적절한 것은?", "c": ["인(P), 비소(As), 안티모니(Sb)", "붕소(B), 알루미늄(Al), 인듐(In)", "탄소(C), 저마늄(Ge)", "헬륨(He), 네온(Ne)"], "a": 0, "ex": "5족 원소는 원자가 전자가 5개라 결합에 참여하지 않는 전자 1개가 생겨요. 주개 준위는 전도띠 바로 아래에 있어요.", "ref": ["s2:6"], "s": "phys", "cx": ["5족 원소는 원자가 전자가 5개라 남는 전자가 생겨 N형이 돼요.", "3족 원소예요 → P형을 만들어요.", "C, Ge는 Si와 같은 14족이라 남거나 모자라는 전자가 없어요.", "18족 비활성 기체는 결합을 하지 않아 도핑에 쓰지 않아요."]}, {"id": "p06", "u": "도핑", "t": "mc", "lv": 1, "q": "[Quiz] N형 반도체는 결합에 참여하지 않는 전자가 많고, P형 반도체는 양공이 많다. 각 반도체 전체의 전기적 상태는?", "c": ["둘 다 전기적으로 중성이다", "N형은 (−), P형은 (+)로 대전된다", "N형은 (+), P형은 (−)로 대전된다", "둘 다 (−)로 대전된다"], "a": 0, "ex": "도핑한 원자 자체도 중성이므로 전체 양성자 수 = 전자 수예요. \"전자가 많다\"는 것은 움직일 수 있는 운반자가 많다는 뜻이에요(필기: 원자가 띠나 결합에 참여하지 않는 전자).", "ref": ["s2:7"], "s": "phys", "cx": ["도핑 원자도 중성 원자라 양성자 수 = 전자 수 → 전체는 중성이에요.", "\"전자가 많다\"는 움직이는 운반자가 많다는 뜻이지 대전된 게 아니에요.", "대전되지 않아요. 부호를 반대로 붙여도 틀려요.", "둘 다 중성이에요."]}, {"id": "p07", "u": "도핑", "t": "mc", "lv": 1, "q": "반도체의 전하 운반자가 전자인지 양공인지(부호) 실험적으로 알아내는 방법은?", "c": ["홀 효과(Hall effect)", "광전 효과", "브래그 회절", "도플러 효과"], "a": 0, "ex": "자기장 속에서 전류를 흘리면 로렌츠 힘으로 운반자가 한쪽에 쌓여 홀 전압이 생기고, 그 부호로 운반자를 판별해요.", "ref": ["s2:8"], "s": "phys", "cx": ["자기장 속 전류에 로렌츠 힘이 작용해 운반자가 한쪽에 쌓여요. 그 전압의 부호로 운반자를 판별해요.", "광전 효과는 빛에 의한 전자 방출 현상이에요.", "브래그 회절은 결정 구조(면 간격)를 알아내는 방법이에요.", "도플러 효과는 파원의 운동에 따른 진동수 변화예요."]}, {"id": "p08", "u": "도핑", "t": "mc", "lv": 3, "q": "같은 방향(+x)으로 전류가 흐르는 P형과 N형 반도체에 같은 자기장(+z)을 걸었다. 홀 효과에 대한 설명으로 옳은 것은?", "c": ["두 경우 운반자는 같은 쪽(−y)으로 휘어 쌓이지만, 쌓이는 전하의 부호가 달라 홀 전압의 부호가 반대이다", "운반자가 서로 반대쪽으로 쌓이고, 홀 전압 부호는 같다", "두 경우 모두 홀 전압이 0이다", "N형에서만 홀 전압이 생긴다"], "a": 0, "ex": "양공(+e)은 +x로 이동 → $F=q\\vec v\\times\\vec B$는 −y 방향이에요. 전자(−e)는 −x로 이동 → $(-e)(-v\\hat x)\\times B\\hat z$도 −y 방향이에요. 같은 쪽에 쌓이지만 전하 부호가 반대라 홀 전압도 반대예요.", "ref": ["s2:8"], "s": "phys", "cx": ["양공(+x 이동)과 전자(−x 이동) 모두 $q\\\\vec v\\\\times\\\\vec B$가 −y 방향이라 같은 쪽에 쌓이고, 전하 부호만 달라요.", "쌓이는 쪽은 같고 부호가 달라요. 반대로 말했어요.", "운반자가 한쪽에 쌓이므로 홀 전압이 생겨요.", "P형에서도 양공이 쌓여 홀 전압이 생겨요."]}, {"id": "p09", "u": "PN접합", "t": "mc", "lv": 1, "q": "PN 접합에서 공핍층(공간전하층)이 생기는 과정으로 옳은 것은?", "c": ["접합면에서 전자와 양공이 확산하여 재결합하고, 움직일 수 없는 이온만 남은 영역이 생긴다", "외부 전원이 있어야만 생긴다", "전자가 P형에서 N형으로 이동하여 생긴다", "양공이 N형에 계속 쌓여 생긴다"], "a": 0, "ex": "N쪽에는 (+)이온(주개), P쪽에는 (−)이온(받개)이 남아 내부 전기장이 생기고, 이것이 더 이상의 확산을 막아요.", "ref": ["s2:10"], "s": "phys", "cx": ["농도 차로 확산 → 재결합 → 이온만 남은 영역 = 공핍층이에요.", "외부 전원 없이 접합만 해도 생겨요.", "전자는 N형에서 P형으로 확산해요(방향이 반대).", "양공이 계속 쌓이는 게 아니라 재결합해서 사라지고 이온만 남아요."]}, {"id": "p10", "u": "PN접합", "t": "mc", "lv": 1, "q": "규소 PN 접합 다이오드의 내부 전위차(built-in voltage) 크기는 대략?", "c": ["0.7 V", "7 V", "0.07 V", "1.5 V"], "a": 0, "ex": "그래서 순방향으로 약 0.7 V(턴온 전압 $V_{\\gamma}$) 이상 걸어야 전류가 크게 흐르기 시작해요.", "ref": ["s2:10", "s2:13"], "s": "phys", "cx": ["Si 다이오드의 내부 전위(턴온 전압)는 약 0.7 V예요.", "10배 커요. 7 V가 아니에요.", "열전압(약 25 mV)과 헷갈리지 마세요. 0.07 V가 아니에요.", "Si의 값이 아니에요."]}, {"id": "p11", "u": "PN접합", "t": "mc", "lv": 1, "q": "다이오드에 순방향 바이어스를 거는 방법과 그 결과는?", "c": ["P형에 (+), N형에 (−)를 연결 → 공핍층이 얇아져 전류가 흐른다", "P형에 (−), N형에 (+)를 연결 → 전류가 흐른다", "P형에 (+), N형에 (−)를 연결 → 공핍층이 넓어진다", "어느 방향이든 전류가 같다"], "a": 0, "ex": "순방향에서는 외부 전압이 내부 전위 장벽을 낮춰 전자와 양공이 접합면을 넘어 이동해요. 전체 전류는 $I_{total}=I_{electron}+I_{hole}$예요.", "ref": ["s2:9", "s2:10"], "s": "phys", "cx": ["순방향은 P에 +예요. 장벽이 낮아지고 공핍층이 얇아져 전류가 흘러요.", "P에 −는 역방향이라 전류가 거의 안 흘러요.", "연결은 맞지만 공핍층이 넓어지는 건 역방향일 때예요.", "다이오드는 방향성이 있어서 한쪽으로만 잘 흘려요."]}, {"id": "p12", "u": "PN접합", "t": "mc", "lv": 1, "q": "다이오드에 역방향 전압을 아주 크게 걸면 일어나는 현상은?", "c": ["항복(breakdown)이 일어나 역방향으로 큰 전류가 흐른다", "공핍층이 사라진다", "전류가 순방향으로 흐른다", "다이오드가 초전도체가 된다"], "a": 0, "ex": "특성곡선의 역방향 쪽 끝 \"Zener breakdown region\"이에요. 그 전에는 매우 작은 역포화전류 $I_s$만 흘러요.", "ref": ["s2:10", "s2:13"], "s": "phys", "cx": ["특성곡선 역방향 끝의 항복(Zener breakdown) 영역이에요.", "역방향에서는 공핍층이 오히려 넓어져요.", "역전압이므로 전류는 역방향으로 흘러요.", "초전도와는 관계없어요."]}, {"id": "p13", "u": "다이오드 특성", "t": "mc", "lv": 1, "q": "이상적인 다이오드의 동작을 바르게 설명한 것은?", "c": ["순방향(i>0)일 때 v=0인 단락회로, 역방향(v<0)일 때 i=0인 개방회로", "순방향일 때 개방회로, 역방향일 때 단락회로", "양방향 모두 저항처럼 동작", "순방향에서 0.7 V 강하"], "a": 0, "ex": "⚠️ 수업 PPT 텍스트에는 \"순방향: 개방회로, 역방향: 단락회로\"라고 반대로 적혀 있지만, 같은 슬라이드 그림(Forward bias: i>0, v=0 / Reverse bias: v<0, i=0)이 맞아요.", "ref": ["s2:14", "s2:13"], "s": "phys", "cx": ["그림 기준: 순방향은 v=0(단락), 역방향은 i=0(개방)이에요.", "PPT 글자에 있는 오타예요. 반대예요.", "이상 다이오드는 방향에 따라 단락/개방이지 저항처럼 동작하지 않아요.", "0.7 V 강하는 고정 전압 모델이에요."]}, {"id": "p14", "u": "다이오드 특성", "t": "mc", "lv": 1, "q": "실제 다이오드의 전류–전압 식 $i_D=I_s\\left(e^{v_D/\\eta V_t}-1\\right)$에서 $V_t$(열전압)와 그 상온값은?", "c": ["$V_t=kT/e$, 약 25 mV", "$V_t=eT/k$, 약 0.7 V", "$V_t=kT/e$, 약 0.7 V", "$V_t=e/kT$, 약 25 V"], "a": 0, "ex": "η는 이상인자(물질에 따라 1~2), $I_s$는 역포화전류예요.", "ref": ["s2:13"], "s": "phys", "cx": ["$V_t=kT/e$이고, 상온에서 약 25 mV예요.", "식이 틀렸고, 0.7 V는 턴온 전압이에요.", "식은 맞지만 값이 턴온 전압과 섞였어요.", "식도 값도 틀렸어요."]}, {"id": "p15", "u": "다이오드 특성", "t": "num", "lv": 3, "q": "이상인자 η = 1, $V_t$ = 25 mV인 다이오드가 순방향으로 충분히 켜져 있다($e^{v/V_t}\\gg1$). 전류를 10배로 늘리려면 전압을 약 몇 mV 높여야 하는가?", "a": 57.6, "tol": 0.03, "unit": "mV", "ex": "$\\dfrac{i_2}{i_1}=e^{\\Delta v/V_t}=10$ → $\\Delta v=V_t\\ln10=25\\times2.303\\approx57.6$ mV.", "ref": ["s2:13"], "s": "phys"}, {"id": "p16", "u": "다이오드 특성", "t": "mc", "lv": 1, "q": "다이오드의 '구간 선형 모델'에 대한 설명으로 옳은 것은?", "c": ["턴온 전압 $V_{\\gamma}$의 전지 + 순방향 저항 $R_{f}$ + 이상 다이오드로 근사하며, 켜진 뒤 기울기는 $di_D/dv_D=1/R_f$", "턴온 전압 없이 이상 다이오드만으로 근사", "$V_{\\gamma}$에서 수직으로 전류가 증가", "역방향에서 저항 $R_{f}$만큼 전류가 흐른다"], "a": 0, "ex": "고정 전압 모델은 $V_{\\gamma}$ + 이상 다이오드(수직 상승), 이상적 모델은 0 V에서 바로 켜져요.", "ref": ["s1:2"], "s": "phys", "cx": ["$V_{\\gamma} + R_{f}$ + 이상 다이오드 → 켜진 뒤 기울기는 $1/R_{f}$예요.", "이상적 모델에 대한 설명이에요.", "고정 전압 모델에 대한 설명이에요.", "역방향에서는 어느 모델이든 전류가 0이에요."]}, {"id": "p17", "u": "다이오드 특성", "t": "num", "lv": 2, "q": "전원 $V_A$ = 5 V, 부하 R = 500 Ω, 다이오드가 순방향으로 직렬 연결된 회로를 구간 선형 모델($R_{f} = 20$ Ω, $V_{\\gamma} = 0.7$ V)로 해석할 때 다이오드 전류 $i_D$는 몇 mA인가?", "a": 8.27, "tol": 0.01, "unit": "mA", "ex": "$i_D=\\dfrac{5-0.7}{500+20}=\\dfrac{4.3}{520}=8.27$ mA.", "ref": ["s1:3"], "s": "phys"}, {"id": "p18", "u": "다이오드 특성", "t": "num", "lv": 2, "q": "위 회로(구간 선형 모델)에서 다이오드 양단 전압 $v_D$는 몇 V인가? (소수 둘째 자리)", "a": 0.865, "tol": 0.01, "unit": "V", "ex": "$v_D=V_\\gamma+i_DR_f=0.7+8.27\\times10^{-3}\\times20\\approx0.87$ V.", "ref": ["s1:3"], "s": "phys"}, {"id": "p19", "u": "다이오드 특성", "t": "num", "lv": 2, "q": "같은 회로(5 V, 500 Ω)를 고정 전압 모델($V_{\\gamma} = 0.7$ V)로 해석하면 전류는 몇 mA인가?", "a": 8.6, "tol": 0.01, "unit": "mA", "ex": "$i_D=\\dfrac{5-0.7}{500}=8.6$ mA. 이상적 모델이면 $5/500=10$ mA예요.", "ref": ["s1:2", "s1:3"], "s": "phys"}, {"id": "p20", "u": "다이오드 특성", "t": "num", "lv": 2, "q": "5 V 전원, 1 kΩ 저항, 순방향 다이오드 2개를 모두 직렬로 연결했다. 고정 전압 모델(각 0.7 V)로 구한 전류는 몇 mA인가?", "a": 3.6, "tol": 0.01, "unit": "mA", "ex": "$i=\\dfrac{5-2\\times0.7}{1000}=3.6$ mA.", "ref": ["s1:2"], "s": "phys"}, {"id": "p21", "u": "다이오드 특성", "t": "mc", "lv": 2, "q": "5 V 전원, 1 kΩ 저항, 다이오드 1개를 직렬로 연결하되 다이오드를 역방향으로 연결했다. 저항 양단 전압은? (이상적 다이오드)", "c": ["0 V", "5 V", "4.3 V", "2.5 V"], "a": 0, "ex": "역방향 이상 다이오드는 개방회로(i = 0)예요. 저항에 전류가 흐르지 않으니 전압도 0이고, 5 V는 모두 다이오드에 걸려요.", "ref": ["s2:14"], "s": "phys", "cx": ["역방향 다이오드 = 개방 → 전류 0 → 저항 전압 0이에요.", "5 V는 다이오드 양단 전압이지 저항 전압이 아니에요.", "순방향 고정 전압 모델일 때의 값이에요.", "전압이 반씩 나뉘지 않아요. 전류가 0이에요."]}, {"id": "p22", "u": "정류·평활", "t": "mc", "lv": 1, "q": "진폭 4 V 사인파를 이상적 다이오드 1개와 1 kΩ 저항으로 된 반파 정류회로에 넣었을 때 출력 $v_o(t)$는?", "c": ["(+) 반주기에만 0~4 V의 반쪽 사인파, (−) 반주기에는 0 V", "−4~4 V 사인파 그대로", "(−) 반주기만 출력", "항상 4 V 직류"], "a": 0, "ex": "(+) 반주기에는 다이오드가 켜져(단락) 입력이 그대로 나오고, (−) 반주기에는 꺼져(개방) 출력이 0이에요.", "ref": ["s2:15", "s2:29"], "s": "phys", "cx": ["(+) 반주기에는 단락이라 입력이 그대로 나오고, (−) 반주기에는 개방이라 0 V예요.", "다이오드가 (−) 반주기를 막아요.", "방향이 반대예요. (+) 반주기만 통과해요.", "평활 축전기가 없으므로 직류가 되지 않아요."]}, {"id": "p23", "u": "정류·평활", "t": "num", "lv": 2, "q": "진폭 4 V 사인파를 반파 정류회로에 넣었다. 고정 전압 모델($V_{\\gamma} = 0.7$ V)로 구한 출력의 최댓값은 몇 V인가?", "a": 3.3, "tol": 0.01, "unit": "V", "ex": "$4-0.7=3.3$ V. 또 입력이 0.7 V를 넘어야 출력이 나오기 시작해요.", "ref": ["s2:15", "s1:2"], "s": "phys"}, {"id": "p24", "u": "정류·평활", "t": "mc", "lv": 1, "q": "브리지(전파) 정류회로에 필요한 다이오드 개수와 출력의 특징은?", "c": ["4개 – 교류의 (−) 반주기도 뒤집혀 출력이 모두 (+)가 된다", "1개 – (+) 반주기만 출력", "2개 – 출력이 (−)만 나온다", "4개 – 출력이 교류 그대로"], "a": 0, "ex": "각 반주기마다 대각선 위치의 다이오드 2개가 켜져, 부하에는 항상 같은 방향으로 전류가 흘러요.", "ref": ["s2:17"], "s": "phys", "cx": ["4개, 대각선 쌍이 번갈아 켜져 출력이 모두 (+)가 돼요.", "다이오드 1개는 반파 정류예요.", "브리지는 4개이고, 출력은 (+)예요.", "개수는 맞지만 출력은 정류된 (+)예요."]}, {"id": "p25", "u": "정류·평활", "t": "mc", "lv": 2, "q": "[Quiz] 브리지 다이오드 회로 출력단에 LED를 연결하고, 입력에 전지를 연결했다. LED에 불이 들어오는 경우는?", "c": ["전지를 어느 방향으로 연결해도 불이 들어온다", "1번 방향으로 연결할 때만", "2번 방향으로 연결할 때만", "어느 방향으로도 불이 들어오지 않는다"], "a": 0, "ex": "브리지 정류회로는 입력 극성과 관계없이 출력 극성이 항상 같아요(수행평가 예정 퀴즈).", "ref": ["s2:16"], "s": "phys", "cx": ["브리지는 입력 극성과 관계없이 출력 극성이 같아요 → 어느 쪽이든 LED가 켜져요.", "방향 제한이 없어요.", "방향 제한이 없어요.", "어느 방향이든 한 쌍의 다이오드가 켜져 전류가 흘러요."]}, {"id": "p26", "u": "정류·평활", "t": "num", "lv": 3, "q": "진폭(최댓값) 8 V 사인파를 브리지 정류회로에 넣었다. 고정 전압 모델($V_{\\gamma} = 0.7$ V)로 구한 출력 최댓값은 몇 V인가?", "a": 6.6, "tol": 0.01, "unit": "V", "ex": "브리지에서는 매 반주기 다이오드 2개가 직렬로 켜지므로 $8-2\\times0.7=6.6$ V예요.", "ref": ["s2:17", "s1:2"], "s": "phys"}, {"id": "p27", "u": "정류·평활", "t": "mc", "lv": 1, "q": "[Quiz] 정류회로 출력의 부하저항에 축전기를 병렬로 연결하면?", "c": ["축전기가 충전·방전을 반복해 출력 전압의 굴곡(리플)이 줄어 직류에 가까워진다", "출력이 다시 교류가 된다", "출력 전압이 0이 된다", "리플 진동수가 0이 된다"], "a": 0, "ex": "전압이 올라갈 때 충전되었다가, 내려갈 때 부하로 방전해 전압이 급격히 떨어지지 않게 해요(평활회로).", "ref": ["s2:18", "s2:19"], "s": "phys", "cx": ["전압이 오를 때 충전, 내릴 때 방전해 굴곡이 줄어요.", "축전기는 교류로 되돌리지 않아요.", "출력이 사라지지 않고 오히려 유지돼요.", "리플은 작아질 뿐 진동수는 2f(전파)로 남아요."]}, {"id": "p28", "u": "정류·평활", "t": "num", "lv": 2, "q": "평활회로 출력에서 최댓값 7.8 V, 최솟값 7.2 V, 평균 직류 전압 7.5 V를 측정했다. 리플 비율 $r_{pp}$는 몇 %인가?", "a": 8.0, "tol": 0.01, "unit": "%", "ex": "$V_{ripple}=7.8-7.2=0.6$ V, $r_{pp}=\\dfrac{0.6}{7.5}\\times100=8.0$%.", "ref": ["s2:19"], "s": "phys"}, {"id": "p29", "u": "정류·평활", "t": "mc", "lv": 2, "q": "1 Hz 교류를 브리지(전파) 정류한 뒤 평활했을 때 리플 진동수는?", "c": ["2 Hz", "1 Hz", "0.5 Hz", "4 Hz"], "a": 0, "ex": "전파 정류는 한 주기에 봉우리가 2번 생기므로 리플 진동수가 입력의 2배예요(반파 정류는 입력과 같은 1 Hz). $f_{ripple}=1/T_{ripple}$.", "ref": ["s2:19", "s2:20"], "s": "phys", "cx": ["전파 정류는 한 주기에 봉우리가 2개 → 리플 진동수 2 Hz예요.", "1 Hz는 반파 정류일 때예요.", "진동수가 줄지 않아요.", "4배가 되지는 않아요."]}, {"id": "p30", "u": "정류·평활", "t": "num", "lv": 2, "q": "정류회로 실험에서 부하 300 Ω, 평활 축전기 2200 μF를 사용했다. RC 시간 상수는 몇 초인가?", "a": 0.66, "tol": 0.01, "unit": "s", "ex": "$\\tau=RC=300\\times2200\\times10^{-6}=0.66$ s. 시간 상수가 리플 주기(0.5 s)보다 클수록 방전이 느려 리플이 작아져요.", "ref": ["s2:20"], "s": "phys"}, {"id": "p31", "u": "정류·평활", "t": "num", "lv": 1, "q": "함수발생기에서 $V_{pp}$ = 16 V 사인파를 출력할 때 진폭(최댓값)은 몇 V인가?", "a": 8.0, "tol": 0.001, "unit": "V", "ex": "$V_{pp}$(peak-to-peak)는 최댓값과 최솟값의 차이이므로 진폭은 16/2 = 8 V예요.", "ref": ["s2:20", "s2:26"], "s": "phys"}, {"id": "p32", "u": "계측기", "t": "mc", "lv": 1, "q": "오실로스코프에서 시간 축(초/눈금)을 조절하는 부분은?", "c": ["Horizontal(수평)", "Vertical(수직)", "Trigger", "Function generator"], "a": 0, "ex": "Vertical은 전압 축(V/div), Horizontal은 시간 축(s/div), Trigger는 파형을 화면에 고정시키는 기준점이에요.", "ref": ["s2:25"], "s": "phys", "cx": ["Horizontal = 시간 축(s/div)이에요.", "Vertical은 전압 축(V/div)이에요.", "Trigger는 파형을 화면에 고정시키는 기준이에요.", "함수발생기는 신호를 만드는 별도 장비예요."]}, {"id": "p33", "u": "계측기", "t": "mc", "lv": 1, "q": "멀티미터와 비교한 오실로스코프의 가장 큰 장점은?", "c": ["시간에 따라 변하는 전압 파형을 그래프로 볼 수 있다", "저항을 측정할 수 있다", "전류를 직접 측정할 수 있다", "휴대가 간편하다"], "a": 0, "ex": "Oscillation + Scope, 즉 진동을 보는 장치예요.", "ref": ["s2:21", "s2:22"], "s": "phys", "cx": ["Oscillation + Scope: 시간에 따른 파형을 볼 수 있다는 게 핵심이에요.", "저항 측정은 멀티미터의 기능이에요.", "오실로스코프는 전압을 재요. 전류를 직접 재지는 않아요.", "휴대성은 멀티미터가 더 좋아요."]}, {"id": "p34", "u": "계측기", "t": "mc", "lv": 1, "q": "함수발생기에서 설정할 수 있는 항목이 아닌 것은?", "c": ["저항값", "주파수(Freq)", "진폭(Ampl, Vpp)", "오프셋(Offset)과 위상(Phase)"], "a": 0, "ex": "함수발생기는 Sine, Square, Ramp, Pulse 등의 파형과 주파수, 진폭, 오프셋, 위상을 설정해 신호를 내보내요.", "ref": ["s2:26", "s2:27"], "s": "phys", "cx": ["저항값은 함수발생기가 설정하는 항목이 아니에요 → 정답.", "주파수는 설정할 수 있어요.", "진폭(Vpp)은 설정할 수 있어요.", "오프셋과 위상도 설정할 수 있어요."]}, {"id": "p35", "u": "도핑", "t": "mc", "lv": 2, "q": "P형 반도체의 받개 준위와 N형 반도체의 주개 준위의 위치를 바르게 짝지은 것은?", "c": ["받개 준위 – 원자가 띠 바로 위, 주개 준위 – 전도띠 바로 아래", "받개 준위 – 전도띠 바로 아래, 주개 준위 – 원자가 띠 바로 위", "둘 다 띠 간격 한가운데", "둘 다 전도띠 위"], "a": 0, "ex": "원자가 띠의 전자가 받개 준위로 쉽게 올라가 양공을 남기고(P형), 주개 준위의 전자는 전도띠로 쉽게 올라가요(N형).", "ref": ["s2:5", "s2:6"], "s": "phys", "cx": ["받개(P형)는 원자가 띠 바로 위, 주개(N형)는 전도띠 바로 아래예요.", "두 준위가 서로 바뀌었어요.", "도핑 준위는 각 띠 가장자리 가까이에 있어요.", "전도띠 위에 있지 않아요."]}, {"id": "pE1", "u": "PN접합", "t": "essay", "q": "PN 접합에서 공핍층과 내부 전위차가 형성되는 과정을 설명하고, 순방향·역방향 바이어스에서 공핍층과 전류가 어떻게 변하는지 서술하시오.", "kp": ["접합 시 농도 차로 N의 전자 → P, P의 양공 → N 확산 후 재결합", "접합면 근처에 움직일 수 없는 이온만 남음 (N쪽 +, P쪽 −) = 공핍층", "이온에 의한 내부 전기장 → 확산을 막는 내부 전위차(Si 약 0.7 V)", "순방향(P에 +): 장벽 낮아짐, 공핍층 얇아짐 → 전류 흐름", "역방향(P에 −): 공핍층 넓어짐 → 전류 거의 0 (큰 역전압 시 항복)"], "sol": "P형과 N형을 접합하면 농도 차이 때문에 N형의 전자는 P형으로, P형의 양공은 N형으로 확산하여 접합면 근처에서 재결합한다. 그 결과 접합면 부근에는 움직일 수 있는 운반자가 없고 N쪽에 양이온, P쪽에 음이온만 남은 공핍층이 생기며, 이 이온들이 만드는 내부 전기장이 더 이상의 확산을 막는 약 0.7 V의 내부 전위차가 된다. P형에 (+), N형에 (−)를 연결하는 순방향 바이어스에서는 외부 전압이 장벽을 낮춰 공핍층이 얇아지고 전류가 흐르며, 반대로 연결하는 역방향 바이어스에서는 공핍층이 넓어져 전류가 거의 흐르지 않는다(매우 큰 역전압에서는 항복이 일어난다).", "ref": ["s2:9", "s2:10"], "s": "phys", "lv": 0, "ex": null}, {"id": "pE2", "u": "정류·평활", "t": "essay", "q": "브리지 정류회로와 평활 축전기를 이용해 교류를 직류로 바꾸는 원리를 전류 경로와 리플을 포함하여 서술하시오.", "kp": ["다이오드 4개를 브리지로 연결", "(+) 반주기: 한 쌍(대각선 2개)의 다이오드가 켜져 부하에 한 방향 전류", "(−) 반주기: 다른 쌍이 켜지지만 부하에는 같은 방향 전류 → 전파 정류 (출력 전부 +)", "부하에 병렬로 축전기: 전압 상승 시 충전, 하강 시 방전하여 전압 유지", "남는 굴곡 = 리플, $V_{\\text{ripple}} = V_{\\max}-V_{\\min}$, 리플 진동수는 입력의 2배"], "sol": "브리지 정류회로는 다이오드 4개로 이루어진다. 입력의 (+) 반주기에는 대각선 위치의 다이오드 한 쌍이 순방향이 되어 전류가 부하를 한 방향으로 흐르고, (−) 반주기에는 다른 한 쌍이 켜지지만 부하에는 같은 방향으로 전류가 흐르므로 출력은 모두 (+)인 전파 정류 파형이 된다. 여기에 부하와 병렬로 평활 축전기를 연결하면 전압이 올라갈 때 축전기가 충전되고 내려갈 때 부하로 방전하여 출력 전압이 거의 일정한 직류가 된다. 남는 작은 굴곡을 리플($V_{\\text{ripple}} = V_{\\text{max}} − V_{\\text{min}}$)이라 하며, 전파 정류에서는 리플 진동수가 입력의 2배이고 RC가 클수록 리플이 작다.", "ref": ["s2:17", "s2:18", "s2:19"], "s": "phys", "lv": 0, "ex": null}, {"id": "pE3", "u": "도핑", "t": "essay", "q": "Si에 5족 원소를 도핑한 N형 반도체와 3족 원소를 도핑한 P형 반도체에서 각각 주된 전하 운반자가 생기는 원리를 쓰고, 두 반도체가 전기적으로 중성인 이유를 설명하시오.", "kp": ["Si는 원자가 전자 4개로 이웃 4개와 공유결합", "N형: 5족(P 등) 원자가 전자 5개 → 결합에 참여 안 하는 전자 1개 → 전자가 운반자, 주개 준위", "P형: 3족(B 등) 원자가 전자 3개 → 결합 전자 하나 부족 → 양공이 운반자, 받개 준위", "도핑 원자 자체가 중성이므로 전체 양성자 수 = 전자 수", "운반자가 이동해 생긴 이온(P⁺, B⁻)까지 합치면 전체 전하 0"], "sol": "Si는 원자가 전자가 4개로 이웃한 Si 4개와 공유결합을 한다. 5족 원소(P, As)를 넣으면 원자가 전자 5개 중 4개는 결합에 쓰이고 1개가 남아, 이 전자가 전도띠 바로 아래의 주개 준위에서 쉽게 전도띠로 올라가 전하 운반자가 된다(N형). 3족 원소(B, Al)를 넣으면 원자가 전자가 3개뿐이어서 결합에 전자 하나가 부족한 양공이 생기고, 원자가 띠 바로 위 받개 준위로 전자가 올라가면서 양공이 운반자가 된다(P형). 그러나 도핑하는 원자와 Si 모두 전기적으로 중성인 원자이므로 반도체 전체의 양성자 수와 전자 수는 같아 두 반도체 모두 전기적으로 중성이다.", "ref": ["s2:5", "s2:6", "s2:7"], "s": "phys", "lv": 0, "ex": null}, {"id": "pE4", "u": "다이오드 특성", "t": "essay", "q": "다이오드의 근사 모델 세 가지(구간 선형, 고정 전압, 이상적)를 각각 설명하고, 어떤 상황에서 어떤 모델을 쓰는 것이 적절한지 서술하시오.", "kp": ["구간 선형: $V_{\\gamma}$ 전지 + 저항 $R_{f}$ + 이상 다이오드, 켜진 뒤 기울기 $1/R_{f}$", "고정 전압: $V_{\\gamma}$ 전지 + 이상 다이오드, 켜지면 전압이 $V_{\\gamma}$로 고정", "이상적: 0 V에서 바로 켜지고 순방향 단락, 역방향 개방", "전원 전압이 $V_{\\gamma}$보다 훨씬 크면 이상적 모델로 충분", "정밀 계산이나 큰 전류에서는 구간 선형 모델"], "sol": "구간 선형 모델은 다이오드를 턴온 전압 $V_{\\gamma}$의 전지, 순방향 저항 $R_{f}$, 이상 다이오드의 직렬로 근사하며, 켜진 뒤 전류가 기울기 $1/R_{f}$로 증가한다. 고정 전압 모델은 $R_{f}$를 무시하고 $V_{\\gamma}$ 전지와 이상 다이오드로 근사하여, 켜지면 다이오드 전압이 $V_{\\gamma}$로 일정하다. 이상적 모델은 0 V에서 바로 켜져 순방향에서는 단락, 역방향에서는 개방으로 본다. 전원 전압이 $V_{\\gamma}$에 비해 매우 크면 이상적 모델로도 충분하고, 전원 전압이 수 V 정도면 고정 전압 모델이, 더 정밀한 계산이나 전류가 커서 $R_{f}$에 의한 전압 강하를 무시할 수 없을 때는 구간 선형 모델이 적절하다.", "ref": ["s1:2", "s1:3"], "s": "phys", "lv": 0, "ex": null}, {"id": "pE5", "u": "에너지 띠", "t": "essay", "q": "도체, 반도체, 절연체의 차이를 에너지 띠 구조로 설명하고, 온도가 높아질 때 금속과 반도체의 전기 전도도가 반대로 변하는 이유를 서술하시오.", "kp": ["원자가 많이 모이면 준위가 띠를 이룸(원자가 띠, 전도띠, 띠 간격)", "도체: 띠가 겹치거나 전도띠가 일부 채워짐 → 자유 전자 많음", "반도체: 띠 간격 작음 → 열에너지로 일부 전자 들뜸", "절연체: 띠 간격 큼 → 전자가 전도띠로 못 올라감", "온도↑: 금속은 원자 진동↑ → 전자 산란↑ → 전도도↓ / 반도체는 들뜬 운반자 수↑ → 전도도↑"], "sol": "고체에서는 원자들의 에너지 준위가 겹쳐 원자가 띠와 전도띠가 생기고 그 사이에 띠 간격이 존재한다. 도체는 원자가 띠와 전도띠가 겹치거나 전도띠가 일부 채워져 있어 자유롭게 움직이는 전자가 많고, 반도체는 띠 간격이 작아 열에너지 등으로 일부 전자가 전도띠로 들떠 전류가 흐를 수 있으며, 절연체는 띠 간격이 커서 전자가 전도띠로 거의 올라가지 못한다. 온도가 높아지면 금속은 운반자 수는 거의 그대로인데 원자(양이온)의 열진동이 커져 전자가 더 많이 산란되므로 전도도가 감소하고, 반도체는 전도띠로 들뜨는 전자(와 양공)의 수가 크게 늘어 전도도가 증가한다.", "ref": ["s2:3", "s2:4"], "s": "phys", "lv": 0, "ex": null}, {"id": "c01", "u": "열역학 기초", "t": "mc", "lv": 1, "q": "계와 주위 사이에 에너지와 물질을 모두 교환할 수 없는 계의 예로 가장 적절한 것은?", "c": ["우주(근사적으로 밀폐된 진공 단열 플라스크)", "자동차 엔진", "전지", "열린 플라스크"], "a": 0, "ex": "열린계: 에너지 ○ 물질 ○ (엔진, 사람, 열린 플라스크) / 닫힌계: 에너지 ○ 물질 ✗ (전지, 냉찜질팩, 밀폐 플라스크) / 고립계: 둘 다 ✗ (우주).", "ref": ["q:3", "nc:n1"], "s": "chem", "cx": ["고립계예요. 단열·밀폐된 진공 플라스크(또는 우주)는 에너지와 물질을 모두 주고받지 않아요.", "엔진은 연료·배기가스(물질)와 열·일(에너지)을 주고받는 열린계예요.", "전지는 물질은 막혀 있지만 전기 에너지를 주고받는 닫힌계예요.", "열린 플라스크는 물질과 에너지를 모두 주고받는 열린계예요."]}, {"id": "c02", "u": "열역학 기초", "t": "mc", "lv": 1, "q": "다음 중 세기 성질(intensive property)이 아닌 것은?", "c": ["부피", "온도", "압력", "밀도"], "a": 0, "ex": "크기 성질은 물질의 양에 비례해요(부피, 질량, U, H…). 세기 성질은 양과 무관해요(T, P, 밀도).", "ref": ["q:3", "q:4"], "s": "chem", "cx": ["부피는 양에 비례하는 크기 성질이에요 → \"세기 성질이 아닌 것\"으로 정답이에요.", "온도는 양과 무관한 세기 성질이에요.", "압력은 세기 성질이에요.", "밀도 = 질량/부피(크기÷크기)라 세기 성질이에요."]}, {"id": "c03", "u": "열역학 기초", "t": "mc", "lv": 1, "q": "다음 중 경로함수인 것만 고른 것은?", "c": ["q, w", "U, H", "S, G", "P, V, T"], "a": 0, "ex": "일(w)과 열(q)은 경로에 따라 달라지는 경로함수예요. 하지만 그 합 q + w = ΔU는 경로와 무관해요.", "ref": ["q:5", "nc:n1"], "s": "chem", "cx": ["열(q)과 일(w)은 경로에 따라 값이 달라지는 경로함수예요.", "U, H는 상태함수예요.", "S, G는 상태함수예요.", "P, V, T는 상태를 나타내는 변수(상태함수)예요."]}, {"id": "c04", "u": "열역학 기초", "t": "mc", "lv": 1, "q": "가역과정에 대한 설명으로 옳지 않은 것은?", "c": ["자발적으로 일어나는 실제 변화는 대부분 가역과정이다", "외부 조건을 무한히 작게 바꾸어도 진행 방향을 바꿀 수 있다", "일련의 연속적인 평형 상태를 거치므로 경로로 표현할 수 있다", "매우 느리게 진행시키면 실제 과정을 가역과정으로 근사할 수 있다"], "a": 0, "ex": "자발적으로 일어나는 변화는 모두 비가역과정이에요.", "ref": ["q:4"], "s": "chem", "cx": ["실제 자발적 변화는 대부분 비가역이에요 → 옳지 않은 설명이라 정답이에요.", "가역과정의 정의 그대로예요(옳은 설명).", "평형 상태를 연속적으로 거치므로 경로로 그릴 수 있어요(옳은 설명).", "준정적으로 느리게 하면 가역에 가까워져요(옳은 설명)."]}, {"id": "c05", "u": "제1법칙·열용량", "t": "mc", "lv": 1, "q": "열역학 제1법칙 $\\Delta U = q + w$ 에서 계가 외부 압력에 대항해 팽창할 때의 부호로 옳은 것은?", "c": ["$\\Delta V>0$이므로 $w<0$ (계가 일을 함)", "$\\Delta V>0$이므로 $w>0$", "$w$는 항상 0", "$q$는 항상 음수"], "a": 0, "ex": "$w=-P_{ex}\\Delta V$. 팽창하면 $\\Delta V>0$이므로 $w<0$, 압축하면 $w>0$(주위가 계에 일을 함)이에요.", "ref": ["q:5", "q:6"], "s": "chem", "cx": ["$w=-P_{ext}\\\\Delta V$이고 $\\\\Delta V>0$이면 $w<0$ → 계가 일을 해 에너지를 잃어요.", "부호가 반대예요. 팽창하면 $w<0$이에요.", "부피가 변하므로 일은 0이 아니에요.", "q의 부호는 열 출입에 따라 정해져요. 팽창과는 무관해요."]}, {"id": "c06", "u": "제1법칙·열용량", "t": "mc", "lv": 1, "q": "봄 열량계(일정 부피 열량계)에서 측정한 열량은 어떤 양과 같은가?", "c": ["$\\Delta U$ (내부에너지 변화)", "$\\Delta H$", "$\\Delta G$", "$T\\Delta S$"], "a": 0, "ex": "부피가 일정하면 $w=0$이므로 $\\Delta U=q_v$예요. 커피컵(일정 압력) 열량계는 $q_p=\\Delta H$예요.", "ref": ["q:8", "nc:n2"], "s": "chem", "cx": ["부피가 일정하면 $w=0$이라 $q_v=\\\\Delta U$예요.", "$\\\\Delta H$는 일정 압력 열량계(커피컵)에서 재요($q_p$).", "$\\\\Delta G$는 열량계로 직접 측정하지 않아요.", "$T\\\\Delta S$는 가역 열($q_{rev}$)이지 봄 열량이 아니에요."]}, {"id": "c07", "u": "제1법칙·열용량", "t": "mc", "lv": 1, "q": "기체에서 정압 몰열용량 $c_p$가 정적 몰열용량 $c_v$보다 큰 이유는?", "c": ["일정 압력에서는 가한 에너지 일부가 외부 압력에 대해 팽창하는 일에 쓰이기 때문", "일정 부피에서는 분자의 회전이 멈추기 때문", "일정 압력에서는 분자 수가 늘어나기 때문", "정적 과정에서 열이 더 많이 빠져나가기 때문"], "a": 0, "ex": "이상기체에서 $c_p-c_v=R$이에요. 단원자 이상기체는 $c_v=\\tfrac32R$, $c_p=\\tfrac52R$이에요.", "ref": ["q:7", "q:11", "nc:n1"], "s": "chem", "cx": ["정압에서는 열의 일부가 팽창 일($P\\\\Delta V$)로 쓰여 같은 ΔT에 열이 더 필요해요 → $c_p=c_v+R$이에요.", "정적 조건에서도 회전은 멈추지 않아요.", "가열한다고 분자 수가 늘지 않아요.", "정적 과정에서는 오히려 열이 모두 내부에너지가 돼요."]}, {"id": "c08", "u": "제1법칙·열용량", "t": "num", "lv": 2, "q": "298 K, 1기압의 아르곤 2.00 mol에 일정 압력에서 1.00 kJ의 열을 가했다. 온도 변화 $\\Delta T$는 몇 K인가? (Ar은 단원자 이상기체, $c_p=20.79$ J/K·mol)", "a": 24.05, "tol": 0.02, "unit": "K", "ex": "$q_p=nc_p\\Delta T$ → $\\Delta T = \\dfrac{1000}{2.00\\times20.79}=24.0$ K.", "ref": ["q:12"], "s": "chem"}, {"id": "c09", "u": "제1법칙·열용량", "t": "num", "lv": 2, "q": "위 문제(Ar 2.00 mol, 일정 압력에서 1.00 kJ 공급)에서 내부에너지 변화 $\\Delta U$는 몇 J인가? ($c_v=12.47$ J/K·mol)", "a": 600.0, "tol": 0.02, "unit": "J", "ex": "$\\Delta U=nc_v\\Delta T=2.00\\times12.47\\times24.05\\approx600$ J. 나머지 400 J은 팽창하며 한 일이에요.", "sol": "$\\Delta U = q + w$ → $w = 600-1000 = -400$ J. 일정 부피였다면 $\\Delta U=q_v=1000$ J, $\\Delta T=40.1$ K였을 거예요.", "ref": ["q:12"], "s": "chem"}, {"id": "c10", "u": "제1법칙·열용량", "t": "num", "lv": 2, "q": "일정 부피 열량계에 12 V 전원으로 10 A의 전류를 300초 동안 흘렸더니 온도가 5.5 K 올라갔다. 이 열량계의 열용량은 몇 kJ/K인가?", "a": 6.55, "tol": 0.02, "unit": "kJ/K", "ex": "$q=VIt=12\\times10\\times300=36$ kJ, $C=\\dfrac{36}{5.5}=6.5$ kJ/K예요. 부피가 일정하므로 $\\Delta U=36$ kJ이에요.", "ref": ["q:8"], "s": "chem"}, {"id": "c11", "u": "제1법칙·열용량", "t": "num", "lv": 2, "q": "반응 $\\mathrm{N_2(g)+3H_2(g)\\to 2NH_3(g)}$ 가 298 K에서 일어날 때 $\\Delta H-\\Delta U$는 몇 kJ인가? ($R=8.314$ J/K·mol)", "a": -4.955, "tol": 0.02, "unit": "kJ", "ex": "$\\Delta H=\\Delta U+\\Delta n_gRT$, $\\Delta n_g=2-4=-2$ → $-2\\times8.314\\times298=-4955$ J ≈ $-4.96$ kJ.", "ref": ["q:9", "q:10", "nc:n2"], "s": "chem"}, {"id": "c12", "u": "제1법칙·열용량", "t": "num", "lv": 3, "q": "1.0 mol의 calcite가 aragonite로 변할 때(1.0 bar) $\\Delta H-\\Delta U$는 몇 J인가? (밀도: calcite 2.71 g/cm³, aragonite 2.93 g/cm³, CaCO₃ 몰질량 100 g/mol, 1 bar = 10⁵ Pa)", "a": -0.277, "tol": 0.05, "unit": "J", "ex": "$V_{cal}=100/2.71=36.90$ cm³, $V_{ara}=100/2.93=34.13$ cm³, $\\Delta V=-2.77$ cm³ → $P\\Delta V=10^5\\times(-2.77\\times10^{-6})=-0.28$ J.", "sol": "$\\Delta U=+0.21$ kJ에 비하면 0.1% 정도밖에 안 돼요. <b>고체·액체만 관여하면 $\\Delta H\\approx\\Delta U$</b>예요.", "ref": ["q:10"], "s": "chem"}, {"id": "c13", "u": "제1법칙·열용량", "t": "num", "lv": 3, "q": "1.0 atm에서 끓는 물에 담근 저항에 12 V, 0.50 A의 전류를 300초 동안 흘렸더니 0.798 g의 물이 증발했다. 몰 증발 엔탈피 $\\Delta H_m$은 몇 kJ/mol인가? (물 18 g/mol)", "a": 40.6, "tol": 0.02, "unit": "kJ/mol", "ex": "$q=12\\times0.50\\times300=1800$ J, $n=0.798/18=0.04433$ mol → $\\Delta H_m=1800/0.04433=40.6$ kJ/mol.", "ref": ["q:10"], "s": "chem"}, {"id": "c14", "u": "제1법칙·열용량", "t": "num", "lv": 3, "q": "위 문제에서 373.15 K에서의 몰 내부에너지 변화 $\\Delta U_m$은 몇 kJ/mol인가? (수증기는 이상기체, $R=8.314$)", "a": 37.5, "tol": 0.02, "unit": "kJ/mol", "ex": "$\\Delta U_m=\\Delta H_m-\\Delta n_gRT=40.6-1\\times8.314\\times373.15\\times10^{-3}=40.6-3.10=37.5$ kJ/mol.", "ref": ["q:10"], "s": "chem"}, {"id": "c15", "u": "이상기체 과정", "t": "num", "lv": 2, "q": "273 K로 일정하게 유지하면서 10.0 mol의 이상기체가 2.0 atm에서 1.0 atm으로 가역 팽창하였다. 계가 받은 일 $w$는 몇 kJ인가? ($R=8.314$)", "a": -15.73, "tol": 0.02, "unit": "kJ", "ex": "$w=-nRT\\ln\\dfrac{V_2}{V_1}=-nRT\\ln\\dfrac{P_1}{P_2}=-10\\times8.314\\times273\\times\\ln2=-15.7$ kJ. 등온이므로 $q=+15.7$ kJ.", "ref": ["q:14", "q:15"], "s": "chem"}, {"id": "c16", "u": "이상기체 과정", "t": "num", "lv": 2, "q": "298 K에서 5.00 mol의 이상기체가 10.0 atm에서 1.00 atm으로 가역 등온 팽창할 때 흡수한 열 $q$는 몇 kJ인가? ($R=8.315$)", "a": 28.5, "tol": 0.02, "unit": "kJ", "ex": "$w=-nRT\\ln10=-5\\times8.315\\times298\\times2.303=-28.5$ kJ, 등온 이상기체는 $\\Delta U=0$이므로 $q=-w=+28.5$ kJ.", "ref": ["q:17", "q:18"], "s": "chem"}, {"id": "c17", "u": "이상기체 과정", "t": "num", "lv": 3, "q": "298 K, 10.0 atm의 단원자 이상기체 5.00 mol이 1.00 atm까지 가역 단열 팽창하였다. 최종 온도는 약 몇 K인가?", "a": 118.6, "tol": 0.02, "unit": "K", "ex": "단열 가역: $T_2=T_1\\left(\\dfrac{P_2}{P_1}\\right)^{(\\gamma-1)/\\gamma}=298\\times(0.1)^{0.4}=119$ K ($\\gamma=5/3$).", "sol": "$TV^{\\gamma-1}$ = 일정, 또는 $T^{\\gamma}P^{1-\\gamma}$ = 일정에서 $\\dfrac{\\gamma-1}{\\gamma}=\\dfrac{2/3}{5/3}=0.4$. 이때 $V_1=12.2$ L, $V_2=48.7$ L예요.", "ref": ["q:16", "q:17", "q:18"], "s": "chem"}, {"id": "c18", "u": "이상기체 과정", "t": "num", "lv": 3, "q": "위 가역 단열 팽창(5.00 mol, 298 K → 119 K)에서 계가 받은 일 $w$는 몇 kJ인가? ($c_v=\\tfrac32R$, $R=8.315$)", "a": -11.2, "tol": 0.02, "unit": "kJ", "ex": "$q=0$이므로 $w=\\Delta U=nc_v\\Delta T=5\\times12.47\\times(119-298)=-11.2$ kJ. 등온(−28.5 kJ)의 약 40%예요.", "ref": ["q:18"], "s": "chem"}, {"id": "c19", "u": "이상기체 과정", "t": "mc", "lv": 2, "q": "같은 초기 상태(298 K, 10 atm)에서 같은 최종 압력(1 atm)까지 가역 등온 팽창과 가역 단열 팽창을 비교한 것으로 옳은 것은?", "c": ["최종 부피는 등온 팽창이 더 크고, 계가 한 일의 크기도 등온 팽창이 더 크다", "최종 부피는 단열 팽창이 더 크다", "단열 팽창에서는 온도가 일정하다", "두 과정에서 한 일의 크기는 같다"], "a": 0, "ex": "등온은 $V_2=122$ L, $|w|=28.5$ kJ이고, 단열은 $V_2=48.7$ L, $|w|=11.2$ kJ이에요. γ>1이라 단열선이 더 가파르게 떨어지고, 단열에서는 열이 들어오지 않아 내부에너지로 일을 하므로 온도가 내려가요.", "ref": ["q:18"], "s": "chem", "cx": ["단열 팽창은 온도가 내려가 최종 부피가 작아요 → 등온 쪽의 부피와 일(P–V 아래 넓이)이 더 커요.", "단열은 냉각되어 부피가 더 작아요.", "단열 팽창에서는 q=0이고 온도가 내려가요.", "P–V 곡선 아래 넓이가 달라 일이 달라요."]}, {"id": "c20", "u": "이상기체 과정", "t": "num", "lv": 3, "q": "단원자 이상기체가 상태 A(2 atm, 10 L)에서 상태 B(1 atm, 30 L)로 변한다. 경로와 무관한 $\\Delta U$는 몇 J인가? (1 L·atm = 101.3 J)", "a": 1520.0, "tol": 0.02, "unit": "J", "ex": "$\\Delta U=\\tfrac32 nR\\Delta T=\\tfrac32(P_BV_B-P_AV_A)=\\tfrac32(30-20)=15$ L·atm ≈ 1520 J.", "ref": ["q:13"], "s": "chem"}, {"id": "c21", "u": "이상기체 과정", "t": "num", "lv": 3, "q": "위 문제에서 경로 ADB(일정 부피에서 압력을 1 atm까지 냉각 → 일정 압력 1 atm에서 30 L까지 가열)로 갈 때 계가 흡수한 열 $q$는 몇 J인가? (1 L·atm = 101.3 J)", "a": 3546.0, "tol": 0.02, "unit": "J", "ex": "$w=-1\\ \\text{atm}\\times(30-10)\\text{ L}=-20$ L·atm, $q=\\Delta U-w=15+20=35$ L·atm ≈ 3550 J. 경로 ACB에서는 $q=55$ L·atm(5570 J)이라 경로마다 달라요.", "ref": ["q:13"], "s": "chem"}, {"id": "c22", "u": "이상기체 과정", "t": "num", "lv": 3, "q": "10 atm, 1 L의 이상기체가 일정 온도에서 1 atm, 10 L로 \"가역\" 팽창할 때 계가 받은 일은 몇 L·atm인가? (소수 첫째 자리)", "a": -23.0, "tol": 0.02, "unit": "L·atm", "ex": "$w=-nRT\\ln\\dfrac{V_2}{V_1}=-P_1V_1\\ln10=-10\\ln10=-23.0$ L·atm. 외부 압력 1 atm에 대항한 비가역 팽창은 $-1\\times9=-9$ L·atm이라, 가역일 때 한 일이 가장 커요.", "ref": ["nc:n1", "q:15"], "s": "chem"}, {"id": "c23", "u": "반응엔탈피·헤스", "t": "mc", "lv": 1, "q": "표준 생성 엔탈피($\\Delta H_f^\\circ$)가 0이 아닌 것은?", "c": ["$\\mathrm{C}$(다이아몬드)", "$\\mathrm{C}$(흑연)", "$\\mathrm{O_2(g)}$", "$\\mathrm{Br_2(l)}$"], "a": 0, "ex": "표준 상태에서 가장 안정한 형태의 원소만 ΔHf° = 0이에요. 탄소는 흑연이 기준이라 다이아몬드는 0이 아니에요.", "ref": ["q:19", "nc:n2"], "s": "chem", "cx": ["표준 상태에서 가장 안정한 탄소는 흑연이에요. 다이아몬드는 ΔHf° ≈ +1.9 kJ/mol이에요.", "흑연은 탄소의 표준 상태라 0이에요.", "O₂(g)는 산소의 표준 상태라 0이에요.", "Br₂는 상온에서 액체가 표준 상태라 0이에요."]}, {"id": "c24", "u": "반응엔탈피·헤스", "t": "num", "lv": 2, "q": "포도당 발효 $\\mathrm{C_6H_{12}O_6(s)\\to 2C_2H_5OH(l)+2CO_2(g)}$ 의 $\\Delta H^\\circ$는 몇 kJ인가? ($\\Delta H_f^\\circ$: 포도당 −1260, 에탄올 −277.7, CO₂ −393.5 kJ/mol)", "a": -82.4, "tol": 0.01, "unit": "kJ", "ex": "$\\Delta H^\\circ=[2(-277.7)+2(-393.5)]-(-1260)=-82.4$ kJ이므로 발열반응이에요.", "ref": ["q:19"], "s": "chem"}, {"id": "c25", "u": "반응엔탈피·헤스", "t": "num", "lv": 2, "q": "$\\mathrm{C(s)+\\tfrac12O_2\\to CO}$ ΔH = −110.5 kJ, $\\mathrm{CO+\\tfrac12O_2\\to CO_2}$ ΔH = −283.0 kJ일 때, $\\mathrm{C(s)+O_2\\to CO_2}$ 의 ΔH는 몇 kJ인가?", "a": -393.5, "tol": 0.005, "unit": "kJ", "ex": "헤스 법칙(엔탈피는 상태함수): −110.5 + (−283.0) = −393.5 kJ.", "ref": ["q:21", "nc:n2"], "s": "chem"}, {"id": "c26", "u": "반응엔탈피·헤스", "t": "num", "lv": 2, "q": "평균 결합 엔탈피(C–H 410, Cl–Cl 243, C–Cl 330, H–Cl 432 kJ/mol)를 이용해 $\\mathrm{CH_4+3Cl_2\\to CHCl_3+3HCl}$ 의 ΔH를 구하면 몇 kJ인가?", "a": -327.0, "tol": 0.01, "unit": "kJ", "ex": "끊어지는 결합: 3 C–H + 3 Cl–Cl = 1230 + 729 = 1959. 생성되는 결합: 3 C–Cl + 3 H–Cl = 990 + 1296 = 2286. ΔH = 1959 − 2286 = −327 kJ.", "sol": "공식: $\\Delta H=\\sum D(\\text{반응물})-\\sum D(\\text{생성물})$ ← <b>생성 엔탈피 공식과 순서가 반대</b>! (C–H 1개는 그대로 남으니 양쪽에서 빼도 같아요: 2369 − 2696 = −327)", "ref": ["q:22"], "s": "chem"}, {"id": "c27", "u": "반응엔탈피·헤스", "t": "mc", "lv": 1, "q": "결합 엔탈피를 이용한 반응 엔탈피 계산식으로 옳은 것은?", "c": ["ΔH = Σ(반응물의 결합 엔탈피) − Σ(생성물의 결합 엔탈피)", "ΔH = Σ(생성물의 결합 엔탈피) − Σ(반응물의 결합 엔탈피)", "ΔH = Σ(생성물 ΔHf°) + Σ(반응물 ΔHf°)", "ΔH = Σ(반응물 ΔHf°) − Σ(생성물 ΔHf°)"], "a": 0, "ex": "결합을 끊을 때 흡수(+), 만들 때 방출(−)이므로 반응물 − 생성물이에요. 생성 엔탈피는 생성물 − 반응물이니 헷갈리지 마세요.", "ref": ["q:22"], "s": "chem", "cx": ["결합을 끊는 데 에너지가 들고(+) 만들면 방출(−)돼요 → 반응물 − 생성물이에요.", "생성 엔탈피 식과 헷갈렸어요. 결합 엔탈피는 반대예요.", "두 항을 더하면 안 돼요.", "생성 엔탈피는 생성물 − 반응물이에요."]}, {"id": "c28", "u": "반응엔탈피·헤스", "t": "mc", "lv": 1, "q": "강산과 강염기의 중화 엔탈피가 산·염기의 종류와 관계없이 거의 일정한 이유는?", "c": ["알짜 이온 반응식이 H⁺ + OH⁻ → H₂O 로 같기 때문", "모든 산의 몰질량이 같기 때문", "물의 비열이 크기 때문", "중화 반응은 흡열 반응이기 때문"], "a": 0, "ex": "강산–강염기는 완전히 이온화하므로 알짜 반응이 같아요. 중화 엔탈피는 약 −57.7 kJ/mol(자료 기준)로 일정해요.", "ref": ["q:20"], "s": "chem", "cx": ["강산·강염기는 완전히 이온화하고 구경꾼 이온을 빼면 H⁺+OH⁻→H₂O 하나라 약 −56 kJ/mol로 같아요.", "산마다 몰질량이 달라요.", "비열은 온도 변화량에 영향을 줄 뿐 몰당 ΔH와는 무관해요.", "중화는 발열 반응이에요."]}, {"id": "c29", "u": "엔트로피·제2법칙", "t": "mc", "lv": 1, "q": "다음 중 계의 엔트로피가 감소하는 과정은?", "c": ["$\\mathrm{N_2(g)+3H_2(g)\\to 2NH_3(g)}$", "얼음이 녹는 과정", "NaCl(s)이 물에 용해", "기체의 자유 팽창"], "a": 0, "ex": "기체 몰수가 4 → 2로 감소하므로 ΔS < 0이에요. 고체 → 액체 → 기체, 용해, 확산, 기체 몰수 증가는 ΔS > 0이에요.", "ref": ["q:24", "q:35"], "s": "chem", "cx": ["기체 4 mol → 2 mol로 줄어 무질서도가 감소해요(ΔS<0).", "고체 → 액체는 엔트로피가 증가해요.", "이온이 퍼져 엔트로피가 증가해요.", "부피가 늘어 엔트로피가 증가해요."]}, {"id": "c30", "u": "엔트로피·제2법칙", "t": "num", "lv": 2, "q": "이상기체 1 mol이 일정 온도에서 부피가 2배로 가역 팽창할 때 계의 엔트로피 변화는 몇 J/K인가? ($R=8.314$)", "a": 5.763, "tol": 0.02, "unit": "J/K", "ex": "$\\Delta S=nR\\ln\\dfrac{V_2}{V_1}=8.314\\ln2=5.76$ J/K. 볼츠만 식 $S=k\\ln W$로 구해도 같아요.", "ref": ["q:26", "q:31"], "s": "chem"}, {"id": "c31", "u": "엔트로피·제2법칙", "t": "num", "lv": 2, "q": "0 ℃에서 물의 몰 융해 엔탈피가 6.01 kJ/mol일 때 몰 융해 엔트로피는 몇 J/K·mol인가?", "a": 22.0, "tol": 0.02, "unit": "J/K·mol", "ex": "$\\Delta S=\\dfrac{\\Delta H}{T}=\\dfrac{6010}{273.15}=22.0$ J/K·mol (정상 녹는점에서 가역 상전이).", "ref": ["q:31", "q:32"], "s": "chem"}, {"id": "c32", "u": "엔트로피·제2법칙", "t": "num", "lv": 2, "q": "브롬은 59.2 ℃에서 끓는다. 트루톤 규칙(몰 증발 엔트로피 ≈ 85 J/K·mol)으로 추정한 표준 몰 증발 엔탈피는 약 몇 kJ/mol인가?", "a": 28.2, "tol": 0.04, "unit": "kJ/mol", "ex": "$\\Delta H_{vap}\\approx85\\times(59.2+273.15)=85\\times332.35=28.2$ kJ/mol.", "ref": ["q:32"], "s": "chem"}, {"id": "c33", "u": "엔트로피·제2법칙", "t": "mc", "lv": 1, "q": "물이 트루톤 규칙에서 크게 벗어나는(약 109 J/K·mol) 이유는?", "c": ["액체 상태에서 수소결합으로 분자 배열이 질서 있어 증발 시 엔트로피 증가가 크기 때문", "물의 몰질량이 작기 때문", "물의 끓는점이 낮기 때문", "수증기가 이상기체가 아니기 때문"], "a": 0, "ex": "수소결합 때문에 액체 물이 상대적으로 질서 정연해서 기체가 될 때 엔트로피가 더 많이 증가해요.", "ref": ["q:32"], "s": "chem", "cx": ["수소결합 때문에 액체가 이미 질서 있어서 기체로 바뀔 때 ΔS가 평균(약 88)보다 커요.", "몰질량은 트루톤 규칙 이탈의 원인이 아니에요.", "물의 끓는점(100 ℃)은 비슷한 분자량에 비해 오히려 높아요.", "이상기체가 아닌 것은 이탈의 주된 원인이 아니에요."]}, {"id": "c34", "u": "엔트로피·제2법칙", "t": "num", "lv": 3, "q": "25 ℃, 1.00 atm에서 500 cm³ 용기 속의 Ar을 1000 cm³로 팽창시키면서 동시에 100 ℃로 가열했다. 엔트로피 변화는 몇 J/K인가? ($c_v=\\tfrac32R$)", "a": 0.175, "tol": 0.03, "unit": "J/K", "ex": "$n=PV/RT=0.0204$ mol, $\\Delta S=n\\left[R\\ln2+\\tfrac32R\\ln\\dfrac{373.15}{298.15}\\right]=0.0204\\times(5.76+2.80)=0.175$ J/K.", "sol": "상태함수이므로 ① 등온 팽창 + ② 정적 가열 두 단계로 나누어 더해요.", "ref": ["q:33"], "s": "chem"}, {"id": "c35", "u": "엔트로피·제2법칙", "t": "num", "lv": 3, "q": "25 ℃에서 $\\mathrm{CH_4(g)+2O_2(g)\\to CO_2(g)+2H_2O(l)}$ 의 표준 반응 엔트로피는 몇 J/K인가? (S°: CH₄ 186.3, O₂ 205.1, CO₂ 213.7, H₂O(l) 69.9 J/K·mol)", "a": -243.0, "tol": 0.01, "unit": "J/K", "ex": "$\\Delta S^\\circ=(213.7+2\\times69.9)-(186.3+2\\times205.1)=353.5-596.5=-243$ J/K (자료 답 −242.8). 기체 3 mol → 1 mol이라 음수예요.", "ref": ["q:35", "q:36"], "s": "chem"}, {"id": "c36", "u": "엔트로피·제2법칙", "t": "mc", "lv": 1, "q": "열역학 제3법칙의 내용으로 옳은 것은?", "c": ["완전결정의 엔트로피는 0 K에 가까워지면 0에 근접한다", "고립계의 엔트로피는 자발적 변화에서 감소한다", "우주의 에너지는 일정하다", "모든 물질의 표준 몰 엔트로피는 음수가 될 수 있다"], "a": 0, "ex": "그래서 물질의 절대 엔트로피를 정할 수 있어요. 수용액 이온의 S°는 H⁺(aq)를 기준으로 한 상대값이라 음수일 수 있어요(예 Ca²⁺ −53.1).", "ref": ["q:35"], "s": "chem", "cx": ["완전결정은 0 K에서 배열이 한 가지(W=1)라 S=k ln1=0이에요.", "고립계 자발 변화에서 엔트로피는 증가해요(제2법칙).", "에너지 보존은 제1법칙이에요.", "3법칙 기준 표준 몰 엔트로피(절대 엔트로피)는 항상 양수예요."]}, {"id": "c37", "u": "엔트로피·제2법칙", "t": "mc", "lv": 2, "q": "주위의 엔트로피 변화에 대한 설명으로 옳은 것은?", "c": ["$\\Delta S_{surr}=-\\Delta H_{sys}/T$ 이며, 주위 온도가 낮을수록 같은 열에 의한 엔트로피 변화가 크다", "발열 과정에서 주위의 엔트로피는 감소한다", "$\\Delta S_{surr}$는 온도와 무관하다", "흡열 과정에서 주위의 엔트로피는 증가한다"], "a": 0, "ex": "발열이면 주위가 열을 받아 $\\Delta S_{\\text{surr}} > 0$이에요. 조용한 도서관의 재채기처럼, 온도가 낮을수록 같은 열의 영향이 커요.", "ref": ["q:34"], "s": "chem", "cx": ["$\\\\Delta S_{surr}=-\\\\Delta H_{sys}/T$ → 같은 열이라도 T가 작을수록 효과가 커요.", "발열이면 주위가 열을 받아 엔트로피가 증가해요.", "T로 나누므로 온도에 따라 달라요.", "흡열이면 주위가 열을 잃어 엔트로피가 감소해요."]}, {"id": "c38", "u": "카르노", "t": "num", "lv": 2, "q": "500 K의 고온 열원과 300 K의 저온 열원 사이에서 작동하는 가역 카르노 기관의 효율은 몇 %인가?", "a": 40.0, "tol": 0.01, "unit": "%", "ex": "$\\eta=1-\\dfrac{T_c}{T_h}=1-\\dfrac{300}{500}=0.40$ → 40%.", "ref": ["q:30"], "s": "chem"}, {"id": "c39", "u": "카르노", "t": "num", "lv": 2, "q": "600 K 고온 열원에서 1000 J의 열을 흡수하고 300 K 저온 열원으로 열을 버리는 가역 카르노 기관이 한 순환 동안 하는 일의 크기는 몇 J인가?", "a": 500.0, "tol": 0.01, "unit": "J", "ex": "$\\eta=1-300/600=0.5$ → $|w|=0.5\\times1000=500$ J. 저온 열원으로 500 J을 버려요.", "ref": ["q:30", "q:27"], "s": "chem"}, {"id": "c40", "u": "카르노", "t": "mc", "lv": 1, "q": "카르노 순환을 이루는 네 과정의 순서로 옳은 것은?", "c": ["등온 가역 팽창 → 단열 가역 팽창 → 등온 가역 압축 → 단열 가역 압축", "단열 팽창 → 등온 팽창 → 단열 압축 → 등온 압축", "등온 팽창 → 등온 압축 → 단열 팽창 → 단열 압축", "정적 가열 → 등압 팽창 → 정적 냉각 → 등압 압축"], "a": 0, "ex": "A→B 등온 팽창(Th, 열 흡수) → B→C 단열 팽창(Th→Tc) → C→D 등온 압축(Tc, 열 방출) → D→A 단열 압축(Tc→Th) 순서예요.", "ref": ["q:27"], "s": "chem", "cx": ["등온 팽창(고온에서 흡열) → 단열 팽창(냉각) → 등온 압축(저온에서 방열) → 단열 압축(가열)이에요.", "등온과 단열의 순서가 섞였어요.", "팽창과 압축이 번갈아 나와야 닫힌 순환이 돼요.", "오토/디젤류 순환에 가까워요. 카르노가 아니에요."]}, {"id": "c41", "u": "카르노", "t": "mc", "lv": 2, "q": "카르노 순환에서 $\\oint \\dfrac{dq_{rev}}{T}=0$ 이라는 결과가 의미하는 것은?", "c": ["$q_{rev}/T$는 상태함수 → 엔트로피의 열역학적 정의($dS=dq_{rev}/T$)의 근거", "q는 상태함수이다", "카르노 기관의 효율은 100%이다", "순환 과정에서 일은 0이다"], "a": 0, "ex": "q 자체는 경로함수지만, 순환에서 qrev/T의 합이 0이므로 qrev/T는 상태함수예요. 이것이 클라우지우스의 엔트로피 정의예요.", "ref": ["q:30"], "s": "chem", "cx": ["한 바퀴 적분이 0 → $q_{rev}/T$는 경로와 무관한 상태함수(엔트로피)예요.", "q 자체는 경로함수예요.", "카르노 효율은 $1-T_C/T_H<1$이에요.", "순환해도 일은 P–V 폐곡선의 넓이만큼 0이 아니에요."]}, {"id": "c42", "u": "깁스 자유에너지", "t": "mc", "lv": 1, "q": "ΔH > 0, ΔS > 0인 반응이 자발적으로 일어나는 조건은?", "c": ["$T>\\Delta H/\\Delta S$ (높은 온도)", "$T<\\Delta H/\\Delta S$ (낮은 온도)", "모든 온도", "어떤 온도에서도 비자발"], "a": 0, "ex": "ΔG = ΔH − TΔS < 0이려면 TΔS가 ΔH보다 커야 하므로 고온에서 자발적이에요.", "sol": "<table class=\"t\"><tr><th>ΔH</th><th>ΔS</th><th>자발</th></tr><tr><td>−</td><td>+</td><td>항상</td></tr><tr><td>+</td><td>−</td><td>절대 ✗</td></tr><tr><td>−</td><td>−</td><td>저온 (T &lt; T*)</td></tr><tr><td>+</td><td>+</td><td>고온 (T &gt; T*)</td></tr></table>", "ref": ["q:41"], "s": "chem", "cx": ["ΔG=ΔH−TΔS<0 → T가 ΔH/ΔS보다 클 때 자발이에요.", "부등호가 반대예요. 낮은 온도에서는 ΔH가 이겨서 비자발이에요.", "ΔH>0이므로 낮은 온도에서는 비자발이에요.", "ΔS>0이라 고온에서는 자발이에요."]}, {"id": "c43", "u": "깁스 자유에너지", "t": "num", "lv": 2, "q": "하버 공정 $\\mathrm{N_2+3H_2\\to2NH_3}$ 에서 ΔH° = −92.2 kJ, ΔS° = −198.7 J/K일 때 25 ℃에서의 ΔG°는 몇 kJ인가?", "a": -32.96, "tol": 0.015, "unit": "kJ", "ex": "$\\Delta G^\\circ=-92.2-298.15\\times(-0.1987)=-33.0$ kJ < 0 → 자발적. 단위(J↔kJ)를 맞추는 것에 주의하세요.", "ref": ["q:39"], "s": "chem"}, {"id": "c44", "u": "깁스 자유에너지", "t": "num", "lv": 2, "q": "어떤 반응의 ΔH° = +178 kJ, ΔS° = +161 J/K이다. 이 반응이 자발적으로 되기 시작하는 온도 T*는 약 몇 K인가?", "a": 1106.0, "tol": 0.01, "unit": "K", "ex": "$T^*=\\Delta H/\\Delta S=178000/161=1106$ K. 둘 다 양수이므로 T* 이상에서 자발적이에요.", "ref": ["q:41"], "s": "chem"}, {"id": "c45", "u": "깁스 자유에너지", "t": "num", "lv": 3, "q": "물이 −10 ℃(263.15 K)에서 얼 때 ΔH = −6.01 kJ/mol, ΔS = −22.0 J/K·mol로 일정하다고 가정하면 ΔG는 몇 J/mol인가?", "a": -221.0, "tol": 0.05, "unit": "J/mol", "ex": "$\\Delta G=-6010-263.15\\times(-22.0)=-6010+5789=-221$ J/mol < 0 → 자발적으로 얼어요(자료 −220 J). 0 ℃에서는 ΔG = 0(평형)이에요.", "ref": ["q:38"], "s": "chem"}, {"id": "c46", "u": "깁스 자유에너지", "t": "mc", "lv": 1, "q": "ΔG°에 대한 설명으로 옳지 않은 것은?", "c": ["ΔG° < 0이면 반응이 빠르게 일어난다", "ΔG° < 0이면 정반응 쪽으로 진행해 생성물이 더 많아진다", "가장 안정한 원소의 ΔGf° = 0이다", "ΔGf° < 0인 물질은 성분 원소에 대해 열역학적으로 안정하다"], "a": 0, "ex": "ΔG°는 반응의 방향(자발성)만 알려 주고, 속도(활성화 에너지)에 대한 정보는 주지 않아요.", "ref": ["q:39", "q:40"], "s": "chem", "cx": ["ΔG°는 방향·평형만 알려주고 속도는 알려주지 않아요(속도는 활성화 에너지) → 옳지 않아 정답이에요.", "옳은 설명이에요(K>1).", "옳은 설명이에요(정의).", "옳은 설명이에요."]}, {"id": "c47", "u": "깁스 자유에너지", "t": "mc", "lv": 3, "q": "일정한 T, P에서 $\\Delta G_{sys}=-T\\Delta S_{total}$이 성립한다. 이 관계를 유도할 때 사용하는 것이 아닌 것은?", "c": ["$\\Delta S_{surr}=+\\Delta H_{sys}/T$", "일정 압력에서 $q_p=\\Delta H_{sys}$", "주위로 전달된 열 = $-\\Delta H_{sys}$", "$G=H-TS$"], "a": 0, "ex": "$\\Delta S_{surr}=-\\Delta H_{sys}/T$ (부호 −)가 맞아요. $\\Delta S_{tot}=\\Delta S_{sys}-\\Delta H_{sys}/T$이고, 양변에 −T를 곱하면 $-T\\Delta S_{tot}=\\Delta H-T\\Delta S=\\Delta G$예요.", "ref": ["q:37", "q:34"], "s": "chem", "cx": ["주위 엔트로피는 $-\\\\Delta H_{sys}/T$예요. 부호가 틀려서 유도에 쓰이지 않아요 → 정답이에요.", "유도에 사용해요(정압 열 = ΔH).", "유도에 사용해요(계가 낸 열 = 주위가 받은 열).", "유도에 사용해요(ΔG = ΔH − TΔS)."]}, {"id": "c48", "u": "깁스 자유에너지", "t": "num", "lv": 3, "q": "3NO(g) → N₂O(g) + NO₂(g) 반응의 ΔH° = −155.7 kJ, ΔS° = −171.8 J/K라 하자. 이 반응이 자발적인 온도의 상한 T*는 약 몇 K인가?", "a": 906.0, "tol": 0.01, "unit": "K", "ex": "둘 다 음수 → T* = ΔH/ΔS = 155700/171.8 = 906 K 아래에서만 자발적이에요.", "ref": ["q:41"], "s": "chem"}, {"id": "c49", "u": "고체 구조", "t": "mc", "lv": 1, "q": "결정성 고체와 비결정성 고체에 대한 설명으로 옳은 것은?", "c": ["비결정성 고체는 녹는점이 일정하지 않고 등방성이다", "결정성 고체는 녹는점이 일정하지 않다", "유리는 결정성 고체이다", "석영은 비결정성 고체이다"], "a": 0, "ex": "비결정성 고체(유리, 플라스틱, 고무)는 결합 세기가 고르지 않아 약한 부분부터 녹으므로 녹는점이 일정하지 않아요. 석영은 결정, 유리는 비결정이에요.", "ref": ["r1:1", "r2:59", "r2:61"], "s": "chem", "cx": ["비결정성 고체는 배열이 불규칙해 일정한 범위에서 서서히 녹고, 방향에 따른 차이가 없어요(등방성).", "결정성 고체는 녹는점이 일정해요.", "유리는 비결정성 고체예요.", "석영은 결정성(망상) 고체예요. 석영 유리가 비결정성이에요."]}, {"id": "c50", "u": "고체 구조", "t": "num", "lv": 2, "q": "파장 1.54 Å의 X선으로 알루미늄 결정을 분석했더니 θ = 19.3°에서 1차(n = 1) 반사가 나타났다. 원자면 사이 거리 d는 몇 Å인가?", "a": 2.33, "tol": 0.01, "unit": "Å", "ex": "브래그 식 $n\\lambda=2d\\sin\\theta$ → $d=\\dfrac{1.54}{2\\sin19.3^\\circ}=2.33$ Å = 233 pm.", "ref": ["r1:2", "r2:65"], "s": "chem"}, {"id": "c51", "u": "고체 구조", "t": "mc", "lv": 1, "q": "결정성 고체의 종류와 예를 바르게 짝지은 것은?", "c": ["망상(공유) 결정 – 다이아몬드, 석영", "분자 결정 – NaCl", "이온 결정 – 드라이아이스", "금속 결정 – 흑연"], "a": 0, "ex": "이온 결정: NaCl / 분자 결정: 얼음, CO₂(s), I₂ / 망상 결정: 다이아몬드, 흑연, 석영 / 금속 결정: Cu, Fe.", "ref": ["r1:3", "r2:60"], "s": "chem", "cx": ["다이아몬드와 석영은 공유결합 그물 구조예요.", "NaCl은 이온 결정이에요.", "드라이아이스(CO₂)는 분자 결정이에요.", "흑연은 공유(망상) 결정이에요."]}, {"id": "c52", "u": "고체 구조", "t": "mc", "lv": 1, "q": "흑연은 전기가 통하지만 다이아몬드는 통하지 않는 이유는?", "c": ["흑연은 sp² 혼성이고 남은 2p 오비탈의 π 전자가 층 전체에 비편재화되어 있기 때문", "흑연은 이온 결합 물질이기 때문", "다이아몬드는 원자 사이가 멀기 때문", "흑연은 sp³ 혼성이기 때문"], "a": 0, "ex": "다이아몬드는 sp³ 정사면체 구조이고 띠 간격이 커서 절연체예요. 흑연은 혼성되지 않은 2p 오비탈이 π MO를 이루어 비편재 전자가 전류를 운반해요.", "ref": ["r1:10", "r1:11", "r2:71"], "s": "chem", "cx": ["흑연은 층마다 비편재화된 π 전자가 있어 전기가 통해요. 다이아몬드는 sp³로 전자가 모두 묶여 있어요.", "흑연은 공유결합 물질이에요.", "원자 간 거리는 전도성의 원인이 아니에요.", "흑연은 sp², 다이아몬드가 sp³예요."]}, {"id": "c53", "u": "고체 구조", "t": "mc", "lv": 2, "q": "SiO₂가 CO₂처럼 독립된 분자가 되지 않고 그물 구조를 이루는 이유는?", "c": ["Si는 3p 오비탈이 커서 작은 O의 오비탈과 π 결합을 효과적으로 만들지 못해, 4개의 O와 단일결합을 하기 때문", "Si는 전기음성도가 O보다 크기 때문", "SiO₂는 이온 결합 물질이기 때문", "Si가 sp 혼성을 하기 때문"], "a": 0, "ex": "그래서 SiO₄ 사면체가 산소를 공유하는 망상 구조가 돼요. 실험식은 SiO₂지만 분자는 아니에요.", "ref": ["r1:11"], "s": "chem", "cx": ["Si–O π 결합이 약해 Si=O를 만들지 못하고, Si 하나가 O 4개와 단일결합 → 3차원 그물이 돼요.", "전기음성도는 O가 더 커요.", "SiO₂는 공유결합(망상) 물질이에요.", "Si는 sp³ 혼성이에요."]}, {"id": "c54", "u": "고체 구조", "t": "mc", "lv": 1, "q": "강철(Fe + C)과 같이 금속 결정의 틈새를 작은 원자가 차지하는 합금은?", "c": ["침입형 합금 – 순수한 철보다 단단하고 연성이 작다", "치환형 합금 – 순수한 철보다 무르다", "침입형 합금 – 순수한 철보다 연성이 크다", "치환형 합금 – 황동이 대표적이며 탄소가 들어간다"], "a": 0, "ex": "탄소–철의 방향성 결합 때문에 단단해지고 연성이 줄어요. 황동(Cu에 Zn 치환)은 치환형 합금이에요.", "ref": ["r1:9"], "s": "chem", "cx": ["C가 Fe 틈새에 들어가 층의 미끄러짐을 막아 → 단단해지고 연성이 줄어요.", "치환형이 아니고, 단단해져요.", "연성은 오히려 작아져요.", "황동(Cu+Zn)은 치환형이지만 탄소는 들어가지 않아요."]}, {"id": "c55", "u": "고체 구조", "t": "mc", "lv": 1, "q": "온도를 높일 때 전기 전도도의 변화로 옳은 것은?", "c": ["금속은 감소하고, 반도체는 증가한다", "금속은 증가하고, 반도체는 감소한다", "둘 다 증가한다", "둘 다 감소한다"], "a": 0, "ex": "금속은 양이온의 열진동이 늘어 전자 이동을 방해해요. 반도체는 전도띠로 들뜨는 전자가 늘어나요.", "ref": ["r1:13", "r2:74"], "s": "chem", "cx": ["금속은 진동이 커져 전자 흐름이 방해받아 감소, 반도체는 전도띠로 올라가는 전자가 늘어 증가해요.", "두 경우가 서로 바뀌었어요.", "금속은 감소해요.", "반도체는 증가해요."]}, {"id": "c56", "u": "결정격자 계산", "t": "mc", "lv": 1, "q": "단순입방(SC), 체심입방(BCC), 면심입방(FCC)의 배위수를 순서대로 옳게 나열한 것은?", "c": ["6, 8, 12", "4, 6, 8", "6, 12, 8", "8, 8, 12"], "a": 0, "ex": "단위세포 속 입자 수는 SC 1, BCC 2, FCC 4이고, 충전율은 52%, 68%, 74%예요.", "ref": ["r1:5", "r1:6", "r2:68"], "s": "chem", "cx": ["SC 6, BCC 8, FCC 12예요.", "4는 정사면체(ZnS)의 배위수예요. 세 값 모두 틀렸어요.", "BCC와 FCC가 서로 바뀌었어요.", "SC는 6이에요."]}, {"id": "c57", "u": "결정격자 계산", "t": "mc", "lv": 2, "q": "체심입방(BCC)에서 단위세포 모서리 a와 원자 반지름 r의 관계는?", "c": ["$\\sqrt3\\,a=4r$", "$\\sqrt2\\,a=4r$", "$a=2r$", "$\\sqrt3\\,a=2r$"], "a": 0, "ex": "BCC는 몸 대각선($\\sqrt{3}\\,a$)을 따라 원자가 닿아요 →$\\sqrt{3}\\,a = 4r$. FCC는 면 대각선 →$\\sqrt{2}\\,a = 4r$, SC는 a = 2r.", "ref": ["r1:5", "r2:68"], "s": "chem", "cx": ["BCC는 몸통 대각선($\\\\sqrt3a$)에서 원자가 접해요 → $\\\\sqrt3a=4r$이에요.", "FCC(면 대각선 접촉)의 관계예요.", "SC(모서리 접촉)의 관계예요.", "대각선에는 반지름 4개(2r+2r)가 들어가요."]}, {"id": "c58", "u": "결정격자 계산", "t": "num", "lv": 2, "q": "은(Ag)은 한 모서리 0.407 nm의 면심입방 단위세포로 결정화한다. 은의 원자 반지름은 몇 nm인가?", "a": 0.1439, "tol": 0.01, "unit": "nm", "ex": "$\\sqrt2a=4r$ → $r=\\dfrac{\\sqrt2\\times0.407}{4}=0.144$ nm = $1.44\\times10^{-8}$ cm.", "ref": ["r1:6", "r1:39"], "s": "chem"}, {"id": "c59", "u": "결정격자 계산", "t": "num", "lv": 2, "q": "위 은 결정(FCC, a = 0.407 nm)의 밀도는 몇 g/cm³인가? (Ag 107.9 g/mol, $N_A=6.022\\times10^{23}$)", "a": 10.63, "tol": 0.015, "unit": "g/cm³", "ex": "$\\rho=\\dfrac{4\\times107.9}{6.022\\times10^{23}\\times(4.07\\times10^{-8})^3}=10.6$ g/cm³.", "ref": ["r1:6", "r1:39"], "s": "chem"}, {"id": "c60", "u": "결정격자 계산", "t": "num", "lv": 3, "q": "철(55.845 g/mol)은 체심입방으로 결정화하고, 원자 반지름은 0.124 nm, 밀도는 7.86 g/cm³이다. 이로부터 추정한 아보가드로 수는? (답은 ×10²³ 단위의 숫자로, 예: 6.02)", "a": 6.05, "tol": 0.015, "unit": "×10²³", "ex": "$a=\\dfrac{4r}{\\sqrt3}=0.2864$ nm, $N_A=\\dfrac{2\\times55.845}{7.86\\times(2.864\\times10^{-8})^3}=6.05\\times10^{23}$.", "ref": ["r1:5", "r1:39"], "s": "chem"}, {"id": "c61", "u": "결정격자 계산", "t": "num", "lv": 3, "q": "폴로늄(209 g/mol, 밀도 9.2 g/cm³)이 단순입방 단위세포를 가질 때 원자 반지름은 몇 nm인가?", "a": 0.1677, "tol": 0.015, "unit": "nm", "ex": "$a^3=\\dfrac{209}{9.2\\times6.022\\times10^{23}}=3.77\\times10^{-23}$ cm³ → $a=0.335$ nm, $r=a/2=0.168$ nm.", "ref": ["r1:5", "r1:39"], "s": "chem"}, {"id": "c62", "u": "결정격자 계산", "t": "num", "lv": 3, "q": "면심입방 구조의 충전율(쌓임 비율)은 몇 %인가? (소수 첫째 자리)", "a": 74.0, "tol": 0.01, "unit": "%", "ex": "$\\dfrac{4\\times\\frac43\\pi r^3}{a^3}$, $a=2\\sqrt2r$ → $\\dfrac{\\pi}{3\\sqrt2}=0.740$ → 74.0%. hcp도 74%로 같아요.", "ref": ["r1:6", "r2:69"], "s": "chem"}, {"id": "c63", "u": "결정격자 계산", "t": "mc", "lv": 2, "q": "Ni–Al 초합금에서 Al 원자는 입방 단위세포의 꼭짓점, Ni 원자는 면의 중심에 있다. 조성은?", "c": ["Ni₃Al", "NiAl", "NiAl₃", "Ni₂Al"], "a": 0, "ex": "Al: 1/8 × 8 = 1, Ni: 1/2 × 6 = 3 → Ni₃Al.", "ref": ["r1:40"], "s": "chem", "cx": ["Al: 8×1/8 = 1, Ni: 6×1/2 = 3 → Ni₃Al이에요.", "면 중심 원자 수를 1로 잘못 셌어요.", "Ni와 Al이 바뀌었어요.", "면 중심은 6×1/2 = 3이에요."]}, {"id": "c64", "u": "이온 결정", "t": "mc", "lv": 1, "q": "NaCl 결정에서 Na⁺ 이온이 차지하는 자리와 배위수는?", "c": ["Cl⁻의 ccp에서 정팔면체 자리 4개를 모두 차지 – 배위수 6", "정사면체 자리 8개를 모두 차지 – 배위수 4", "정육면체 자리 – 배위수 8", "정사면체 자리의 절반 – 배위수 4"], "a": 0, "ex": "ccp 단위세포에는 정팔면체 자리가 4개(모서리 12 × 1/4 + 중심 1), 정사면체 자리가 8개 있어요.", "ref": ["r1:16", "r1:18", "r2:76"], "s": "chem", "cx": ["NaCl: Cl⁻ ccp + Na⁺가 팔면체 구멍 4개를 모두 채워 → 1:1, 배위수 6이에요.", "사면체 구멍을 모두 채우면 형석(CaF₂, 1:2) 구조예요.", "정육면체 자리·배위수 8은 CsCl이에요.", "사면체 절반은 ZnS(배위수 4)예요."]}, {"id": "c65", "u": "이온 결정", "t": "mc", "lv": 2, "q": "양이온 반지름 100 pm, 음이온 반지름 181 pm인 1:1 이온 화합물이 가질 것으로 예상되는 배위수는?", "c": ["6 (NaCl형)", "4 (ZnS형)", "8 (CsCl형)", "12"], "a": 0, "ex": "r⁺/r⁻ = 100/181 = 0.552 → 0.414 ≤ 비 < 0.732 → 정팔면체 자리(배위수 6).", "sol": "<table class=\"t\"><tr><th>배위수</th><th>자리</th><th>r⁺/r⁻</th></tr><tr><td>4</td><td>사면체</td><td>0.225~0.414</td></tr><tr><td>6</td><td>팔면체</td><td>0.414~0.732</td></tr><tr><td>8</td><td>정육면체</td><td>0.732~1</td></tr></table>", "ref": ["r1:17", "r1:18", "r2:77"], "s": "chem", "cx": ["r⁺/r⁻ = 100/181 ≈ 0.55 → 0.414~0.732 구간이라 팔면체(배위수 6)예요.", "0.225~0.414일 때 배위수 4예요.", "0.732 이상일 때 배위수 8이에요.", "이온 결정에서 12는 나오지 않아요."]}, {"id": "c66", "u": "이온 결정", "t": "num", "lv": 3, "q": "정사면체 자리에 양이온이 들어가기 위한 한계 반지름비 r⁺/r⁻ 는? (소수 셋째 자리)", "a": 0.225, "tol": 0.01, "unit": "", "ex": "정사면체 자리 한계 $=\\dfrac{\\sqrt6-2}{2}=0.225$. 정팔면체는 $\\sqrt2-1=0.414$, 정육면체는 $\\sqrt3-1=0.732$예요.", "ref": ["r1:17", "r2:77"], "s": "chem"}, {"id": "c67", "u": "이온 결정", "t": "mc", "lv": 2, "q": "플루오린화 이온이 최조밀 쌓임을 이루고, 코발트 이온이 정팔면체 구멍의 절반을 채운다. 화학식은?", "c": ["CoF₂", "CoF", "CoF₃", "Co₂F"], "a": 0, "ex": "음이온 n개당 정팔면체 구멍이 n개 → 절반이면 Co는 n/2개 → Co : F = 1 : 2.", "ref": ["r1:41"], "s": "chem", "cx": ["ccp에서 F⁻ n개, 팔면체 구멍 n개 → 절반 = n/2 → Co:F = 1:2예요.", "구멍을 모두 채웠을 때의 조성이에요.", "1/3을 채웠을 때의 조성이에요.", "Co가 F보다 많을 수 없어요."]}, {"id": "c68", "u": "이온 결정", "t": "mc", "lv": 3, "q": "황 이온이 ccp를 이루고 아연 이온이 정사면체 구멍의 1/8, 알루미늄 이온이 정팔면체 구멍의 1/2을 차지한다. 화학식은?", "c": ["ZnAl₂S₄", "ZnAlS₂", "Zn₂AlS₄", "ZnAl₂S₃"], "a": 0, "ex": "S²⁻ 4개당 사면체 8개 × 1/8 = Zn 1, 팔면체 4개 × 1/2 = Al 2 → ZnAl₂S₄ (전하: +2 +6 −8 = 0 ✔).", "ref": ["r1:41", "r1:16"], "s": "chem", "cx": ["S 4개 → 사면체 구멍 8개의 1/8 = Zn 1, 팔면체 구멍 4개의 1/2 = Al 2 → ZnAl₂S₄예요.", "S가 2개면 Zn이 1/2이 돼요.", "Zn은 1개예요.", "S는 4개예요(전하: 2+6 = 8 = 4×2)."]}, {"id": "c69", "u": "이온 결정", "t": "mc", "lv": 2, "q": "Na₂O, CdS, ZrI₄는 음이온이 ccp를 이루고 양이온이 정사면체 구멍에 들어간다. 각각 정사면체 구멍의 몇 분의 몇을 채우는가?", "c": ["Na₂O: 전부, CdS: 1/2, ZrI₄: 1/8", "Na₂O: 1/2, CdS: 전부, ZrI₄: 1/4", "Na₂O: 1/4, CdS: 1/2, ZrI₄: 1/8", "모두 1/2"], "a": 0, "ex": "음이온 4개당 사면체 구멍 8개. Na₂O: 양이온 8 → 8/8, CdS: 4 → 1/2, ZrI₄: 1 → 1/8.", "ref": ["r1:41"], "s": "chem", "cx": ["사면체 구멍 = 2n. Na₂O는 Na 2n → 전부, CdS는 n → 1/2, ZrI₄는 n/4 → 1/8이에요.", "Na₂O와 CdS가 서로 바뀌었고, ZrI₄도 틀렸어요.", "Na₂O는 전부예요.", "화학식마다 비율이 달라요."]}, {"id": "c70", "u": "이온 결정", "t": "num", "lv": 3, "q": "CsCl(168.4 g/mol)의 밀도가 3.97 g/cm³이고 Cs⁺와 Cl⁻가 단위세포의 몸 대각선을 따라 접촉한다. 이웃한 Cs⁺와 Cl⁻ 중심 사이 거리는 몇 pm인가?", "a": 357.7, "tol": 0.015, "unit": "pm", "ex": "단위세포에 CsCl 1개. $a^3=\\dfrac{168.4}{3.97\\times6.022\\times10^{23}}$ → $a=413$ pm, 거리 = $\\dfrac{\\sqrt3}{2}a=358$ pm (반지름 합 169 + 181 = 350 pm보다 약간 큼).", "ref": ["r1:42", "r1:18"], "s": "chem"}, {"id": "c71", "u": "이온 결정", "t": "num", "lv": 3, "q": "MgO(40.31 g/mol)는 NaCl형 구조이고 밀도는 3.58 g/cm³이다. O²⁻끼리 면 대각선 방향으로 접촉한다고 가정할 때 O²⁻의 반지름은 몇 pm인가?", "a": 149.0, "tol": 0.02, "unit": "pm", "ex": "$a^3=\\dfrac{4\\times40.31}{3.58\\times6.022\\times10^{23}}$ → $a=421$ pm, $r_{O}=\\dfrac{\\sqrt2a}{4}=149$ pm (이때 $r_{Mg}=(a-2r_O)/2=62$ pm).", "ref": ["r1:42"], "s": "chem"}, {"id": "c72", "u": "이온 결정", "t": "mc", "lv": 2, "q": "녹는점이 CaO > NaCl > KBr 순서인 이유로 가장 적절한 것은?", "c": ["이온의 전하가 크고 이온 사이 거리가 짧을수록 쿨롱 인력이 커서 격자를 끊는 데 많은 에너지가 필요하므로", "분자량이 클수록 녹는점이 높으므로", "런던 분산력의 크기 차이 때문에", "금속 결합의 세기 차이 때문에"], "a": 0, "ex": "F ∝ q⁺q⁻/r². CaO는 ±2 전하, NaCl·KBr은 ±1이고, KBr이 NaCl보다 이온 사이 거리가 길어요.", "ref": ["r1:15"], "s": "chem", "cx": ["쿨롱 법칙($\\\\propto q_1q_2/r$): CaO(2+·2−) > NaCl > KBr(이온이 큼)이에요.", "KBr이 더 무겁지만 녹는점은 더 낮아요.", "분산력은 분자 결정에서 중요한 힘이에요.", "이온 결정이라 금속 결합과는 관계없어요."]}, {"id": "c73", "u": "이온 결정", "t": "mc", "lv": 1, "q": "이온성 고체의 성질로 옳지 않은 것은?", "c": ["고체 상태에서 전기 전도성이 크다", "녹는점이 높다(대략 600~2000 ℃)", "외부 힘을 가하면 같은 전하끼리 마주쳐 쪼개진다", "용융 상태나 수용액에서 전기가 통한다"], "a": 0, "ex": "고체에서는 이온이 격자에 고정되어 움직일 수 없어 전기가 통하지 않아요.", "ref": ["r1:15"], "s": "chem", "cx": ["고체에서는 이온이 고정되어 전기가 통하지 않아요 → 옳지 않아 정답이에요.", "옳은 설명이에요.", "옳은 설명이에요(쪼개짐).", "옳은 설명이에요(이온이 이동 가능)."]}, {"id": "c74", "u": "상평형", "t": "mc", "lv": 1, "q": "물의 상평형 그림에서 고체–액체 경계선의 기울기가 음(−)인 이유는?", "c": ["녹는점에서 얼음의 밀도가 액체 물보다 작기 때문(얼면 부피 증가)", "얼음의 밀도가 물보다 크기 때문", "물의 증기압이 작기 때문", "물이 초임계 유체가 되기 때문"], "a": 0, "ex": "클라페이론 식 dP/dT = ΔH/(TΔV)에서 융해 시 ΔV < 0이므로 기울기가 음수예요. 압력이 커지면 녹는점이 낮아져요(스케이트).", "ref": ["r1:32", "r2:86", "r2:88"], "s": "chem", "cx": ["얼음이 더 가벼워서 압력을 높이면 밀도가 큰 액체 쪽이 유리해 녹는점이 내려가요 → 기울기가 음이에요.", "얼음이 물보다 가벼워요.", "증기압은 고체–액체 선과 관계없어요.", "초임계는 임계점 너머 이야기예요."]}, {"id": "c75", "u": "상평형", "t": "mc", "lv": 1, "q": "1 atm에서 고체 CO₂(드라이아이스)가 액체를 거치지 않고 승화하는 이유는?", "c": ["CO₂의 삼중점 압력(5.1 atm)이 1 atm보다 높기 때문", "CO₂의 임계 온도가 낮기 때문", "CO₂ 고체의 밀도가 액체보다 작기 때문", "CO₂는 분자 결정이 아니기 때문"], "a": 0, "ex": "삼중점(5.1 atm, −56.6 ℃)보다 낮은 압력에서는 액체 상이 존재할 수 없어요. 1 atm에서 −78 ℃에 승화해요.", "ref": ["r1:33", "r2:86"], "s": "chem", "cx": ["1 atm은 삼중점(5.1 atm)보다 낮아서 액체 영역을 지나지 않아요.", "임계 온도는 기체 액화와 관련된 개념이에요.", "CO₂는 고체가 액체보다 무거워요.", "CO₂ 고체는 분자 결정이에요."]}, {"id": "c76", "u": "상평형", "t": "mc", "lv": 1, "q": "임계점에 대한 설명으로 옳은 것은?", "c": ["임계 온도보다 높으면 아무리 압력을 가해도 기체를 액화시킬 수 없다", "임계점에서는 세 상이 공존한다", "임계 온도 아래에서는 액화가 불가능하다", "물의 임계 온도는 100 ℃이다"], "a": 0, "ex": "세 상이 공존하는 점은 삼중점이에요. 물의 임계점은 374 ℃, 218 atm이에요. 임계점 너머는 초임계 유체예요.", "ref": ["r1:34", "r2:84", "r2:85"], "s": "chem", "cx": ["임계 온도 이상에서는 압력을 높여도 액체와 기체의 구분이 사라져 액화되지 않아요.", "세 상이 공존하는 것은 삼중점이에요.", "임계 온도 아래에서 액화가 가능해요.", "물의 임계 온도는 374 ℃예요."]}, {"id": "c77", "u": "상평형", "t": "mc", "lv": 2, "q": "−20 ℃의 얼음이 가득 찬 실린더에 피스톤으로 2.0 torr의 압력을 가하며 가열하면(공기 없음) 어떻게 되는가? (물의 삼중점 4.58 torr, 0.01 ℃)", "c": ["약 −10 ℃에서 얼음이 액체를 거치지 않고 승화한다", "0 ℃에서 녹은 뒤 100 ℃에서 끓는다", "0.01 ℃에서 세 상이 공존한다", "끝까지 얼음으로 남는다"], "a": 0, "ex": "외부 압력이 삼중점 압력보다 낮으면, 얼음의 증기압이 2.0 torr가 되는 온도(약 −10 ℃)에서 승화해요.", "ref": ["r1:30", "r1:31"], "s": "chem", "cx": ["2.0 torr < 삼중점(4.58 torr)이라 고체→기체 승화예요. 그 압력의 승화 곡선과 만나는 약 −10 ℃에서 일어나요.", "1 atm(760 torr)일 때의 이야기예요.", "삼중점 압력이 아니에요.", "가열하면 승화 곡선을 만나요."]}, {"id": "c78", "u": "상평형", "t": "mc", "lv": 2, "q": "영하의 겨울날 젖은 빨래가 얼었다가 결국 마르는 현상을 바르게 설명한 것은?", "c": ["자연 환경은 열린계여서 생긴 수증기가 계속 빠져나가 얼음이 서서히 승화하기 때문", "상평형 그림에 따르면 1 atm에서 얼음은 반드시 승화하기 때문", "얼음이 녹아 물이 된 뒤 증발하기 때문", "대기압이 삼중점보다 낮기 때문"], "a": 0, "ex": "상평형 그림은 닫힌계의 평형 조건이에요. 열린계에서는 증기가 평형에 이르지 못해, 평형 승화가 아닌 승화가 실제로 일어나요.", "ref": ["r1:33"], "s": "chem", "cx": ["열린계라 수증기가 계속 빠져나가 증기압이 평형에 이르지 못하고 승화가 계속돼요.", "1 atm에서 물은 녹는 쪽이에요. 승화의 원인은 열린계예요.", "영하라 녹지 않아요.", "대기압은 삼중점(0.006 atm)보다 높아요."]}, {"id": "c79", "u": "상평형", "t": "mc", "lv": 3, "q": "가상의 물질 X는 10.0 atm에서 225 ℃에 녹고, 고체 밀도 2.78 g/cm³ > 액체 밀도 2.67 g/cm³이다. X의 정상 녹는점(1 atm)은?", "c": ["225 ℃보다 낮다", "225 ℃보다 높다", "225 ℃와 같다", "알 수 없다"], "a": 0, "ex": "고체가 더 조밀 → 녹을 때 ΔV > 0 → 고체–액체 경계선 기울기 양(+) → 압력을 낮추면(10 → 1 atm) 녹는점도 낮아져요.", "ref": ["r1:42", "r2:88"], "s": "chem", "cx": ["고체 밀도 > 액체 → 고–액 선 기울기 양(+) → 압력이 낮아지면 녹는점도 낮아져요.", "물처럼 고체가 가벼울 때의 경우예요.", "압력에 따라 녹는점이 변해요.", "밀도 정보로 기울기 부호를 알 수 있어요."]}, {"id": "c80", "u": "상평형", "t": "mc", "lv": 3, "q": "삼중점 근처에서 고체의 증기압(승화) 곡선이 액체의 증기압 곡선보다 기울기가 더 큰 이유는?", "c": ["ΔH_승화 = ΔH_융해 + ΔH_기화 > ΔH_기화 이므로 클라우지우스–클라페이롱 식에서 기울기가 더 크다", "고체의 부피가 더 크기 때문", "고체의 엔트로피가 더 크기 때문", "승화열이 기화열보다 작기 때문"], "a": 0, "ex": "$\\dfrac{d\\ln P}{dT}=\\dfrac{\\Delta H}{RT^2}$에서 ΔH가 큰 승화 곡선이 더 가팔라요.", "ref": ["r2:89", "r1:42"], "s": "chem", "cx": ["클라우지우스–클라페이롱 기울기 ∝ ΔH이고, 승화열 = 융해열 + 기화열 > 기화열이에요.", "부피는 이 기울기의 원인이 아니에요.", "고체의 엔트로피가 더 작아요.", "승화열이 더 커요."]}, {"id": "c81", "u": "상평형", "t": "num", "lv": 3, "q": "벤젠의 증기압은 40 ℃에서 183 mmHg이다. 증발열을 30.8 kJ/mol로 하여 25 ℃에서의 증기압을 구하면 약 몇 mmHg인가?", "a": 100.9, "tol": 0.02, "unit": "mmHg", "ex": "$\\ln\\dfrac{P_2}{183}=-\\dfrac{30800}{8.314}\\left(\\dfrac{1}{298.15}-\\dfrac{1}{313.15}\\right)=-0.595$ → $P_2=101$ mmHg.", "ref": ["r2:89"], "s": "chem"}, {"id": "c82", "u": "상평형", "t": "mc", "lv": 2, "q": "대기압에서 다이아몬드가 흑연으로 거의 바뀌지 않는 이유는?", "c": ["다이아몬드는 준안정 상이며, 상전이에 강한 결합을 끊는 큰 활성화 에너지가 필요하기 때문(속도론적 장벽)", "다이아몬드가 상온·상압에서 가장 안정한 상이기 때문", "흑연이 다이아몬드보다 밀도가 크기 때문", "상전이에 압력이 필요 없기 때문"], "a": 0, "ex": "상온·상압에서는 흑연이 안정한 상이에요. 흑연 → 다이아몬드는 약 15만 atm, 2800 ℃가 필요해요(밀도는 흑연 2.2 < 다이아몬드 3.5).", "ref": ["r1:11", "r2:82", "r1:35"], "s": "chem", "cx": ["흑연이 더 안정(ΔG<0)하지만 활성화 에너지가 매우 커서 속도가 극히 느려요.", "상온·상압에서 가장 안정한 탄소는 흑연이에요.", "다이아몬드가 밀도가 더 커요.", "상전이에는 큰 에너지 장벽이 있어요."]}, {"id": "cE1", "u": "이상기체 과정", "t": "essay", "q": "같은 초기 상태(298 K, 10 atm, 5 mol 단원자 이상기체)에서 같은 최종 압력(1 atm)까지 가역 등온 팽창과 가역 단열 팽창을 할 때, 최종 부피·온도·한 일의 크기를 비교하고 그 이유를 서술하시오.", "kp": ["등온: T 일정(298 K), ΔU = 0, q = −w (열을 흡수해 일)", "단열: q = 0 → w = ΔU, 내부에너지를 소모해 온도가 내려감(119 K)", "최종 부피 등온(122 L) > 단열(48.7 L)", "한 일의 크기 등온(28.5 kJ) > 단열(11.2 kJ)", "γ > 1이라 단열선이 등온선보다 가파름"], "sol": "가역 등온 팽창에서는 온도가 298 K로 유지되어 ΔU = 0이고, 계가 한 일만큼 주위에서 열을 흡수한다(q = −w = 28.5 kJ). 가역 단열 팽창에서는 열 출입이 없으므로(q = 0) 계가 한 일이 내부에너지 감소로 충당되어 온도가 119 K까지 낮아진다(w = ΔU = −11.2 kJ). 같은 압력까지 팽창할 때 단열 과정은 온도가 낮아지므로 최종 부피가 48.7 L로 등온 과정(122 L)보다 작고, PV 그래프에서 γ > 1이라 단열선이 더 가파르게 떨어져 그 아래 넓이인 일의 크기도 등온 팽창의 약 40%에 불과하다.", "ref": ["q:18", "q:16"], "s": "chem", "lv": 0, "ex": null}, {"id": "cE2", "u": "깁스 자유에너지", "t": "essay", "q": "일정한 온도와 압력에서 계의 깁스 자유에너지 변화(ΔG)만으로 반응의 자발성을 판단할 수 있는 이유를 $\\Delta S_{\\text{total}}$을 이용해 유도하여 서술하시오.", "kp": ["제2법칙: 자발적 과정에서 $\\Delta S_{\\text{total}} = \\Delta S_{\\text{sys}} + \\Delta S_{\\text{surr}} > 0$", "일정 압력: 주위로 전달된 열 = −$q_{p}$ = −$\\Delta H_{\\text{sys}}$", "$\\Delta S_{\\text{surr}}$ = $−\\Delta H_{\\text{sys}} / T$", "$\\Delta S_{\\text{total}} = \\Delta S_{\\text{sys}} − \\Delta H_{\\text{sys}}/T$ → $-T\\Delta S_{\\text{total}}=\\Delta H-T\\Delta S=\\Delta G$", "T > 0이므로 ΔG < 0 ⟺ $\\Delta S_{\\text{total}} > 0$ (자발)"], "sol": "열역학 제2법칙에 따르면 자발적 과정에서는 $\\Delta S_{\\text{total}} = \\Delta S_{\\text{sys}} + \\Delta S_{\\text{surr}} > 0$이다. 일정 압력에서 계가 흡수한 열은 $q_{p} = \\Delta H_{\\text{sys}}$이므로 주위가 받은 열은 −$\\Delta H_{\\text{sys}}$이고, 주위가 일정 온도 T를 유지하면 $\\Delta S_{\\text{surr}}$ = −$\\Delta H_{\\text{sys}}$/T이다. 따라서 $\\Delta S_{\\text{total}} = \\Delta S_{\\text{sys}} − \\Delta H_{\\text{sys}}$/T이고 양변에 −T를 곱하면 $-T\\Delta S_{\\text{total}}=\\Delta H_{\\text{sys}}-T\\Delta S_{\\text{sys}}=\\Delta G_{\\text{sys}}$이다. 절대온도 T는 항상 양수이므로 $\\Delta G_{\\text{sys}} < 0$이면 $\\Delta S_{\\text{total}} > 0$이 되어 자발적이며, 계의 성질만으로 자발성을 판단할 수 있다.", "ref": ["q:37", "q:34"], "s": "chem", "lv": 0, "ex": null}, {"id": "cE3", "u": "고체 구조", "t": "essay", "q": "소금(NaCl)과 설탕은 겉모습은 비슷하지만 성질이 크게 다르다. 두 물질의 고체 종류를 밝히고, 녹는점과 전기 전도성의 차이를 입자 간 힘으로 설명하시오.", "kp": ["소금: 이온성 고체(이온 결합), 설탕: 분자성 고체(수소결합·분자 간 힘)", "이온 결합 ≫ 분자 간 힘 → 소금의 녹는점이 훨씬 높음", "녹을 때 입자 간 힘 일부를 끊어야 함", "소금 수용액/용융액은 이온이 이동해 전기 전도, 설탕 수용액은 전도 X"], "sol": "소금은 Na⁺와 Cl⁻가 강한 이온 결합으로 배열된 이온성 고체이고, 설탕은 분자들이 수소결합 등 비교적 약한 분자 간 힘으로 모인 분자성 고체이다. 물질이 녹으려면 입자 사이의 힘을 일부 끊어야 하는데, 이온 결합이 분자 간 힘보다 훨씬 강하므로 소금의 녹는점(801 ℃)이 설탕보다 매우 높다. 또한 소금은 녹이거나 물에 녹이면 이온이 자유롭게 움직여 전기가 통하지만, 설탕은 녹아도 중성 분자로 존재하므로 전기가 통하지 않는다.", "ref": ["r1:14", "r1:15", "r1:40"], "s": "chem", "lv": 0, "ex": null}, {"id": "cE4", "u": "결정격자 계산", "t": "essay", "q": "면심입방(FCC) 단위세포와 육방최조밀(hcp) 단위세포의 충전율이 같음을 증명하시오.", "kp": ["FCC: 원자 4개,$\\sqrt{2}\\,a = 4r$ → $a = 2\\sqrt{2}\\,r$", "FCC 충전율 = 4·(4/3)πr³ / ($2\\sqrt{2}\\,r$)³ = π/($3\\sqrt{2}$) ≈ 0.74", "hcp(육방 단위): 원자 6개, 밑면 정육각형 한 변 = 2r, 높이 c = ($4\\sqrt{6}/3$) r", "hcp 부피 = ($3\\sqrt{3}/2$)(2r)²·$c = 24\\sqrt{2}\\,r^3$ → 충전율 = 6·(4/3)πr³ / $24\\sqrt{2}\\,r^3 = \\pi $/($3\\sqrt{2}$)", "둘 다 최조밀 쌓임(ABC vs ABAB)이므로 74%"], "sol": "FCC 단위세포에는 원자가 1/8×8 + 1/2×6 = 4개 있고 면 대각선을 따라 원자가 접하므로 $\\sqrt{2}\\,a = 4r$, $a = 2\\sqrt{2}\\,r$이다. 충전율 = 4×(4/3)πr³ / ($2\\sqrt{2}\\,r$)³ = (16/3)πr³ / $16\\sqrt{2}\\,r^3 = \\pi $/($3\\sqrt{2}$) ≈ 0.74. hcp 육방 단위세포에는 1/6×12 + 1/2×2 + 3 = 6개의 원자가 있고, 밑면은 한 변 2r인 정육각형(넓이 ($3\\sqrt{3}/2$)(2r)² = $6\\sqrt{3}\\,r^2$), 높이는 c = ($4\\sqrt{6}/3$)r이므로 부피 = $6\\sqrt{3}\\,r^2$ × ($4\\sqrt{6}/3$)$r = 24\\sqrt{2}\\,r^3$이다. 충전율 = 6×(4/3)πr³ / $24\\sqrt{2}\\,r^3 = \\pi $/($3\\sqrt{2}$) ≈ 0.74로 FCC와 같다. 두 구조 모두 같은 크기의 구를 최조밀로 쌓되 층 배열만 ABCABC…와 ABAB…로 다르기 때문이다.", "ref": ["r1:6", "r1:7", "r1:40"], "s": "chem", "lv": 0, "ex": null}, {"id": "cE5", "u": "상평형", "t": "essay", "q": "일반적으로 액체는 온도를 높이면 기화하고 기체는 압력을 높이면 액화한다. 그러나 임계 압력 이상의 액체는 온도를 높여도 기화하지 않고, 임계 온도 이상의 기체는 압력을 높여도 응축하지 않는다. 그 이유를 설명하시오.", "kp": ["임계 온도 이상: 분자의 운동에너지가 분자 간 인력보다 커서 압축해도 액체 상(경계면)을 형성 못함", "임계점에서 액체와 기체의 밀도가 같아져 구분(경계면)이 사라짐", "임계점 너머는 초임계 유체 – 하나의 균일한 상", "따라서 기화·액화라는 상전이(불연속 변화)가 일어나지 않음"], "sol": "온도가 임계 온도보다 높으면 분자의 평균 운동에너지가 분자 간 인력을 압도하여 아무리 압축해도 분자들이 액체 상으로 모이지 못한다. 또한 임계점에 가까워질수록 액체의 밀도는 감소하고 기체의 밀도는 증가하다가 임계점에서 같아져 두 상의 경계면이 사라진다. 임계 온도·임계 압력을 넘어선 영역은 액체도 기체도 아닌 하나의 균일한 초임계 유체이므로, 그 안에서는 온도나 압력을 바꾸어도 기화나 응축 같은 불연속적인 상전이가 일어나지 않는다.", "ref": ["r1:34", "r2:84", "r2:85"], "s": "chem", "lv": 0, "ex": null}, {"id": "cE6", "u": "상평형", "t": "essay", "q": "물의 상평형 그림에서 고체–액체 경계선의 기울기가 음인 이유를 클라페이론 식과 연결하여 설명하고, 이 성질이 나타나는 일상의 예를 두 가지 쓰시오.", "kp": ["클라페이론 식 dP/dT = ΔH_융해/(TΔV_융해)", "ΔH_융해 > 0, 얼음 밀도 < 물 → 녹으면 부피 감소 ΔV < 0 → 기울기 음수", "압력↑ → 녹는점↓", "예: 스케이트 날 아래 얼음이 압력으로 녹음", "예: 얼음이 물에 뜸 / 수도관 동파 / 호수 표면만 얼어 생물 생존"], "sol": "두 상의 경계선 기울기는 클라페이론 식 dP/dT = ΔH/(TΔV)로 주어진다. 얼음이 녹을 때 ΔH는 양수이지만, 수소결합으로 생긴 얼음의 빈 공간이 무너져 액체 물이 더 조밀해지므로 ΔV는 음수가 된다. 따라서 기울기가 음이 되어 압력이 높아질수록 녹는점이 낮아진다. 예로 스케이트 날의 큰 압력이 얼음을 녹여 잘 미끄러지게 하는 것, 얼음이 물에 떠서 호수 표면만 얼어 수중 생물이 살 수 있는 것, 물이 얼며 부피가 늘어 수도관이 터지는 것이 있다.", "ref": ["r1:32", "r2:88"], "s": "chem", "lv": 0, "ex": null}, {"id": "cE7", "u": "카르노", "t": "essay", "q": "가역 카르노 기관의 효율 식을 쓰고, 열기관의 효율이 100%가 될 수 없는 이유와 효율을 높이는 방법을 서술하시오.", "kp": ["η = $−w/q_{h} = 1 − T_{c}/T_{h}$", "η = 1이려면 $T_{c} = 0$ K 또는 $T_{h} = \\infty $ → 불가능", "열을 일로 바꾸는 데 근본적 한계(제2법칙)", "효율↑: 고온-저온 온도차를 크게 (냉각기 사용 등)"], "sol": "가역 카르노 기관의 효율은 흡수한 열에 대한 한 일의 비로 η = $−w/q_{h} = 1 − T_{c}/T_{h}$이다. 효율이 100%가 되려면 저온 열원의 온도가 0 K이거나 고온 열원이 무한대여야 하는데 이는 불가능하므로, 흡수한 열의 일부는 반드시 저온 열원으로 버려야 한다(열을 일로 완전히 바꿀 수 없다는 제2법칙의 한계). 효율을 높이려면 두 열원의 온도 차이를 크게 해야 하므로 고온부의 온도를 높이거나 냉각기를 사용해 저온부의 온도를 낮춘다.", "ref": ["q:30"], "s": "chem", "lv": 0, "ex": null}, {"id": "cE8", "u": "고체 구조", "t": "essay", "q": "흑연은 전기가 통하고 미끄럽지만 다이아몬드는 전기가 통하지 않고 매우 단단하다. 두 동소체의 구조(혼성 오비탈, 결합)로 설명하시오.", "kp": ["다이아몬드: sp³ 혼성, 정사면체 3차원 공유결합 망상 → 매우 단단", "다이아몬드: 채워진 MO와 빈 MO 사이 띠 간격이 큼 → 절연체", "흑연: sp² 혼성, 120° 육각 평면 층", "흑연: 남은 2p 오비탈 → π MO 비편재 전자 → 전기 전도", "흑연: 층 사이는 약한 힘 → 미끄러움"], "sol": "다이아몬드의 각 탄소는 sp³ 혼성 오비탈로 네 탄소와 정사면체 모양의 공유결합을 하여 3차원 거대 분자를 이루므로 매우 단단하고, 채워진 분자 오비탈과 빈 분자 오비탈 사이의 띠 간격이 커서 전자가 전도띠로 이동하지 못하는 절연체이다. 흑연의 탄소는 sp² 혼성으로 세 탄소와 120°의 σ결합을 하여 육각형 평면 층을 이루며, 혼성되지 않은 2p 오비탈들이 층 전체에 비편재화된 π 분자 오비탈을 형성하여 전기가 통한다. 원자가 전자가 모두 층 내 결합에 쓰여 층 사이에는 약한 힘만 작용하므로 층이 쉽게 미끄러진다.", "ref": ["r1:10", "r1:11", "r2:71"], "s": "chem", "lv": 0, "ex": null}, {"id": "b01", "u": "유전자와 단백질", "t": "mc", "lv": 1, "q": "알캅톤뇨증을 비롯한 선천성 대사 이상 질환을 연구하여 \"대사 장애는 특정 효소가 합성되지 못하기 때문이며, 대사 장애는 열성으로 유전된다\"고 처음 발표한 사람은?", "c": ["개로드(Garrod)", "비들과 테이텀", "자코브와 모노", "그리피스"], "a": 0, "ex": "개로드는 유전자와 단백질(효소)의 관계를 가장 먼저 인식한 사람이에요. 알캅톤뇨증은 호모겐티신산을 분해하는 효소가 없어서 산화된 호모겐티신산이 소변을 검게 만드는 병이에요.", "ref": ["bio5:2", "nb:n1"], "s": "bio", "cx": ["개로드는 알캅톤뇨증을 연구해 \"선천성 대사 이상\"이라는 개념을 처음 제시했어요.", "비들·테이텀은 붉은빵곰팡이로 1유전자 1효소설을 실험으로 증명했어요.", "자코브·모노는 lac 오페론(유전자 발현 조절)을 연구했어요.", "그리피스는 폐렴쌍구균 형질전환 실험을 했어요."]}, {"id": "b02", "u": "유전자와 단백질", "t": "mc", "lv": 1, "q": "비들과 테이텀이 1유전자 1효소설을 증명할 때 사용한 생물과, 그 생물을 쓴 가장 중요한 이유로 옳은 것은?", "c": ["붉은빵곰팡이 – 핵상이 n(반수체)이라 돌연변이가 바로 표현형으로 나타난다", "대장균 – 오페론을 가지고 있어 조절 연구가 쉽다", "붉은빵곰팡이 – 2n이라 열성 돌연변이를 보존하기 쉽다", "효모 – 필수아미노산을 합성하지 못한다"], "a": 0, "ex": "붉은빵곰팡이는 생활사 대부분이 반수체(n)라서 대립유전자가 하나뿐이에요. 그래서 X선으로 생긴 돌연변이가 가려지지 않고 바로 표현형(생장 여부)으로 나타나요.", "ref": ["bio5:3", "nb:n2"], "s": "bio", "cx": ["붉은빵곰팡이는 n이라 대립유전자가 하나뿐이어서 열성 돌연변이도 바로 드러나요.", "1유전자 1효소설 실험에는 대장균이 아니라 붉은빵곰팡이를 썼어요.", "생물은 맞지만 핵상이 n이에요. 2n이면 열성이 가려져요.", "효모를 쓰지 않았어요. 야생형은 최소배지에서 다 합성해요."]}, {"id": "b03", "u": "유전자와 단백질", "t": "txt", "lv": 1, "q": "붉은빵곰팡이가 최소배지에서 생장할 때, 생체에서 가장 처음으로 합성되는 비필수아미노산은? (단답)", "a": ["글루탐산", "glutamate", "글루탐산염", "glutamicacid"], "ex": "최소배지에는 포도당, 무기염류, 비오틴(비타민 B8)만 있어요. 붉은빵곰팡이는 여기서 글루탐산을 가장 먼저 합성하고, 이것을 바탕으로 필요한 모든 아미노산을 만들어요.", "ref": ["bio5:4"], "s": "bio"}, {"id": "b04", "u": "유전자와 단백질", "t": "mc", "lv": 2, "q": "아르지닌 합성 경로는 다음과 같다.\n선구물질 →(효소 a)→ 오르니틴 →(효소 b)→ 시트룰린 →(효소 c)→ 아르지닌\n어떤 돌연변이주는 최소배지 + 오르니틴에서는 자라지 못하지만, 최소배지 + 시트룰린, 최소배지 + 아르지닌에서는 자란다. 이 돌연변이주에 결손된 효소는?", "c": ["효소 a", "효소 b", "효소 c", "효소 a와 c"], "a": 1, "ex": "시트룰린부터 넣어 주면 자라므로 시트룰린 이후 단계는 정상이에요. 오르니틴을 넣어도 자라지 못하므로 오르니틴 → 시트룰린 단계, 즉 효소 b가 결손됐어요.", "sol": "<b>규칙</b>: 결손된 효소의 <u>바로 다음 산물</u>부터 넣어 주면 생장해요. 최종산물(아르지닌)을 넣으면 모든 돌연변이가 생장해요.<br>오르니틴 ✗ / 시트룰린 ○ / 아르지닌 ○ → 오르니틴에서 막힘 → <b>효소 b (Ⅱ형)</b>", "ref": ["bio5:8", "nb:n1"], "s": "bio", "cx": ["효소 a가 없어도 오르니틴을 넣어 주면 자라야 하는데, 이 돌연변이주는 오르니틴에서 자라지 못해요.", "오르니틴에서는 못 자라고 시트룰린부터 자라므로 오르니틴→시트룰린(효소 b)이 막혔어요.", "효소 c가 없으면 시트룰린을 넣어도 자라지 못해요.", "a와 c가 모두 없으면 아르지닌에서만 자라야 해요. 시트룰린에서 자라므로 c는 정상이에요."]}, {"id": "b05", "u": "유전자와 단백질", "t": "mc", "lv": 2, "q": "위 아르지닌 합성 경로에서 최소배지 + 아르지닌에서만 자라는 돌연변이주(Ⅲ형)에 결손된 효소는?", "c": ["효소 a", "효소 b", "효소 c", "결손된 효소 없음"], "a": 2, "ex": "오르니틴, 시트룰린을 넣어도 못 자라고 아르지닌을 넣어야만 자라요. 그러므로 시트룰린 → 아르지닌을 담당하는 효소 c가 결손됐어요.", "ref": ["bio5:8"], "s": "bio", "cx": ["효소 a 결손이면 오르니틴만 넣어도 자라요.", "효소 b 결손이면 시트룰린만 넣어도 자라요.", "아르지닌에서만 자라므로 마지막 단계(시트룰린→아르지닌, 효소 c)가 막혔어요.", "결손이 없으면 최소배지에서도 자라요."]}, {"id": "b06", "u": "유전자와 단백질", "t": "mc", "lv": 3, "q": "페닐알라닌 합성 경로가 chorismate → prephenate → 페닐피루브산 → 페닐알라닌 이라고 하자.\n돌연변이주 X는 최소배지에 페닐피루브산 또는 prephenate를 넣으면 자라지만, chorismate를 넣으면 자라지 못한다. X에서 막힌 단계는?", "c": ["chorismate → prephenate", "prephenate → 페닐피루브산", "페닐피루브산 → 페닐알라닌", "선구물질 → chorismate"], "a": 0, "ex": "prephenate부터 넣으면 자라므로 prephenate 이후는 정상이에요. chorismate는 이용하지 못하므로 chorismate → prephenate 단계가 막혔어요.", "sol": "수업 응용 슬라이드(페닐알라닌 경로)와 같은 원리예요. <b>자라게 해 주는 물질 중 경로상 가장 앞선 것</b> 바로 앞 단계가 결손 단계예요.", "ref": ["bio5:9"], "s": "bio", "cx": ["prephenate부터는 자라고 chorismate는 쓰지 못하니 chorismate→prephenate가 막혔어요.", "이 단계가 막혔다면 prephenate를 넣었을 때 자라지 못해요.", "이 단계가 막혔다면 페닐피루브산을 넣어도 자라지 못해요.", "chorismate를 넣어도 못 자라므로 그 앞 단계만의 문제가 아니에요."]}, {"id": "b07", "u": "유전자와 단백질", "t": "mc", "lv": 1, "q": "헤모글로빈이 2개의 α 사슬과 2개의 β 사슬로 이루어지고, α와 β가 서로 다른 유전자에서 만들어진다는 사실이 밝혀지면서 수정된 가설은?", "c": ["1유전자 1폴리펩타이드설", "1유전자 1효소설", "1유전자 1기능성분자설", "1유전자 다폴리펩타이드설"], "a": 0, "ex": "하나의 단백질이 여러 종류의 폴리펩타이드로 이루어진 경우가 발견되면서, \"1유전자 = 1폴리펩타이드\"로 수정됐어요.", "ref": ["bio5:11"], "s": "bio", "cx": ["α, β 사슬이 각각 다른 유전자에서 만들어지므로 \"유전자 1개 = 폴리펩타이드 1개\"로 수정됐어요.", "수정되기 전의 원래 가설이에요.", "RNA 산물까지 포함한 더 나중의 현대적 해석이에요.", "이런 가설은 없어요."]}, {"id": "b08", "u": "유전자와 단백질", "t": "mc", "lv": 1, "q": "miRNA, rRNA, tRNA 등이 발견되면서 \"유전자의 전사 결과물이 폴리펩타이드에만 국한되지 않는다\"는 것을 반영한 현대적 해석은?", "c": ["1유전자 1기능성분자설", "1유전자 1단백질설", "1유전자 1효소설", "중심원리 폐기설"], "a": 0, "ex": "현대적 해석은 \"유전자는 폴리펩타이드 또는 기능적인 RNA를 암호화하는 부위\"라는 1유전자 1기능성분자설이에요.", "ref": ["bio5:12", "nb:n2"], "s": "bio", "cx": ["tRNA·rRNA·miRNA처럼 RNA 자체가 최종 산물인 경우도 포함하는 해석이에요.", "단백질로만 한정하면 RNA 산물을 설명하지 못해요.", "최초의 가설이라 RNA 산물을 설명하지 못해요.", "중심원리는 폐기되지 않았어요."]}, {"id": "b09", "u": "유전자와 단백질", "t": "mc", "lv": 1, "q": "필기에 정리한 시기별 헤모글로빈 구성 중 '태아' 헤모글로빈은?", "c": ["α₂γ₂", "ζ₂ε₂", "α₂β₂", "α₂δ₂"], "a": 0, "ex": "배아는 ζ₂ε₂, 태아는 α₂γ₂, 성인은 α₂β₂예요. 태아 헤모글로빈은 모체 혈액에서 산소를 받아와야 해서 산소 친화력이 더 커요.", "ref": ["nb:n1"], "s": "bio", "cx": ["태아는 α₂γ₂예요. 산소 친화력이 커서 모체로부터 산소를 받아요.", "배아(초기)의 헤모글로빈이에요.", "성인의 주 헤모글로빈이에요.", "성인의 소량 헤모글로빈(HbA₂)이에요."]}, {"id": "b10", "u": "유전자와 단백질", "t": "mc", "lv": 1, "q": "1유전자 1효소설 실험에서 붉은빵곰팡이 포자에 X선을 쬔 뒤, \"하나의 돌연변이만 생긴다\"고 가정하는 이유로 가장 적절한 것은?", "c": ["돌연변이가 여러 자리에서 생기면 결과 해석이 꼬이기 때문", "X선은 항상 한 자리에서만 돌연변이를 일으키기 때문", "반수체는 돌연변이가 한 개까지만 허용되기 때문", "최소배지에서는 돌연변이가 하나만 나타나기 때문"], "a": 0, "ex": "필기에 \"변이가 여러 자리면 해석이 꼬인다\"고 적어 두었죠. 실험을 단순하게 해석하려고 하나의 변이만 생긴다고 가정해요.", "ref": ["nb:n1", "bio5:6"], "s": "bio", "cx": ["돌연변이가 둘 이상이면 어느 유전자 때문인지 해석하기 어려워 하나로 가정해요.", "X선은 여러 자리에 무작위로 돌연변이를 일으킬 수 있어요.", "이런 제한은 없어요.", "배지는 돌연변이 수를 정하지 않아요."]}, {"id": "b11", "u": "중심원리·전사", "t": "mc", "lv": 1, "q": "원핵세포 RNA 중합효소에서 프로모터를 인식하여 전사 개시를 돕고, 전사가 시작되면 떨어져 재사용되는 소단위는?", "c": ["σ (시그마) 인자", "ω (오메가)", "β′", "α"], "a": 0, "ex": "σ를 뺀 α₂ββ′ω를 핵심효소, σ를 보조인자라고 해요. 핵심효소 + σ = 완전효소예요. σ는 개시(프로모터 인식)에만 필요해요.", "ref": ["nb:n2"], "s": "bio", "cx": ["σ 인자는 프로모터를 인식하고 개시 후 떨어져 다시 쓰여요.", "ω는 중합효소의 조립·안정화를 도와요.", "β′는 DNA에 결합하는 핵심 소단위예요.", "α는 효소 조립과 조절 단백질과의 상호작용을 맡아요."]}, {"id": "b12", "u": "중심원리·전사", "t": "mc", "lv": 1, "q": "대장균 프로모터의 공통서열 중 −10 부위(프리브노 상자)의 서열은?", "c": ["5′-TATAAT-3′ (비주형·암호·센스 DNA)", "5′-TTGACA-3′ (비주형·암호·센스 DNA)", "5′-TATAAA-3′ (비주형·암호·센스 DNA)", "5′-AGGAGG-3′ (mRNA, 5′→3′)"], "a": 0, "ex": "프로모터 서열은 관례상 비주형(암호화·센스) DNA 가닥을 5′→3′로 써요. −35 부위는 5′-TTGACA-3′, −10 부위는 5′-TATAAT-3′(프리브노 상자)예요. 5′-TATAAA-3′는 진핵생물의 TATA 상자, 5′-AGGAGG-3′는 mRNA의 리보솜 결합 서열(SD)이에요. (주형(비암호·안티센스) 가닥에서 −10 부위는 3′-ATATTA-5′)", "ref": ["nb:n2", "nb:n3"], "s": "bio", "cx": ["−10 상자(프리브노)는 비주형 DNA 기준 5′-TATAAT-3′예요.", "−35 부위의 서열이에요.", "진핵생물의 TATA box(−25 부근)예요.", "DNA가 아니라 mRNA의 SD(샤인–달가노) 서열 5′-AGGAGG-3′예요(번역 개시)."]}, {"id": "b13", "u": "중심원리·전사", "t": "mc", "lv": 1, "q": "rho(ρ) 의존적 전사 종결에 대한 설명으로 옳은 것은?", "c": ["ρ 단백질이 RNA의 rut 부위(C가 풍부)에 결합한 뒤 ATP를 써서 헬리케이스 활성으로 RNA–DNA 혼성을 풀어 RNA를 떼어 낸다", "GC가 풍부한 역반복서열이 머리핀을 만들고 뒤의 U 연속 부위가 떨어져 나간다", "ρ 단백질이 DNA 주형가닥의 TATA 상자에 결합한다", "ρ 단백질은 진핵세포 RNA 중합효소 Ⅱ의 종결에 쓰인다"], "a": 0, "ex": "ρ 의존 종결: ① ρ가 새 RNA의 rut 부위에 결합 → ② ATP를 쓰며 RNA를 타고 이동 → ③ 중합효소가 멈춘 곳에서 RNA–DNA 혼성을 풀어 RNA를 떼어 내요. ②번 보기는 ρ 비의존 종결이에요.", "ref": ["bio6:3", "nb:n2"], "s": "bio", "cx": ["ρ가 rut(C 풍부)에 붙어 ATP로 RNA를 따라가 헬리케이스로 떼어 내요.", "ρ 비의존적(내재적) 종결에 대한 설명이에요.", "ρ는 DNA가 아니라 RNA에 결합해요. TATA는 진핵생물 프로모터예요.", "ρ는 원핵생물의 종결 인자예요."]}, {"id": "b14", "u": "중심원리·전사", "t": "mc", "lv": 1, "q": "rho(ρ) 비의존적 전사 종결에서 RNA가 DNA에서 쉽게 떨어져 나가는 이유는?", "c": ["머리핀 뒤의 U 연속 부위가 주형의 A와 약한 A–U 결합(수소결합 2개)을 이루기 때문", "ρ 단백질이 ATP를 분해하기 때문", "GC쌍은 수소결합이 2개라 약하기 때문", "σ 인자가 다시 결합하기 때문"], "a": 0, "ex": "GC가 풍부한 역반복서열이 단단한 머리핀을 만들어 중합효소를 멈추게 해요. 그 뒤의 U…U는 A와 결합하는데, A–U는 약해서 쉽게 떨어져요.", "ref": ["bio6:4", "nb:n4"], "s": "bio", "cx": ["U–A 결합은 약해서 머리핀으로 멈춘 RNA가 쉽게 떨어져요.", "ρ 비의존적 종결이라 ρ가 필요 없어요.", "GC는 수소결합이 3개라 강해요. 그래서 머리핀이 단단해요.", "σ는 개시에 쓰이고 종결과는 무관해요."]}, {"id": "b15", "u": "중심원리·전사", "t": "mc", "lv": 1, "q": "단일가닥 RNA가 자기상보적 염기쌍으로 복잡한 3차구조를 형성하여 단백질처럼 촉매 기능을 수행하는 것을 무엇이라 하는가?", "c": ["리보자임", "리보솜", "인트론", "폴리솜"], "a": 0, "ex": "단일가닥 RNA는 자기상보적 구조로 머리핀(2차구조), 나아가 3차구조까지 만들 수 있어요. 촉매 기능을 하는 RNA를 리보자임이라고 해요.", "ref": ["bio6:2", "nb:n4"], "s": "bio", "cx": ["리보자임 = 촉매 기능을 하는 RNA예요(예: rRNA의 펩티딜 전이).", "리보솜은 rRNA와 단백질로 된 번역 장치예요.", "인트론은 제거되는 비암호 서열이에요.", "폴리솜은 mRNA 하나에 리보솜 여러 개가 붙은 것이에요."]}, {"id": "b16", "u": "중심원리·전사", "t": "mc", "lv": 1, "q": "진핵세포에서 mRNA가 고리 모양의 폴리솜을 이루어 번역 효율을 높일 수 있는 이유는?", "c": ["5′ cap과 poly(A) 꼬리가 개시인자(eIF4E·eIF4G)와 poly(A) 결합 단백질을 통해 연결되기 때문", "mRNA가 원형 DNA에서 전사되기 때문", "인트론이 서로 결합하기 때문", "SD 서열이 3′ 끝에 있기 때문"], "a": 0, "ex": "5′ cap–eIF4E–eIF4G–PABP–poly(A)가 연결되어 mRNA가 고리 모양이 돼요. 번역을 마친 리보솜이 다시 개시코돈 근처로 쉽게 돌아올 수 있어요.", "ref": ["bio6:5", "nb:n4"], "s": "bio", "cx": ["cap–eIF4E–eIF4G–PABP–poly(A)로 양 끝이 연결되어 고리가 돼요.", "진핵생물 mRNA는 선형 염색체에서 전사돼요.", "인트론은 스플라이싱으로 제거돼요.", "SD 서열은 원핵생물에 있고 5′ 쪽에 있어요."]}, {"id": "b17", "u": "중심원리·전사", "t": "mc", "lv": 1, "q": "DNA 두 가닥 중 RNA 합성의 주형으로 쓰이는 가닥에 대한 설명으로 옳은 것은?", "c": ["주형가닥 = 안티센스 가닥 = (−)가닥이며, RNA는 이와 상보적으로 5′→3′ 방향으로 합성된다", "주형가닥 = 센스 가닥이며 mRNA와 서열이 같다", "RNA 중합효소는 주형가닥을 5′→3′ 방향으로 읽는다", "전사에는 프라이머가 반드시 필요하다"], "a": 0, "ex": "RNA 중합효소는 주형(안티센스, −)가닥을 3′→5′로 읽으며 RNA를 5′→3′로 합성해요. 비주형가닥(센스, +)은 mRNA와 서열이 같아요(T↔U만 다름). 전사에는 프라이머가 필요 없어요.", "ref": ["nb:n3", "nb:n2"], "s": "bio", "cx": ["주형 = 안티센스 = (−)가닥이에요. RNA는 상보적으로 5′→3′ 방향으로 합성돼요.", "센스(암호화) 가닥은 주형이 아니에요. mRNA와 서열이 같은(T↔U) 쪽이에요.", "주형은 3′→5′ 방향으로 읽어요.", "RNA 중합효소는 프라이머가 필요 없어요."]}, {"id": "b18", "u": "발현 조절 기초", "t": "mc", "lv": 1, "q": "tRNA, rRNA, 리보솜 단백질, RNA 중합효소처럼 하우스키핑 기능을 담당하는 단백질을 암호화하는 유전자는?", "c": ["구성성 유전자", "유도성 유전자", "억제성 유전자", "조절유전자"], "a": 0, "ex": "생존에 항상 필요하므로 지속적으로 발현되는 구성성 유전자예요.", "ref": ["bio6:7", "nb:n4"], "s": "bio", "cx": ["항상 발현되는 하우스키핑 유전자 = 구성성 유전자예요.", "유도성은 기질이 있을 때만 켜져요.", "억제성은 최종산물이 있으면 꺼져요.", "조절유전자는 억제인자 등을 만드는 유전자예요."]}, {"id": "b19", "u": "발현 조절 기초", "t": "mc", "lv": 1, "q": "이화경로에 관여하는 효소를 암호화하며, 그 기질이 있을 때에만 발현되는 유전자(예 젖당 분해 효소 유전자)는?", "c": ["유도성 유전자", "억제성 유전자", "구성성 유전자", "하우스키핑 유전자"], "a": 0, "ex": "유전자 발현을 촉진하는 기질을 유도성 물질, 촉진되는 유전자를 유도성 유전자라고 해요.", "ref": ["bio6:7"], "s": "bio", "cx": ["기질(유도물질)이 있을 때 켜지는 이화 유전자 = 유도성이에요.", "억제성은 동화 경로(최종산물이 있으면 꺼짐)예요.", "구성성은 항상 켜져 있어요.", "하우스키핑 = 구성성이에요."]}, {"id": "b20", "u": "발현 조절 기초", "t": "mc", "lv": 1, "q": "동화경로(예 트립토판 합성)에 관여하는 효소의 유전자는 최종산물이 있으면 발현이 중단된다. 이 유전자와 최종산물을 각각 무엇이라 하는가?", "c": ["억제성 유전자 – 억제성 물질", "유도성 유전자 – 유도성 물질", "구성성 유전자 – 보조활성인자", "조절유전자 – 활성인자"], "a": 0, "ex": "발현을 억제하는 최종산물을 억제성 물질(보조억제물질), 억제되는 유전자를 억제성 유전자라고 해요.", "ref": ["bio6:7"], "s": "bio", "cx": ["동화 경로 → 억제성 유전자예요. 최종산물은 억제성 물질(보조억제물질)이에요.", "유도성은 이화 경로에 해당해요.", "구성성은 조절되지 않아요.", "짝이 맞지 않아요."]}, {"id": "b21", "u": "발현 조절 기초", "t": "mc", "lv": 1, "q": "진핵생물 핵심 프로모터의 TATA box가 위치하는 곳(전사 개시점 = +1)은 대략?", "c": ["−25 부근", "−10 부근", "+30 부근", "−120 부근"], "a": 0, "ex": "TFIIB 인식 요소는 −35, TATA box(5′-TATAAA-3′, 비주형 DNA)는 −25, 개시자(Inr)는 +1, 하류 핵심 프로모터 요소는 +30 부근이에요. −10(5′-TATAAT-3′)은 원핵생물이에요.", "ref": ["bio6:8"], "s": "bio", "cx": ["진핵생물 TATA box는 약 −25(−25~−30)에 있어요.", "−10은 원핵생물의 프리브노 상자예요.", "프로모터는 개시점 앞(음수 쪽)에 있어요.", "CAAT/GC box 같은 근위 요소의 위치예요."]}, {"id": "b22", "u": "발현 조절 기초", "t": "mc", "lv": 1, "q": "진핵세포의 인핸서와 사일런서에 결합하는 단백질을 바르게 짝지은 것은?", "c": ["인핸서 – 전사 활성화 인자(activator), 사일런서 – 전사 억제 인자(repressor)", "인핸서 – 억제인자, 사일런서 – 활성인자", "둘 다 RNA 중합효소가 직접 결합", "인핸서 – σ 인자, 사일런서 – ρ 인자"], "a": 0, "ex": "인핸서는 전사 효율을 크게 높이는 영역(활성인자 결합), 사일런서는 전사를 억제하거나 잠재우는 영역(억제인자 결합)이에요. DNA가 휘어서 멀리서도 작용해요.", "ref": ["bio6:10", "nb:n4"], "s": "bio", "cx": ["인핸서에는 활성인자, 사일런서에는 억제인자가 결합해요.", "짝이 서로 바뀌었어요.", "중합효소는 핵심 프로모터에 결합해요.", "σ, ρ는 원핵생물의 인자예요."]}, {"id": "b23", "u": "발현 조절 기초", "t": "mc", "lv": 2, "q": "전사 개시 조절 4가지 중, \"최종산물(보조억제물질)이 억제인자를 활성화시켜 작동부위에 결합하게 함으로써 전사를 끄는\" 방식은?", "c": ["억제성 음성 조절", "유도성 음성 조절", "유도성 양성 조절", "억제성 양성 조절"], "a": 0, "ex": "산물이 신호이면 억제성, 억제인자(repressor)를 쓰면 음성이에요. 트립토판 오페론이 대표 예예요.", "sol": "<table class=\"t\"><tr><th></th><th>유도성 (기질 신호)</th><th>억제성 (산물 신호)</th></tr><tr><td>음성 (억제인자)</td><td>기질이 억제인자 비활성화 → ON (lac)</td><td>산물이 억제인자 활성화 → OFF (trp)</td></tr><tr><td>양성 (활성인자)</td><td>기질이 활성인자 활성화 → ON</td><td>산물이 활성인자 비활성화 → OFF</td></tr></table>", "ref": ["bio6:13", "bio6:11", "bio6:12"], "s": "bio", "cx": ["최종산물이 억제인자를 켬 → 억제성 + 억제인자 사용 → 음성 조절이에요(trp).", "유도성 음성은 유도물질이 억제인자를 떼어 내는 방식이에요(lac).", "활성인자를 쓰는 양성 조절이에요.", "최종산물이 활성인자를 끄는 방식이에요."]}, {"id": "b24", "u": "발현 조절 기초", "t": "mc", "lv": 2, "q": "유도성 양성 조절에 대한 설명으로 옳은 것은?", "c": ["유도물질이 활성인자에 결합해 활성인자가 DNA에 붙게 만들어 전사가 일어난다", "유도물질이 억제인자를 떼어 내 전사가 일어난다", "보조억제물질이 억제인자를 활성화한다", "최종산물이 활성인자를 비활성화한다"], "a": 0, "ex": "양성 = 활성인자(activator) 사용, 유도성 = 기질(유도물질)이 신호예요. 그러므로 유도물질이 활성인자를 활성화해 전사가 ON이 돼요.", "ref": ["bio6:11", "bio6:13"], "s": "bio", "cx": ["유도물질 + 활성인자 → DNA 결합 → 전사가 켜져요(예: ara, CAP).", "유도성 음성 조절이에요.", "억제성 음성 조절이에요.", "억제성 양성 조절이에요."]}, {"id": "b25", "u": "젖당 오페론", "t": "mc", "lv": 1, "q": "오페론의 구성요소가 아닌 것은?", "c": ["조절유전자(lacI)", "프로모터", "작동부위(operator)", "구조유전자"], "a": 0, "ex": "오페론 = 프로모터 + 작동부위 + 구조유전자예요. 조절유전자는 항상 발현되어 억제단백질을 만들지만 오페론의 요소에는 포함되지 않아요.", "ref": ["bio6:15", "bio6:14", "nb:n5"], "s": "bio", "cx": ["조절유전자는 오페론 밖에 따로 있어요(자체 프로모터) → 구성요소가 아니라서 정답이에요.", "오페론의 구성요소예요.", "오페론의 구성요소예요.", "오페론의 구성요소예요."]}, {"id": "b26", "u": "젖당 오페론", "t": "mc", "lv": 1, "q": "원핵세포 유전자 발현 조절의 특징으로 옳지 않은 것은?", "c": ["하나의 조절부위는 하나의 유전자만 조절한다", "전사속도는 프로모터에 대한 RNA 중합효소의 친화력에 의해 결정된다", "폴리시스트론 구조를 가진다", "일반적으로 조절부위는 구조유전자 바로 앞에 존재한다"], "a": 0, "ex": "원핵세포는 폴리시스트론이라서 하나의 조절부위가 여러 개의 유전자로 구성된 유전자군의 발현을 한꺼번에 조절해요.", "ref": ["bio6:16"], "s": "bio", "cx": ["원핵생물은 조절부위 하나가 여러 유전자를 함께 조절해요(오페론) → 옳지 않아 정답이에요.", "옳은 설명이에요.", "옳은 설명이에요.", "옳은 설명이에요."]}, {"id": "b27", "u": "젖당 오페론", "t": "mc", "lv": 1, "q": "lac 오페론 구조유전자와 그 산물의 짝으로 옳지 않은 것은?", "c": ["lacY – β-갈락토시다아제", "lacZ – β-갈락토시다아제", "lacY – β-갈락토시드 투과효소", "lacA – 티오갈락토시드 아세틸기 전이효소"], "a": 0, "ex": "lacZ → β-갈락토시다아제(젖당 분해), lacY → 투과효소(젖당 유입), lacA → 아세틸기 전이효소예요.", "ref": ["bio6:17", "nb:n5"], "s": "bio", "cx": ["lacY는 투과효소예요. β-갈락토시다아제는 lacZ예요 → 틀린 짝이라 정답이에요.", "바른 짝이에요.", "바른 짝이에요.", "바른 짝이에요."]}, {"id": "b28", "u": "젖당 오페론", "t": "txt", "lv": 1, "q": "젖당 오페론에서 억제인자에 결합하여 억제를 해제하는 '진짜' 유도체(β1-6 결합 이당류)의 이름은? (단답)", "a": ["알로락토오스", "알로락토스", "allolactose", "1,6-알로락토오스", "16알로락토오스"], "ex": "젖당(β1-4)이 유입되면 β-갈락토시다아제가 일부를 분해했다가 재결합해 알로락토오스(β1-6)를 만들어요. 이것이 억제인자를 해제해요.", "ref": ["nb:n7", "bio6:18"], "s": "bio"}, {"id": "b29", "u": "젖당 오페론", "t": "mc", "lv": 2, "q": "IPTG에 대한 설명으로 옳은 것은?", "c": ["억제인자에 결합해 유도하지만 β-갈락토시다아제에 의해 분해되지 않아 유도 상태가 계속 유지된다", "억제인자를 활성화해 전사를 끈다", "CAP에 결합해 cAMP를 대신한다", "β-갈락토시다아제의 기질이라 빠르게 분해된다"], "a": 0, "ex": "IPTG는 알로락토오스와 비슷해서 억제인자를 떼어 내지만, β-갈락토시다아제로 분해되지 않는 인공 유도물질이에요.", "ref": ["nb:n5"], "s": "bio", "cx": ["IPTG는 분해되지 않는 유도물질이라 유도가 계속 유지돼요.", "억제인자를 비활성화해 전사를 켜요.", "CAP–cAMP와는 관계없어요.", "β-갈락토시다아제가 분해하지 못해요."]}, {"id": "b30", "u": "젖당 오페론", "t": "mc", "lv": 1, "q": "lac 억제인자가 가장 강하게 결합하는 주작동부위는?", "c": ["O₁", "O₂", "O₃", "CAP 결합부위"], "a": 0, "ex": "O₁이 주작동부위이고, O₂(lacZ 안)와 O₃(lacI 쪽)는 보조작동부위예요.", "ref": ["bio6:19", "nb:n9"], "s": "bio", "cx": ["주작동부위 O₁에 가장 강하게 결합해요.", "O₂는 보조 작동부위예요(DNA 고리 형성).", "O₃는 보조 작동부위예요.", "CAP 결합부위에는 cAMP–CAP이 결합해요."]}, {"id": "b31", "u": "젖당 오페론", "t": "mc", "lv": 1, "q": "작동부위에 돌연변이가 생긴 Oᶜ의 결과로 옳은 것은?", "c": ["lac 억제인자에 대한 친화력이 감소해 젖당 유무와 상관없이 구성적으로 발현된다", "억제인자가 더 강하게 결합해 항상 꺼진다", "RNA 중합효소가 결합하지 못한다", "유도체에 대한 친화력이 사라진다"], "a": 0, "ex": "Oᶜ는 억제인자가 잘 붙지 못하는 작동부위예요. 그래서 젖당이 없어도 전사가 일어나요(구성적 발현).", "ref": ["bio6:19", "nb:n7"], "s": "bio", "cx": ["억제인자가 잘 붙지 못해 항상 발현돼요(구성성, 시스 우성).", "반대예요.", "프로모터 돌연변이일 때의 이야기예요.", "유도체와 결합하는 것은 억제인자예요."]}, {"id": "b32", "u": "젖당 오페론", "t": "mc", "lv": 2, "q": "I⁺ P⁺ Oᶜ Z⁺ / I⁺ P⁺ O⁺ Z⁻ 부분 이배체에서 β-갈락토시다아제의 발현 양상은? (포도당 고갈)", "c": ["구성적 발현", "유도성 발현", "발현 불능", "젖당 있을 때만 절반 발현"], "a": 0, "ex": "Oᶜ는 같은 DNA에 있는 Z⁺만 조절하는 cis 작용을 해요. Oᶜ와 같은 분자에 있는 Z⁺는 억제인자가 있어도 항상 발현돼요.", "ref": ["bio6:21", "nb:n5"], "s": "bio", "cx": ["Oᶜ와 같은 가닥(시스)에 Z⁺가 있어 젖당이 없어도 발현돼요 → 구성적이에요.", "다른 가닥 O⁺Z⁻는 Z가 고장이라 효소를 만들지 못해요.", "Z⁺가 하나 있어요.", "Oᶜ는 시스로 항상 작동해요."]}, {"id": "b33", "u": "젖당 오페론", "t": "mc", "lv": 2, "q": "F′ I⁻ O⁺ Z⁺ / I⁺ O⁺ Z⁺ 의 β-갈락토시다아제 발현 양상은? (포도당 고갈)", "c": ["유도성", "구성성", "불능", "젖당 없을 때만 발현"], "a": 0, "ex": "I⁺가 만든 억제단백질은 세포질로 확산돼 양쪽 DNA의 작동부위에 모두 결합할 수 있어요(trans). 그래서 I⁻ 결함이 보완되어 유도성이 돼요.", "ref": ["nb:n6", "bio6:21"], "s": "bio", "cx": ["I⁺ 억제인자는 트랜스로 양쪽 O⁺에 모두 작용해요 → I⁻가 가려져 유도성이에요.", "I⁻는 열성이라 구성성이 되지 않아요.", "Z⁺가 있어 효소를 만들 수 있어요.", "젖당이 있을 때 발현돼요."]}, {"id": "b34", "u": "젖당 오페론", "t": "mc", "lv": 2, "q": "F′ I⁻ Oᶜ Z⁺ / I⁺ O⁺ Z⁻ 의 β-갈락토시다아제 발현 양상은? (포도당 고갈)", "c": ["구성성", "유도성", "불능", "발현 없음"], "a": 0, "ex": "기능하는 Z⁺는 F′ 위에 있고, 같은 분자에 Oᶜ가 있어요. 억제인자(I⁺ 유래)가 있어도 Oᶜ에는 결합하지 못하므로 구성성이에요.", "ref": ["nb:n6"], "s": "bio", "cx": ["Oᶜ–Z⁺가 같은 가닥(시스)이라 항상 발현돼요 → 구성성이에요.", "구성적인 Oᶜ–Z⁺가 있어요.", "Z⁺가 있어요.", "Oᶜ–Z⁺에서 발현돼요."]}, {"id": "b35", "u": "젖당 오페론", "t": "mc", "lv": 3, "q": "F′ I⁺ Oᶜ Z⁻ / I⁺ O⁺ Z⁺ 의 β-갈락토시다아제 발현 양상은? (포도당 고갈)", "c": ["유도성", "구성성", "불능", "구성성이지만 절반만 발현"], "a": 0, "ex": "Oᶜ는 cis라 같은 분자의 Z⁻만 켜는데, Z⁻는 기능이 없어요. 기능하는 Z⁺는 O⁺와 같은 분자에 있고 억제인자(I⁺)가 있으므로 유도성이에요.", "sol": "<b>함정 문제</b>: Oᶜ가 있다고 무조건 구성성이 아니에요. \"<u>Oᶜ와 같은 DNA 위에 Z⁺가 있는가</u>\"를 꼭 확인하세요.", "ref": ["bio6:21", "nb:n6"], "s": "bio", "cx": ["Oᶜ 쪽은 Z⁻라 효소가 없어요. O⁺Z⁺ 쪽은 I⁺로 조절돼 → 유도성이에요.", "Oᶜ와 같은 가닥의 Z가 고장이라 구성성이 될 수 없어요.", "Z⁺(O⁺ 쪽)가 있어요.", "Oᶜ 쪽에서는 효소가 전혀 나오지 않아요."]}, {"id": "b36", "u": "젖당 오페론", "t": "mc", "lv": 2, "q": "Iˢ 돌연변이(억제인자가 알로락토오스와 결합하지 못함)를 가진 $I^{s}$ O⁺ Z⁺ 대장균의 발현 양상은?", "c": ["불능 (젖당이 있어도 발현 안 됨)", "구성성", "유도성", "포도당이 있을 때만 발현"], "a": 0, "ex": "Iˢ 억제인자는 유도체가 붙지 못하니 작동부위에서 떨어지지 않아요. 그래서 젖당이 있어도 전사가 안 돼요(불능, super-repressor).", "ref": ["nb:n9", "nb:n6"], "s": "bio", "cx": ["Iˢ 억제인자는 유도물질과 결합하지 못해 항상 붙어 있어요 → 불능이에요.", "억제인자가 계속 붙어 있어 구성성이 될 수 없어요.", "젖당이 있어도 떨어지지 않아요.", "포도당이 있으면 오히려 더 억제돼요."]}, {"id": "b37", "u": "젖당 오페론", "t": "mc", "lv": 2, "q": "필기에 정리한 조절유전자 돌연변이 중 'Iᵈ'의 특징으로 옳은 것은?", "c": ["억제인자가 작동부위(operator)와 결합하지 못해 구성성이 되며, I⁻보다 우성이다", "억제인자가 알로락토오스와 결합하지 못해 불능이 된다", "억제인자가 만들어지지 않아 열성 구성성이 된다", "억제인자가 CAP과 결합하지 못한다"], "a": 0, "ex": "I⁻는 억제인자 자체가 없어서 구성성이에요. Iˢ는 알로락토오스 결합 ✗이라 불능, Iᵈ는 작동부위 결합 ✗이라 구성성이에요. 필기 기준 우열은 Iˢ > I⁻, Iᵈ > I⁻예요.", "ref": ["nb:n9"], "s": "bio", "cx": ["Iᵈ는 작동부위에 결합하지 못하는 억제인자예요. 사량체에 섞여 정상 억제인자까지 망가뜨려 우성(음성 우성)이에요.", "Iˢ에 대한 설명이에요.", "I⁻에 대한 설명이에요.", "억제인자와 CAP은 관계없어요."]}, {"id": "b38", "u": "젖당 오페론", "t": "mc", "lv": 1, "q": "대장균이 포도당이 없는 환경에 있을 때 cAMP와 CAP의 상태로 옳은 것은?", "c": ["아데닐산 고리화효소가 활성화되어 cAMP↑ → cAMP–CAP 복합체가 CAP 결합부위에 붙어 전사 촉진", "cAMP↓ → CAP이 억제인자로 작용", "cAMP↑ → CAP이 작동부위에 붙어 전사 억제", "cAMP 변화 없음"], "a": 0, "ex": "포도당이 고갈되면 AC가 켜져 ATP에서 cAMP를 만들어요. cAMP–CAP이 CAP 결합부위에 붙으면 DNA가 휘어져 RNA 중합효소가 프로모터에 더 잘 결합해요(양성 조절).", "ref": ["nb:n9", "nb:n6"], "s": "bio", "cx": ["포도당이 없으면 cAMP↑ → cAMP–CAP이 CAP 결합부위에 붙어 RNA 중합효소를 도와요(양성 조절).", "포도당이 없으면 cAMP는 증가해요.", "CAP은 작동부위가 아니라 CAP 결합부위에서 활성화를 도와요.", "cAMP가 증가해요."]}, {"id": "b39", "u": "젖당 오페론", "t": "mc", "lv": 2, "q": "이중생장곡선 Ⅰ(포도당 있음) – Ⅱ(정체) – Ⅲ(젖당 이용) 구간에서, Ⅱ 구간에 대한 설명으로 옳은 것은?", "c": ["포도당이 고갈되어 cAMP가 많아지고, 젖당 분해 효소를 새로 만드는 데 시간이 걸려 생장이 잠시 멈춘다", "포도당과 젖당을 동시에 쓰고 있다", "cAMP가 거의 없어 CAP이 작동하지 않는다", "억제인자가 작동부위에 결합해 젖당을 쓸 수 없는 구간이다"], "a": 0, "ex": "박신 표: Ⅰ에서는 포도당 ○, AC 꺼짐, cAMP 적음, CAP 꺼짐 / Ⅱ·Ⅲ에서는 포도당 ✗, AC 켜짐, cAMP 많음, CAP 켜짐. Ⅱ는 효소를 합성하는 적응기예요.", "ref": ["nb:n6", "nb:n9"], "s": "bio", "cx": ["포도당이 소진된 뒤 lac 효소를 새로 만드는 동안 생장이 멈춰요(지체기).", "포도당을 우선 이용하고(이화물 억제), 동시에 쓰지 않아요.", "cAMP가 증가하는 시점이에요.", "젖당이 있으면 억제인자가 떨어져요. 효소를 준비하는 시간이에요."]}, {"id": "b40", "u": "젖당 오페론", "t": "mc", "lv": 1, "q": "필기의 '심화 2'에 따르면, lac 오페론에 대한 설명으로 옳은 것은?", "c": ["on/off가 아니라 more/less로, 젖당이 없어도 기저 수준에서 소량 발현된다", "젖당이 없으면 β-갈락토시다아제가 전혀 없다", "포도당이 있으면 투과효소가 분해된다", "알로락토오스는 세포 밖에서 만들어진다"], "a": 0, "ex": "세포질에 소량의 β-갈락토시다아제와 투과효소가 늘 있어요. 그래서 젖당이 들어오면 알로락토오스가 만들어질 수 있어요. 젖당이 대량 유입되면 발현량이 증가해요.", "ref": ["nb:n7"], "s": "bio", "cx": ["기저 발현이 있어야 젖당이 들어와 알로락토오스로 바뀔 수 있어요(more/less).", "기저 수준의 소량은 있어요.", "포도당은 유입을 막을 뿐 투과효소를 분해하지 않아요.", "세포 안에서 β-갈락토시다아제가 만들어요."]}, {"id": "b41", "u": "젖당 오페론", "t": "num", "lv": 2, "q": "작동부위 조합별 억제 배수가 O₁ 단독 약 18배, O₁+O₂+O₃ 약 1300배이다. 보조작동부위 O₂, O₃를 동시에 돌연변이시켜 O₁만 남기면 억제 능력은 약 몇 배 감소하는가? (정수, 근삿값)", "a": 72.0, "tol": 0.12, "unit": "배", "ex": "1300 ÷ 18 ≈ 72배예요. 서술 기출의 \"O₂·O₃ 동시 돌연변이 → 억제 능력 약 70배 감소\"와 같은 결과예요.", "sol": "$1300/18 \\approx 72$ → 약 70배. O₂·O₃가 O₁과 함께 억제인자에 결합해 <b>DNA 고리</b>를 만들어야 억제가 아주 강해져요.", "ref": ["nb:n7", "nb:n8", "bio6:20"], "s": "bio"}, {"id": "b42", "u": "젖당 오페론", "t": "mc", "lv": 2, "q": "억제인자 농도에 따른 작동부위 결합률 그래프에서, Oᶜ(돌연변이)에 대한 설명으로 옳은 것은?", "c": ["억제인자 농도가 낮으면 거의 결합하지 못하지만, 농도가 매우 높으면 결합할 수 있다(Kd가 크다)", "어떤 농도에서도 결합률이 0이다", "O⁺보다 낮은 농도에서 포화된다", "O 결손과 그래프가 같다"], "a": 0, "ex": "심화 3에 따르면 O 결손은 결합 자체가 불가능하고(그래프가 0에 붙음), Oᶜ는 낮은 농도에서는 결합이 안 되지만 높은 농도에서는 극복돼요(곡선이 오른쪽으로 이동).", "ref": ["nb:n7", "bio6:19"], "s": "bio", "cx": ["친화력이 낮아(Kd↑) 곡선이 오른쪽으로 이동해요. 농도가 아주 높으면 결합해요.", "결합률이 완전히 0인 것은 아니에요.", "O⁺보다 높은 농도가 필요해요.", "O 결손이면 어떤 농도에서도 결합하지 못해요."]}, {"id": "b43", "u": "트립토판 오페론", "t": "mc", "lv": 1, "q": "트립토판(trp) 오페론의 1단계 억제에서, 트립토판의 역할은?", "c": ["보조억제물질로서 비활성 억제단백질에 결합해 활성화시킨다", "유도물질로서 억제단백질을 떼어 낸다", "활성인자로서 RNA 중합효소를 끌어온다", "CAP과 결합한다"], "a": 0, "ex": "trpR가 만든 억제단백질은 원래 비활성(아포억제인자)이에요. 트립토판이 붙어야 활성이 되어 작동부위에 결합해요(전사 약 70배 감소).", "ref": ["nb:n10"], "s": "bio", "cx": ["Trp가 보조억제물질로 trpR 억제단백질을 활성화 → 작동부위에 결합해요.", "유도물질이 아니에요(lac와 반대).", "활성인자가 아니에요.", "CAP과는 무관해요."]}, {"id": "b44", "u": "트립토판 오페론", "t": "mc", "lv": 2, "q": "[Trp]가 높을 때 감쇠(attenuation)가 일어나는 과정으로 옳은 것은?", "c": ["Trp-tRNA가 충분 → 리보솜이 리더 mRNA 영역 1(5′-UGG UGG-3′)을 빠르게 통과 → 영역 2를 덮음 → 3:4 종결자 형성 → 전사 일찍 종결", "리보솜이 영역 1에서 멈춤 → 2:3 항종결자 형성 → 전사 계속", "Trp-tRNA 부족 → 1:2 머리핀만 형성", "억제단백질이 리더 서열에 결합"], "a": 0, "ex": "[Trp]↑ → 리보솜 빠름 → 3:4 종결자 → 짧은 mRNA(약 140 nt) → trpE~A 전사 안 됨.", "ref": ["nb:n10"], "s": "bio", "cx": ["Trp가 많으면 리보솜이 빨리 지나가 2를 덮고 3:4 종결자가 생겨 종결돼요.", "[Trp]가 낮을 때의 상황이에요.", "Trp-tRNA가 부족하면 2:3이 생겨요.", "감쇠는 단백질이 아니라 RNA 구조로 조절돼요."]}, {"id": "b45", "u": "트립토판 오페론", "t": "mc", "lv": 2, "q": "[Trp]가 낮아 리보솜이 리더 mRNA 영역 1의 5′-UGG-3′ 코돈에서 멈추었을 때 형성되는 구조와 결과는?", "c": ["2:3 항종결자 → 3:4가 만들어지지 못해 전사 계속 → 긴 mRNA", "3:4 종결자 → 전사 종결", "1:2 + 3:4 → 전사 종결", "아무 구조도 없음 → 번역 중단"], "a": 0, "ex": "리보솜이 영역 1에 머물면 영역 2가 자유로워져 영역 3과 2:3 쌍을 이뤄요. 영역 3이 묶이니 3:4 종결자가 생기지 못해 전사가 계속돼요.", "ref": ["nb:n10"], "s": "bio", "cx": ["리보솜이 1에 멈추면 2와 3이 짝지어(항종결자) 3:4가 생기지 않아 전사가 계속돼요.", "[Trp]가 높을 때의 결과예요.", "리보솜이 없을 때의 결과예요.", "2:3 구조가 생겨요."]}, {"id": "b46", "u": "트립토판 오페론", "t": "mc", "lv": 2, "q": "리더 서열의 번역이 전혀 일어나지 않을 때(리보솜 없음) 형성되는 구조는?", "c": ["1:2 + 3:4 → 전사 종결", "2:3 → 전사 계속", "1:2만 → 전사 계속", "2:3 + 1:4"], "a": 0, "ex": "리보솜이 없으면 먼저 합성되는 1이 2와 쌍을 이루고(1:2), 남은 3이 4와 3:4 종결자를 만들어 전사가 종결돼요.", "ref": ["nb:n10"], "s": "bio", "cx": ["리보솜이 없으면 1:2가 먼저 생기고 이어서 3:4 → 종결돼요.", "리보솜이 1에서 멈출 때의 구조예요.", "3:4도 함께 생겨 종결돼요.", "이런 조합은 생기지 않아요."]}, {"id": "b47", "u": "트립토판 오페론", "t": "mc", "lv": 1, "q": "감쇠 조절이 원핵생물에서 가능한 근본적인 이유는?", "c": ["전사와 번역이 동시에 일어나기 때문", "핵막이 있어 전사와 번역이 분리되기 때문", "RNA 중합효소가 3종류이기 때문", "오페론이 없기 때문"], "a": 0, "ex": "원핵생물은 핵막이 없어서 mRNA가 합성되는 도중에 리보솜이 번역을 시작해요. 리보솜의 속도가 RNA 2차구조 형성에 영향을 줄 수 있어요.", "ref": ["nb:n10"], "s": "bio", "cx": ["핵막이 없어 전사 중인 mRNA를 리보솜이 바로 번역해요 → 리보솜 위치가 RNA 구조를 결정해요.", "그건 진핵생물이에요. 그래서 감쇠가 불가능해요.", "원핵생물의 RNA 중합효소는 1종류예요.", "trp 오페론이 있어요."]}, {"id": "b48", "u": "트립토판 오페론", "t": "mc", "lv": 3, "q": "리더 mRNA 영역 1의 5′-UGG UGG-3′(트립토판 코돈)를 5′-GGU GGU-3′(글리신 코돈)로 바꾼 돌연변이에서, 감쇠 조절은 무엇에 반응하게 되겠는가?", "c": ["글리신(Gly-tRNA)의 양", "트립토판의 양", "젖당의 유무", "감쇠가 완전히 사라지고 항상 종결"], "a": 0, "ex": "리보솜이 멈추는지 여부는 영역 1 코돈에 해당하는 아미노아실-tRNA 공급에 달려 있어요. 글리신이 부족하면 멈춰서 2:3 → 전사 계속, 충분하면 3:4 → 종결이 돼요.", "ref": ["nb:n10"], "s": "bio", "cx": ["멈춤 코돈이 Gly 코돈이 되면 Gly-tRNA가 부족할 때 멈춰요 → 글리신에 반응해요.", "UGG가 사라져 Trp에는 반응하지 않아요.", "lac 오페론과 관계없어요.", "리보솜 멈춤 기작은 그대로 남아요."]}, {"id": "b49", "u": "트립토판 오페론", "t": "mc", "lv": 2, "q": "trp 오페론 조절에 관한 설명으로 옳지 않은 것은?", "c": ["trp 오페론은 유도성 음성 조절의 대표 예이다", "억제단백질 유전자 trpR은 오페론과 멀리 떨어져 있다", "구조유전자는 trpE·D·C·B·A 5개이다", "억제 단계와 감쇠 단계, 두 단계로 발현이 조절된다"], "a": 0, "ex": "trp 오페론은 억제성 음성 조절이에요. 유도성 음성 조절의 대표는 lac 오페론이에요.", "ref": ["nb:n10", "bio6:13"], "s": "bio", "cx": ["trp는 억제성 음성 조절이에요(lac가 유도성 음성) → 옳지 않아 정답이에요.", "옳은 설명이에요.", "옳은 설명이에요.", "옳은 설명이에요(억제 + 감쇠)."]}, {"id": "b50", "u": "발현 조절 기초", "t": "mc", "lv": 1, "q": "다세포 생물에서 모든 세포의 유전자는 같지만 세포마다 구조와 기능이 다른 이유는?", "c": ["세포의 종류에 따라 발현되는 유전자의 종류가 다르기 때문", "세포마다 DNA 염기서열이 다르기 때문", "세포마다 염색체 수가 다르기 때문", "분화된 세포는 유전자를 잃기 때문"], "a": 0, "ex": "세포 분화는 유전자 발현 조절의 결과예요. 필요한 시기·장소에서 필요한 유전자만 발현돼요.", "ref": ["bio6:6"], "s": "bio", "cx": ["DNA는 같고 어떤 유전자가 켜지느냐(선택적 발현)가 달라요 → 분화예요.", "체세포는 DNA 서열이 같아요.", "염색체 수도 같아요.", "유전자를 잃지 않아요(핵이식 실험)."]}, {"id": "bE1", "u": "유전자와 단백질", "t": "essay", "q": "비들과 테이텀의 붉은빵곰팡이 실험 과정을 쓰고, 이 실험으로부터 1유전자 1효소설을 이끌어 낸 논리를 서술하시오.", "kp": ["붉은빵곰팡이 포자에 X선 조사 → 돌연변이 유발", "완전배지에서는 자라지만 최소배지에서 자라지 못하는 영양요구성 돌연변이주 선별", "최소배지에 오르니틴/시트룰린/아르지닌을 하나씩 첨가해 생장 여부 확인", "Ⅰ·Ⅱ·Ⅲ형이 각각 다른 단계(효소 a·b·c)가 결손됨", "하나의 유전자 돌연변이가 하나의 효소 결손을 일으킴 → 1유전자 1효소설"], "sol": "야생형 붉은빵곰팡이 포자에 X선을 쪼여 돌연변이를 유도한 뒤, 완전배지에서는 자라지만 최소배지에서는 자라지 못하는 영양요구성 돌연변이주를 골라낸다. 이들을 최소배지에 오르니틴, 시트룰린, 아르지닌을 각각 첨가한 배지에서 배양하면, Ⅰ형은 오르니틴부터, Ⅱ형은 시트룰린부터, Ⅲ형은 아르지닌을 넣어야만 생장한다. 이는 각 돌연변이주가 아르지닌 합성 경로의 서로 다른 한 단계(효소 a, b, c)만 결손되었음을 뜻하며, X선으로 하나의 유전자에만 돌연변이가 생겼다고 가정하면 \"하나의 유전자는 하나의 특정 효소의 합성에 관여한다\"는 1유전자 1효소설을 이끌어 낼 수 있다.", "ref": ["bio5:6", "bio5:8", "nb:n1"], "s": "bio", "lv": 0, "ex": null}, {"id": "bE2", "u": "젖당 오페론", "t": "essay", "q": "포도당이 없고 젖당이 있는 환경에서 대장균의 lac 오페론 구조유전자가 높은 수준으로 전사되는 과정을 억제인자와 CAP의 작용을 모두 포함하여 서술하시오.", "kp": ["젖당 일부가 β-갈락토시다아제에 의해 알로락토오스로 전환", "알로락토오스가 억제인자에 결합 → 억제인자 구조 변화 → 작동부위(O₁)에서 떨어짐 (음성 조절 해제)", "포도당 고갈 → 아데닐산 고리화효소 활성 → cAMP 증가", "cAMP–CAP 복합체가 CAP 결합부위에 결합 → RNA 중합효소의 프로모터 결합 촉진 (양성 조절)", "lacZ·lacY·lacA가 하나의 mRNA로 전사(폴리시스트론)"], "sol": "세포 내에 소량 존재하는 투과효소와 β-갈락토시다아제에 의해 젖당 일부가 알로락토오스로 전환된다. 알로락토오스는 lac 억제인자에 결합해 구조를 바꾸어 억제인자가 작동부위에서 떨어지게 한다(음성 조절 해제). 동시에 포도당이 고갈되어 아데닐산 고리화효소가 활성화되고 cAMP 농도가 증가하면, cAMP–CAP 복합체가 CAP 결합부위에 결합하여 DNA를 휘게 하고 RNA 중합효소가 프로모터에 결합하는 것을 촉진한다(양성 조절). 그 결과 lacZ, lacY, lacA가 하나의 mRNA로 높은 수준으로 전사된다.", "ref": ["nb:n5", "nb:n9", "bio6:18"], "s": "bio", "lv": 0, "ex": null}, {"id": "bE3", "u": "트립토판 오페론", "t": "essay", "q": "trp 오페론의 감쇠(attenuation) 조절을 [Trp]가 높을 때와 낮을 때로 나누어 리보솜의 위치와 리더 mRNA의 2차구조 변화를 중심으로 서술하시오.", "kp": ["리더 mRNA에 트립토판 코돈(5′-UGG UGG-3′)이 있는 영역 1이 존재", "[Trp]↑ → Trp-tRNA 충분 → 리보솜이 영역 1을 빨리 지나 영역 2를 덮음", "영역 3:4 종결자(머리핀 + U 연속) 형성 → 전사 조기 종결", "[Trp]↓ → 리보솜이 5′-UGG-3′ 코돈에서 정지 → 영역 2:3 항종결자 형성", "3:4가 형성되지 못해 전사가 계속 → 구조유전자 전사", "원핵생물은 전사·번역이 동시에 일어나므로 가능"], "sol": "trp 리더 mRNA에는 트립토판 코돈(5′-UGG UGG-3′)을 가진 영역 1과, 서로 쌍을 이룰 수 있는 영역 2, 3, 4가 있다. [Trp]가 높으면 Trp-tRNA가 충분하여 리보솜이 영역 1을 빠르게 지나 영역 2까지 덮으므로 영역 3과 4가 3:4 종결자(머리핀)를 형성해 전사가 일찍 끝난다. [Trp]가 낮으면 리보솜이 영역 1의 5′-UGG-3′ 코돈에서 멈추고, 자유로워진 영역 2가 영역 3과 2:3 항종결자를 이루어 3:4 종결자가 형성되지 못하므로 전사가 계속되어 구조유전자가 전사된다. 이는 원핵생물에서 전사와 번역이 동시에 일어나기 때문에 가능하다.", "ref": ["nb:n10"], "s": "bio", "lv": 0, "ex": null}, {"id": "bE4", "u": "젖당 오페론", "t": "essay", "q": "I⁺P⁺OᶜZ⁺ / I⁺P⁺O⁺Z⁻ 와 I⁻P⁺O⁺Z⁺ / I⁺P⁺O⁺Z⁻ 의 발현 양상을 각각 판정하고, 작동부위와 조절유전자의 작용 방식(cis/trans) 차이로 설명하시오.", "kp": ["첫째: 구성성 (Oᶜ와 같은 분자의 Z⁺)", "둘째: 유도성", "작동부위는 DNA 서열 자체 → 같은 DNA 분자의 유전자만 조절 (cis)", "조절유전자 산물(억제단백질)은 확산 가능 → 다른 DNA에도 작용 (trans)", "I⁺의 억제단백질이 I⁻쪽 작동부위에도 결합해 결함을 보완"], "sol": "첫째 이배체는 구성성이다. 작동부위(Oᶜ)는 단백질을 만들지 않는 DNA 서열이므로 같은 DNA 분자 위의 유전자만 조절하는 cis 작용을 하며, Oᶜ에는 억제인자가 결합하지 못하므로 같은 분자의 Z⁺가 젖당 유무와 관계없이 발현된다. 둘째 이배체는 유도성이다. 조절유전자 I⁺가 만든 억제단백질은 세포질로 확산되어 다른 DNA 분자의 작동부위에도 결합할 수 있는 trans 작용을 하므로, I⁻ 결함이 보완되어 젖당이 있을 때만 발현된다.", "ref": ["bio6:21", "nb:n5", "nb:n6"], "s": "bio", "lv": 0, "ex": null}, {"id": "bE5", "u": "젖당 오페론", "t": "essay", "q": "[서술 기출] 작동자1(+11)을 돌연변이시키면 억제가 전혀 일어나지 않고, 작동자2(+412) 또는 작동자3(−82)을 각각 돌연변이시키면 억제 능력이 2배, 둘 다 돌연변이시키면 70배 감소하였다. 세 작동자가 어떤 상관관계로 발현을 억제하는지 설명하시오.", "kp": ["작동자1(O₁)은 주작동자 – 억제의 필수 부위", "O₂·O₃는 보조작동자 – 단독으로는 효과 작음", "억제단백질(사량체)이 O₁과 O₂ 또는 O₃에 동시에 결합", "DNA 고리 형성 → 억제 효율 크게 증가", "O₂, O₃는 서로 대체 가능(하나만 있어도 대부분 기능) → 하나만 망가지면 2배, 둘 다 망가지면 70배"], "sol": "작동자1이 없으면 억제가 전혀 일어나지 않으므로 작동자1은 억제에 반드시 필요한 주작동자이다. 작동자2와 3은 RNA 중합효소의 결합을 직접 방해하지 못하는 보조작동자로, 억제단백질(사량체)이 작동자1과 동시에 작동자2 또는 3에 결합하면 DNA가 고리 구조를 이루어 억제가 크게 강화된다. 작동자2와 3은 서로를 대체할 수 있어 하나만 돌연변이되면 억제 능력이 2배만 감소하지만, 둘 다 돌연변이되면 고리를 만들 수 없어 70배 감소한다.", "ref": ["nb:n8", "nb:n7"], "s": "bio", "lv": 0, "ex": null}, {"id": "bE6", "u": "젖당 오페론", "t": "essay", "q": "lac 억제단백질이 수행하는 기능들을 종합할 때, 이 단백질은 어떤 도메인들로 구성되어 있을지 설명하시오.", "kp": ["작동부위 DNA에 결합하는 DNA 결합 도메인", "유도체(알로락토오스)가 결합하는 도메인", "다른 소단위와 결합해 이량체/사량체를 이루는 다량체 형성 도메인", "(유도체 결합 시 구조가 바뀌어 DNA 결합력 감소 – 알로스테릭)"], "sol": "억제단백질은 ① 작동부위 DNA 서열을 인식해 결합하는 DNA 결합 도메인, ② 유도체(알로락토오스)가 결합하여 단백질의 입체구조를 바꾸는 유도체 결합 도메인, ③ 2개 또는 4개의 단백질이 서로 결합해 이량체·사량체를 형성하는(O₁과 O₂/O₃에 동시 결합해 DNA 고리를 만드는 데 필요) 다량체 형성 도메인으로 구성되어 있을 것이다.", "ref": ["nb:n8"], "s": "bio", "lv": 0, "ex": null}, {"id": "bE7", "u": "중심원리·전사", "t": "essay", "q": "원핵세포의 rho 의존적 전사 종결과 rho 비의존적 전사 종결을 비교하여 서술하시오.", "kp": ["의존: ρ 단백질이 새 RNA의 rut 부위(C 풍부)에 결합", "의존: ATP를 사용해 RNA를 따라 이동, 헬리케이스 활성으로 RNA–DNA 분리", "비의존: 단백질 없이 DNA 서열만으로 종결", "비의존: GC가 풍부한 역반복서열 → RNA 머리핀 → 중합효소 정지", "비의존: 뒤따르는 U 연속(A–U 약한 결합)으로 RNA 이탈"], "sol": "rho 의존적 종결에서는 ρ 단백질이 전사된 RNA의 rut 부위(C가 풍부)에 결합한 뒤 ATP를 사용하며 RNA를 따라 이동하고, 종결 부위에서 멈춘 RNA 중합효소를 따라잡아 헬리케이스 활성으로 RNA–DNA 혼성을 풀어 RNA를 떼어 낸다. rho 비의존적 종결은 단백질 없이 DNA 서열만으로 일어나며, GC가 풍부한 역반복서열이 전사되면 RNA가 안정한 머리핀을 만들어 중합효소를 멈추게 하고, 그 뒤의 U 연속 부위는 주형의 A와 약한 결합을 하므로 RNA가 쉽게 떨어져 나간다.", "ref": ["bio6:3", "bio6:4"], "s": "bio", "lv": 0, "ex": null}, {"id": "bE8", "u": "발현 조절 기초", "t": "essay", "q": "유도성 유전자와 억제성 유전자가 각각 어떤 대사 경로에 관여하는지와, 이러한 조절 방식이 세균에게 유리한 이유를 서술하시오.", "kp": ["유도성: 이화경로 효소 – 기질이 있을 때만 발현 (lac)", "억제성: 동화경로 효소 – 최종산물이 있으면 발현 중단 (trp)", "필요할 때만 효소를 만들어 에너지·물질 낭비 방지", "환경 변화에 빠르게 적응"], "sol": "유도성 유전자는 이화경로에 관여하는 효소를 암호화하며 그 기질이 있을 때만 발현된다(예: 젖당 분해 효소). 억제성 유전자는 동화경로에 관여하는 효소를 암호화하며 최종산물이 충분하면 발현이 중단된다(예: 트립토판 합성 효소). 이처럼 필요한 시기에 필요한 양의 효소만 합성하면 불필요한 단백질 합성에 드는 에너지와 물질을 아낄 수 있고 변화하는 환경에 효율적으로 적응할 수 있어 세균의 생존에 유리하다.", "ref": ["bio6:7", "bio6:6"], "s": "bio", "lv": 0, "ex": null}, {"id": "e01", "u": "궤도 역학", "t": "mc", "lv": 1, "q": "지구 표면 근처에서 원궤도를 유지하기 위한 궤도 속도(제1우주속도)와 지표에서의 탈출 속도를 바르게 짝지은 것은?", "c": ["약 7.9 km/s – 약 11.2 km/s", "약 11.2 km/s – 약 7.9 km/s", "약 3 km/s – 약 7.9 km/s", "약 7.9 km/s – 약 16.7 km/s"], "a": 0, "ex": "$v_0=\\sqrt{GM/R_\\oplus}\\approx7.9$ km/s, $v_{esc}=\\sqrt2 v_0\\approx11.2$ km/s. 참고로 정지위성은 약 3 km/s, 달은 약 1 km/s예요.", "ref": ["e4:1"], "s": "earth", "cx": ["$v_c=\\\\sqrt{GM/R}\\\\approx7.9$ km/s, $v_{esc}=\\\\sqrt2\\\\,v_c\\\\approx11.2$ km/s예요.", "두 값이 서로 바뀌었어요.", "3 km/s는 어떤 값과도 맞지 않아요.", "16.7 km/s는 태양계를 벗어나는 제3우주속도예요."]}, {"id": "e02", "u": "궤도 역학", "t": "mc", "lv": 1, "q": "같은 거리 r에서 탈출 속도 $v_{esc}$와 궤도 속도 $v_c$의 관계는?", "c": ["$v_{esc}=\\sqrt2\\,v_c$", "$v_{esc}=2v_c$", "$v_{esc}=v_c/\\sqrt2$", "$v_{esc}=v_c$"], "a": 0, "ex": "$v_c=\\sqrt{GM/r}$는 구심력 = 만유인력에서, $v_{esc}=\\sqrt{2GM/r}$는 역학적 에너지 = 0에서 나와요.", "ref": ["e4:1"], "s": "earth", "cx": ["$\\\\tfrac12mv^2=GMm/r$ → $v_{esc}=\\\\sqrt{2GM/r}=\\\\sqrt2\\\\,v_c$예요.", "2배가 아니라 $\\sqrt{2}$배예요.", "탈출 속도가 더 커요.", "탈출하려면 원궤도보다 더 빨라야 해요."]}, {"id": "e03", "u": "궤도 역학", "t": "mc", "lv": 1, "q": "지표로부터의 높이 h가 커질수록 원궤도 속도는?", "c": ["느려진다", "빨라진다", "변하지 않는다", "처음에는 빨라지다가 느려진다"], "a": 0, "ex": "$v_c=\\sqrt{\\dfrac{GM}{R+h}}=v_0\\left(1+\\dfrac{h}{R}\\right)^{-1/2}$ 이므로 h가 커지면 작아져요.", "ref": ["e4:1"], "s": "earth", "cx": ["$v_c=\\\\sqrt{GM/(R+h)}$ → r이 커지면 느려져요.", "r이 분모에 있어서 빨라질 수 없어요.", "r에 따라 변해요.", "단조롭게 감소해요."]}, {"id": "e04", "u": "궤도 역학", "t": "mc", "lv": 1, "q": "위치 A에서 접선 방향으로 진입 속도 v가 $v_c<v<\\sqrt2v_c$ 일 때의 궤도는?", "c": ["타원 궤도(A가 근지점)", "타원 궤도(A가 원지점)", "포물선 궤도", "쌍곡선 궤도"], "a": 0, "ex": "$0 < v < v_{c}$ → 타원(A 원지점), $v = v_{c}$ → 원, $v_{c} < v <\\sqrt{2}\\,v_{c}$ → 타원(A 근지점), $v =\\sqrt{2}\\,v_{c}$ → 포물선, $v >\\sqrt{2}\\,v_{c}$ → 쌍곡선이에요.", "ref": ["e4:4", "e4:3"], "s": "earth", "cx": ["원궤도 속도보다 빠르지만 탈출하지 못해 → A가 가장 가까운 점(근지점)인 타원이에요.", "$v<v_{c}$일 때의 경우예요.", "$v=\\sqrt{2}\\,v_{c}$일 때예요.", "$v>\\sqrt{2}\\,v_{c}$일 때예요."]}, {"id": "e05", "u": "궤도 역학", "t": "mc", "lv": 1, "q": "위치 A에서 접선 방향 진입 속도가 $0<v<v_c$ 일 때의 궤도와 A의 위치는?", "c": ["타원 궤도, A는 원지점", "타원 궤도, A는 근지점", "원 궤도", "포물선 궤도"], "a": 0, "ex": "원궤도 속도보다 느리면 안쪽으로 떨어지는 타원이 되므로 A가 가장 먼 점(원지점)이에요.", "ref": ["e4:4"], "s": "earth", "cx": ["느리면 안쪽으로 떨어지므로 A가 가장 먼 점(원지점)인 작은 타원이에요.", "근지점이 되는 것은 $v>v_{c}$일 때예요.", "$v=v_{c}$일 때예요.", "탈출 속도일 때예요."]}, {"id": "e06", "u": "궤도 역학", "t": "mc", "lv": 1, "q": "진입 속도가 정확히 탈출 속도($\\sqrt2v_c$)와 같을 때의 궤도는?", "c": ["포물선", "쌍곡선", "원", "타원"], "a": 0, "ex": "$v_i=v_c\\sqrt{2-r/a}$에서 a → ∞이면 $v_i=\\sqrt2 v_c$가 돼요. 이때 역학적 에너지는 0이고 궤도는 포물선이에요.", "ref": ["e4:3", "e4:4"], "s": "earth", "cx": ["정확히 탈출 속도 → 역학적 에너지 0 → 포물선이에요.", "탈출 속도보다 클 때(E>0)예요.", "$v=v_{c}$일 때예요.", "탈출 속도보다 작을 때(E<0)예요."]}, {"id": "e07", "u": "궤도 역학", "t": "num", "lv": 2, "q": "다누리 2호가 지구 중심에서 r = 10,000 km인 원궤도를 돈다. 궤도 속도는 몇 km/s인가? (G = 6.67×10⁻¹¹ N·m²/kg², M = 6.0×10²⁴ kg)", "a": 6.33, "tol": 0.015, "unit": "km/s", "ex": "$v_c=\\sqrt{\\dfrac{GM}{r}}=\\sqrt{\\dfrac{6.67\\times10^{-11}\\times6.0\\times10^{24}}{10^7}}\\approx6.33$ km/s (자료 ≈ 6.34 km/s).", "ref": ["e4:2"], "s": "earth"}, {"id": "e08", "u": "궤도 역학", "t": "num", "lv": 2, "q": "위 탐사선(r = 10,000 km)이 그 위치에서 지구 중력권을 완전히 벗어나려면 필요한 탈출 속도는 약 몇 km/s인가?", "a": 8.96, "tol": 0.015, "unit": "km/s", "ex": "$v_{esc}=\\sqrt2\\times6.34\\approx8.97$ km/s. 지표의 11.2 km/s보다 작아요.", "ref": ["e4:2"], "s": "earth"}, {"id": "e09", "u": "궤도 역학", "t": "num", "lv": 2, "q": "위 탐사선이 원궤도(6.34 km/s)에서 탈출하려면 속도를 최소 약 몇 km/s 더 가속해야 하는가?", "a": 2.63, "tol": 0.03, "unit": "km/s", "ex": "$\\Delta v=v_{esc}-v_c=8.97-6.34=2.63$ km/s.", "ref": ["e4:2"], "s": "earth"}, {"id": "e10", "u": "궤도 역학", "t": "num", "lv": 3, "q": "탐사선(r = 10,000 km, $v_c$ = 6.34 km/s)이 근지점에서 접선 방향으로 가속하여 원지점 거리가 40,000 km인 타원 궤도로 진입하려 한다. 필요한 진입 속도는 약 몇 km/s인가?", "a": 8.02, "tol": 0.015, "unit": "km/s", "ex": "$a=\\dfrac{10000+40000}{2}=25000$ km, $v_i=v_c\\sqrt{2-\\dfrac{r}{a}}=6.34\\sqrt{1.6}\\approx8.02$ km/s.", "sol": "이 속도는 $v_{esc}$(8.97)보다 작아서 지구에 묶인 타원 궤도예요. 반대로 근지점에서 6.34 km/s로 감속하면 r = 10,000 km 원궤도로 돌아와요.", "ref": ["e4:6", "e4:3"], "s": "earth"}, {"id": "e11", "u": "궤도 역학", "t": "num", "lv": 2, "q": "지표 근처 원궤도 속도가 7.9 km/s일 때, 지표로부터 높이 h = R(지구 반지름)인 곳에서의 원궤도 속도는 약 몇 km/s인가?", "a": 5.59, "tol": 0.02, "unit": "km/s", "ex": "r = 2R → $v_c=7.9/\\sqrt2\\approx5.6$ km/s.", "ref": ["e4:1"], "s": "earth"}, {"id": "e12", "u": "궤도 역학", "t": "mc", "lv": 2, "q": "고도가 높은 곳에서 탈출할 때 필요한 탈출 속도가 지표에서보다 작은 이유로 옳은 것은?", "c": ["중심에서 멀어질수록 중력 퍼텐셜 에너지가 0에 가까워져(덜 음수) 0까지 올리는 데 필요한 운동 에너지가 줄기 때문", "고도가 높으면 지구 질량이 작아지기 때문", "고도가 높으면 원궤도 속도가 커지기 때문", "대기 저항이 없어서"], "a": 0, "ex": "역학적 에너지 = 0이 되도록 하는 속력이므로 $v_{esc}=\\sqrt{2GM/r}$, r이 클수록 작아요.", "ref": ["e4:2"], "s": "earth", "cx": ["$E_p=-GMm/r$가 r이 클수록 0에 가까워 → 필요한 운동 에너지가 작아져요.", "지구 질량은 변하지 않아요.", "고도가 높으면 $v_{c}$는 오히려 작아져요.", "대기 저항은 이론값과 무관해요."]}, {"id": "e13", "u": "성단", "t": "mc", "lv": 1, "q": "산개 성단에 대한 설명으로 옳지 않은 것은?", "c": ["주로 은하 헤일로에 구형으로 분포한다", "수백~수천 개의 별이 허술하게 모여 있다", "대체로 푸른색을 띤다", "금속 함량비가 높은 종족 Ⅰ에 해당한다"], "a": 0, "ex": "산개 성단은 우리은하 원반(나선팔)에 분포해요. 헤일로에 분포하는 것은 구상 성단이에요.", "ref": ["c1:2", "ne:n1"], "s": "earth", "cx": ["헤일로에 구형으로 분포하는 것은 구상 성단이에요 → 옳지 않아 정답이에요.", "옳은 설명이에요.", "옳은 설명이에요(젊은 O·B형 별).", "옳은 설명이에요."]}, {"id": "e14", "u": "성단", "t": "mc", "lv": 1, "q": "구상 성단이 대체로 붉은색을 띠는 이유는?", "c": ["오래되어 질량이 큰 별은 주계열을 벗어났고, 적색 거성과 질량이 작은 주계열성이 대부분이기 때문", "금속 함량이 높기 때문", "성간 소광이 없기 때문", "모두 젊은 별이기 때문"], "a": 0, "ex": "구상 성단은 100억 년 이상 된 늙은 성단(종족 Ⅱ)이에요. 남은 주계열성은 질량이 작고 표면 온도가 낮아요.", "ref": ["c1:3", "ne:n1"], "s": "earth", "cx": ["나이가 많아 무겁고 푸른 별은 이미 진화했고, 붉은 별이 대부분이에요.", "구상 성단은 금속이 적어요(종족 Ⅱ).", "소광은 붉어 보이는 원인이 아니에요.", "구상 성단은 늙은 별로 이루어져 있어요."]}, {"id": "e15", "u": "성단", "t": "mc", "lv": 1, "q": "성단에 대해 옳은 것은?", "c": ["한 성단의 별들은 지구로부터 거리가 비슷하고 공간 운동도 비슷하다", "구상 성단은 우리은하에서 1000개 이상 발견되었다", "산개 성단은 나이가 100억 년 이상이다", "구상 성단은 종족 Ⅰ이다"], "a": 0, "ex": "이 특징을 이용하면 같은 방향의 별 중 어떤 별이 성단에 속하는지 구별할 수 있어요. 산개 성단은 1000개 이상, 구상 성단은 약 200개예요.", "ref": ["c1:2"], "s": "earth", "cx": ["같은 성단의 별은 거리·나이·화학 조성·운동이 비슷해요 → 색등급도 비교가 가능해요.", "우리은하의 구상 성단은 약 150개예요(1000개 이상은 산개 성단).", "100억 년 이상은 구상 성단이에요.", "구상 성단은 종족 Ⅱ예요."]}, {"id": "e16", "u": "성단", "t": "mc", "lv": 1, "q": "UBV 등급계에서 색지수 B−V에 대한 설명으로 옳은 것은?", "c": ["표면 온도가 낮을수록 B−V 값이 커지며, A0형 별의 B−V는 0이다", "표면 온도가 높을수록 B−V 값이 커진다", "B−V = (긴 파장 등급) − (짧은 파장 등급)이다", "B−V는 거리에 따라 달라지는 값이다"], "a": 0, "ex": "고온의 별은 짧은 파장(B)에서 더 밝아 B < V → B−V < 0이에요. 색지수 = 짧은 파장 등급 − 긴 파장 등급이에요.", "ref": ["c1:3", "c1:4"], "s": "earth", "cx": ["차가운 별일수록 B(파랑)가 어두워 B 등급이 커져 → B−V가 커져요. A0형은 0이 기준이에요.", "반대예요. 뜨거울수록 B−V가 작아요(음수).", "B는 짧은 파장, V는 긴 파장이에요. 짧은 − 긴이에요.", "색지수는 거리와 무관해요(소광 제외)."]}, {"id": "e17", "u": "성단", "t": "mc", "lv": 1, "q": "성단의 색등급도에서 '전향점'이 의미하는 것은?", "c": ["남아 있는 주계열성 중 가장 질량이 큰 별의 위치", "가장 어두운 별의 위치", "적색 거성 가지의 끝", "백색 왜성의 위치"], "a": 0, "ex": "질량이 큰 별부터 주계열을 벗어나므로, 전향점의 위치로 성단의 나이를 추정해요.", "ref": ["c1:6"], "s": "earth", "cx": ["아직 주계열에 남은 별 중 가장 무거운 별 → 성단의 나이 지표예요.", "가장 어두운 별과는 관계없어요.", "거성 가지의 끝은 전향점이 아니에요.", "백색 왜성은 왼쪽 아래에 있어요."]}, {"id": "e18", "u": "성단", "t": "mc", "lv": 1, "q": "성단의 나이가 많을수록 색등급도에서 전향점의 위치는?", "c": ["오른쪽 아래(어둡고 붉은 쪽)로 이동", "왼쪽 위로 이동", "변하지 않음", "왼쪽 아래로 이동"], "a": 0, "ex": "시간이 지날수록 더 질량이 작은 별까지 주계열을 떠나므로 전향점이 낮은 광도·낮은 온도 쪽으로 내려가요.", "ref": ["c1:6", "c1:7"], "s": "earth", "cx": ["늙을수록 무거운 별부터 빠져나가 전향점이 어둡고 붉은 쪽으로 내려가요.", "젊어질 때의 방향이에요.", "나이에 따라 변해요.", "전향점은 주계열을 따라 오른쪽 아래로 내려가요."]}, {"id": "e19", "u": "성단", "t": "mc", "lv": 2, "q": "플레이아데스 성단의 전향점이 히아데스 성단의 전향점보다 광도가 큰 곳에 있다. 옳은 해석은?", "c": ["플레이아데스 성단이 히아데스 성단보다 젊다", "플레이아데스 성단이 더 늙었다", "플레이아데스 성단이 더 멀리 있다", "두 성단의 나이는 같다"], "a": 0, "ex": "질량이 큰(밝은) 별이 아직 주계열에 남아 있다는 것은 더 젊다는 뜻이에요.", "ref": ["c1:8", "c1:7"], "s": "earth", "cx": ["전향점이 더 밝다 = 더 무거운 별이 남아 있다 = 더 젊다는 뜻이에요.", "반대예요.", "전향점의 광도(절대 등급) 비교는 거리와 무관해요.", "전향점이 다르니 나이가 달라요."]}, {"id": "e20", "u": "성단", "t": "mc", "lv": 2, "q": "젊은 산개 성단의 색등급도에서 주계열 위쪽과 적색 거성 사이에 별이 거의 없는 구간(헤르츠스프룽 갭)이 생기는 이유는?", "c": ["질량이 큰 별은 중심핵 수소 연소 후 준거성 단계를 매우 빠르게 지나가기 때문", "그 구간의 별은 성간 소광으로 보이지 않기 때문", "그 구간의 별은 모두 초신성이 되었기 때문", "질량이 작은 별만 그 구간을 지나기 때문"], "a": 0, "ex": "태양의 약 2배 이상인 별은 광도가 거의 일정한 채 매우 빠르게 오른쪽으로 이동해요. 질량이 작은 별은 천천히 지나가서 준거성 가지가 뚜렷해요(구상 성단).", "ref": ["c1:8"], "s": "earth", "cx": ["무거운 별은 준거성 단계를 아주 빨리 지나가 그 구간에 머무는 별이 적어요.", "소광은 특정 구간만 골라 가리지 않아요.", "초신성은 마지막 단계예요.", "이 갭은 질량이 큰 별에서 뚜렷해요."]}, {"id": "e21", "u": "성단", "t": "mc", "lv": 1, "q": "젊은 산개 성단에서는 보기 어렵지만 구상 성단의 색등급도에서 나타나는 것은?", "c": ["수평 가지와 점근 거성 가지", "푸른 주계열 상단의 O·B형 별", "헤르츠스프룽 갭", "전향점이 없는 주계열"], "a": 0, "ex": "구상 성단에는 적색 거성 가지, 수평 가지, 점근 거성 가지에 별이 많아 나이가 많은 천체임을 알 수 있어요.", "ref": ["c1:8"], "s": "earth", "cx": ["나이가 많아 저질량 별이 거성 이후 단계(수평 가지, AGB)에 이르렀어요.", "O·B형은 젊은 성단에서 보여요.", "헤르츠스프룽 갭은 젊은 성단의 특징이에요.", "구상 성단에도 전향점이 있어요."]}, {"id": "e22", "u": "성단", "t": "mc", "lv": 1, "q": "주계열 맞추기(main-sequence fitting)에 대한 설명으로 옳지 않은 것은?", "c": ["나이가 많은 구상 성단에 특히 정확하게 적용된다", "성단의 주계열을 표준 주계열에 수직으로 맞춘 등급 차이가 거리 지수이다", "최대 약 10 kpc 거리까지 적용할 수 있다", "주계열이 뚜렷한 어린 성단에 널리 쓰인다"], "a": 0, "ex": "늙은 성단은 주계열 범위가 좁고, 성단 소속 별과 비소속 별을 구별하기 어려워 적용하기 어려워요.", "ref": ["c1:9"], "s": "earth", "cx": ["구상 성단은 금속 함량이 달라 표준 주계열과 어긋나 부정확해요 → 옳지 않아 정답이에요.", "옳은 설명이에요(m−M).", "옳은 설명이에요.", "옳은 설명이에요."]}, {"id": "e23", "u": "성단", "t": "num", "lv": 2, "q": "프레세페 성단의 주계열을 표준 주계열에 맞추었더니 같은 색지수에서 겉보기 등급 m = 10.2, 절대 등급 M = 4.0이었다. 성단까지의 거리는 약 몇 pc인가?", "a": 173.8, "tol": 0.02, "unit": "pc", "ex": "$m-M=5\\log d-5$ → $6.2=5\\log d-5$ → $\\log d=2.24$ → $d\\approx174$ pc.", "ref": ["c1:18", "c1:9"], "s": "earth"}, {"id": "e24", "u": "성단", "t": "num", "lv": 2, "q": "어떤 성단의 주계열 맞추기 결과 m − M = 7.5였다. 거리는 약 몇 pc인가?", "a": 316.0, "tol": 0.02, "unit": "pc", "ex": "$\\log d=\\dfrac{7.5+5}{5}=2.5$ → $d=10^{2.5}\\approx316$ pc.", "ref": ["c1:9"], "s": "earth"}, {"id": "e25", "u": "성단", "t": "num", "lv": 2, "q": "같은 별이 지구에서 거리가 2배로 멀어지면 겉보기 등급은 몇 등급 증가하는가?", "a": 1.505, "tol": 0.02, "unit": "등급", "ex": "$\\Delta m=5\\log2\\approx1.5$ 등급 증가(더 어두워져요).", "ref": ["c1:9"], "s": "earth"}, {"id": "e26", "u": "우리은하", "t": "mc", "lv": 1, "q": "마젤란성운의 세페이드 변광성을 연구하여 주기–광도 관계를 처음 발견한 사람은?", "c": ["레빗", "섀플리", "허블", "커티스"], "a": 0, "ex": "마젤란성운 속 세페이드는 거리가 거의 같아서 겉보기 등급 차이가 곧 절대 등급 차이예요. 광도가 클수록 주기가 길어요.", "ref": ["c2:2"], "s": "earth", "cx": ["레빗이 소마젤란은하의 세페이드로 주기–광도 관계를 발견했어요.", "섀플리는 구상 성단으로 은하 중심을 찾았어요.", "허블은 안드로메다의 거리를 쟀어요(레빗의 관계를 이용).", "커티스는 대논쟁의 상대(외부 은하설)예요."]}, {"id": "e27", "u": "우리은하", "t": "mc", "lv": 1, "q": "세페이드 변광성의 주기–광도 관계로 옳은 것은?", "c": ["광도가 큰(절대 등급이 작은) 세페이드일수록 변광 주기가 길다", "광도가 클수록 주기가 짧다", "주기와 광도는 관계가 없다", "겉보기 등급이 클수록 주기가 길다"], "a": 0, "ex": "주기를 관측하면 절대 등급을 알 수 있고, 겉보기 등급과 비교해 거리를 구해요.", "ref": ["c2:2"], "s": "earth", "cx": ["주기가 길수록 광도가 커요(M이 작아요).", "반대예요.", "뚜렷한 관계가 있어요.", "겉보기 등급은 거리에 따라 달라 관계식에 쓰지 않아요."]}, {"id": "e28", "u": "우리은하", "t": "mc", "lv": 1, "q": "Ⅰ형 세페이드 변광성과 Ⅱ형 세페이드 변광성의 비교로 옳은 것은?", "c": ["같은 주기에서 Ⅰ형이 Ⅱ형보다 약 1.5등급 밝다", "Ⅰ형은 주로 구상 성단에 있다", "Ⅱ형은 종족 Ⅰ이다", "두 형은 같은 주기에서 밝기가 같다"], "a": 0, "ex": "Ⅰ형(고전적 세페이드)은 원반(나선팔)의 종족 Ⅰ, Ⅱ형(W Virginis형)은 구상 성단·헤일로의 종족 Ⅱ예요.", "ref": ["c2:3"], "s": "earth", "cx": ["같은 주기에서 Ⅰ형(종족 Ⅰ)이 약 1.5등급 더 밝아요.", "Ⅰ형은 원반(산개 성단)에 있어요.", "Ⅱ형은 종족 Ⅱ예요.", "약 1.5등급 차이가 있어요."]}, {"id": "e29", "u": "우리은하", "t": "mc", "lv": 1, "q": "거문고자리 RR형 변광성에 대한 설명으로 옳은 것은?", "c": ["주기 약 5~24시간이며 구상 성단에서 주로 발견된다", "주기가 수십 일이다", "주로 은하 원반의 종족 Ⅰ이다", "광도가 태양의 10만 배 이상이다"], "a": 0, "ex": "질량 0.5~0.7 M☉인 종족 Ⅱ 별이 수평 가지(헬륨핵 연소) 단계에서 불안정대를 지날 때 맥동해요.", "ref": ["c2:3"], "s": "earth", "cx": ["RR Lyrae: 주기가 1일 미만이고, 구상 성단에 많고, M ≈ +0.5로 일정해요.", "수십 일은 세페이드예요.", "종족 Ⅱ이고 헤일로에 있어요.", "광도는 태양의 약 50배예요."]}, {"id": "e30", "u": "우리은하", "t": "num", "lv": 2, "q": "섀플리의 예제: 변광 주기 11일인 세페이드 HV 2063의 절대 등급은 −3.3, 평균 겉보기 등급은 14.45이다. 거리는 약 몇 pc인가? (유효숫자 3자리)", "a": 35481.0, "tol": 0.02, "unit": "pc", "ex": "$14.45-(-3.3)=17.75=5\\log d-5$ → $\\log d=4.55$ → $d\\approx3.55\\times10^4$ pc.", "sol": "실제 마젤란은하 거리(50~60 kpc)보다 작아요 → 섀플리의 <b>영점 오차</b> (1952년 바데가 수정).", "ref": ["c2:3"], "s": "earth"}, {"id": "e31", "u": "우리은하", "t": "num", "lv": 2, "q": "구상 성단 M3의 변광성 4개의 거리 지수가 16.3, 16.0, 15.9, 15.7이었다. 평균 거리 지수(≈16.0)로 구한 M3까지의 거리는 약 몇 pc인가?", "a": 15849.0, "tol": 0.03, "unit": "pc", "ex": "$16.0=5\\log d-5$ → $\\log d=4.2$ → $d=10^{4.2}\\approx15{,}850$ pc (약 15.9 kpc).", "ref": ["c2:15"], "s": "earth"}, {"id": "e32", "u": "우리은하", "t": "num", "lv": 3, "q": "Ⅱ형 세페이드를 Ⅰ형으로 잘못 알고 주기–광도 관계를 적용하면 절대 등급을 1.5등급 밝게 잡게 된다. 이렇게 구한 거리는 실제 거리의 약 몇 배가 되는가?", "a": 2.0, "tol": 0.03, "unit": "배", "ex": "M을 1.5 작게(밝게) 잡으면 m−M이 1.5 커져요 → $d$는 $10^{1.5/5}=10^{0.3}\\approx2$배로 과대 추정돼요. 섀플리 영점 오차와 비슷한 원리예요.", "ref": ["c2:3"], "s": "earth"}, {"id": "e33", "u": "우리은하", "t": "mc", "lv": 1, "q": "섀플리가 구상 성단의 공간 분포를 연구하여 얻은 결론은?", "c": ["구상 성단 분포의 중심(은하 중심)은 태양에서 멀리 떨어져 있다", "태양은 우리은하의 중심에 있다", "구상 성단은 은하면에만 분포한다", "안드로메다는 외부 은하이다"], "a": 0, "ex": "구상 성단은 은하면 위아래로 고르게, 특정 방향(궁수자리)에 집중해 분포했어요. 그 중심이 은하 중심이라면 태양은 중심이 아니에요.", "ref": ["c2:7"], "s": "earth", "cx": ["구상 성단 분포의 중심 = 은하 중심이 태양에서 수 kpc 떨어져 있다는 결론이에요.", "그 반대를 보였어요.", "구상 성단은 헤일로에 구형으로 분포해요.", "이건 허블(1924)의 결론이에요."]}, {"id": "e34", "u": "우리은하", "t": "mc", "lv": 1, "q": "섀플리와 커티스의 대논쟁(1920)에서 주된 쟁점은?", "c": ["안드로메다 성운이 우리은하 안의 천체인지, 밖의 외부 은하인지", "태양이 우주의 중심인지", "세페이드 변광성이 존재하는지", "우주가 팽창하는지"], "a": 0, "ex": "섀플리는 안드로메다가 우리은하 내부의 성운이라고, 커티스는 독립된 외부 은하라고 주장했어요.", "ref": ["c2:11"], "s": "earth", "cx": ["나선 성운이 우리은하 안의 천체인지 밖의 은하인지가 쟁점이었어요.", "천동설 논쟁이 아니에요.", "세페이드의 존재는 이미 알려져 있었어요.", "우주 팽창은 1929년 허블 법칙이에요."]}, {"id": "e35", "u": "우리은하", "t": "mc", "lv": 1, "q": "대논쟁을 끝낸 허블의 관측(1924)으로 옳은 것은?", "c": ["안드로메다 성운의 세페이드 변광성으로 거리를 구해, 섀플리가 추정한 우리은하 크기보다 멀다는 것을 보였다", "안드로메다의 적색편이를 측정했다", "구상 성단의 분포를 측정했다", "안드로메다의 연주 시차를 측정했다"], "a": 0, "ex": "거리 약 90만 광년(현재 약 250만 광년) > 섀플리의 우리은하 크기(30만 광년) → 외부 은하로 확정됐어요.", "ref": ["c2:12"], "s": "earth", "cx": ["세페이드로 거리를 재니 우리은하보다 훨씬 멀어서 외부 은하임이 증명됐어요.", "적색편이는 팽창 연구(1929)예요.", "구상 성단 분포는 섀플리의 연구예요.", "너무 멀어서 연주 시차는 측정할 수 없어요."]}, {"id": "e36", "u": "우리은하", "t": "mc", "lv": 1, "q": "현재 알려진 우리은하의 구조로 옳지 않은 것은?", "c": ["태양계는 은하 중심에 위치한다", "막대나선 은하이다", "은하핵에는 태양 질량의 약 400만 배인 블랙홀이 있다", "원반에는 젊은 별과 산개 성단, 헤일로에는 늙은 별과 구상 성단이 많다"], "a": 0, "ex": "태양계는 중심에서 약 8.5 kpc(최근 측정 약 8.2 kpc) 떨어진 원반면 부근에 있어요. 원반 지름은 약 30 kpc예요.", "ref": ["c2:9"], "s": "earth", "cx": ["태양계는 중심에서 약 8 kpc 떨어진 원반에 있어요 → 옳지 않아 정답이에요.", "옳은 설명이에요.", "옳은 설명이에요(궁수자리 A*).", "옳은 설명이에요."]}, {"id": "e37", "u": "우리은하", "t": "mc", "lv": 2, "q": "우리은하 중심부가 막대 모양임을 알아낸 관측으로 옳은 것은?", "c": ["스피처 망원경(중적외선)으로 은하 중심 방향 밝은 별 밀도가 한쪽으로 비대칭임을 보고, 가이아 망원경의 연주 시차 별 지도로 확인했다", "허블이 세페이드 변광성으로 확인했다", "구상 성단의 시지름으로 확인했다", "가시광선 사진으로 직접 막대를 보았다"], "a": 0, "ex": "구형 팽대부라면 별 밀도가 대칭이어야 하는데, 한쪽이 더 컸어요 → 기울어진 막대. 가이아는 별 좌표의 변화(연주 시차)로 3차원 별 지도를 만들었어요.", "ref": ["c2:10", "c2:11"], "s": "earth", "cx": ["적외선(먼지 투과) 별 밀도의 비대칭 + 가이아 시차 지도로 막대 구조를 확인했어요.", "허블은 외부 은하를 연구했어요.", "구상 성단의 시지름은 막대와 관계없어요.", "가시광선은 먼지에 가려져 직접 볼 수 없어요."]}, {"id": "e38", "u": "우리은하", "t": "mc", "lv": 2, "q": "성간 물질에 의해 먼 별빛이 받는 영향으로 옳은 것은? (필기)", "c": ["짧은 파장이 더 많이 산란·흡수되어 별이 실제보다 어둡고(성간 소광) 붉게(성간 적색화) 보인다", "긴 파장이 더 많이 흡수되어 별이 푸르게 보인다", "성간 물질은 별의 밝기에 영향이 없다", "별이 실제보다 밝게 보인다"], "a": 0, "ex": "성간 소광 때문에 별이 어둡게 보여 거리가 과대 추정될 수 있어요. 성간 적색화는 색지수를 크게 만들어요.", "ref": ["ne:n1"], "s": "earth", "cx": ["짧은 파장(파랑)이 더 산란·흡수되어 어둡고 붉게 보여요(소광 + 적색화).", "반대예요.", "영향이 있어요.", "어둡게 보여요."]}, {"id": "eE1", "u": "성단", "t": "essay", "q": "성단의 색등급도를 이용하여 성단의 나이를 비교하는 원리를 '전향점'을 중심으로 서술하시오.", "kp": ["성단의 별들은 거의 같은 시기에 태어남", "질량이 큰 별일수록 수명이 짧아 먼저 주계열을 벗어남", "전향점 = 남아 있는 주계열성 중 가장 무거운 별의 위치", "나이가 많을수록 전향점이 오른쪽 아래(낮은 광도·낮은 온도)", "예: 플레이아데스가 히아데스보다 젊음"], "sol": "한 성단의 별들은 같은 분자 구름에서 거의 같은 시기에 태어났지만, 질량이 큰 별일수록 수명이 짧아 먼저 주계열을 벗어난다. 따라서 색등급도에서 주계열이 꺾여 나가는 전향점은 남아 있는 주계열성 중 가장 무거운 별의 위치를 나타내며, 시간이 지날수록 더 가벼운 별까지 주계열을 떠나므로 전향점은 광도가 작고 표면 온도가 낮은 오른쪽 아래로 이동한다. 즉 전향점이 오른쪽 아래에 있는 성단일수록 나이가 많다. 예를 들어 플레이아데스 성단은 히아데스 성단보다 전향점이 밝은 곳에 있어 더 젊다.", "ref": ["c1:6", "c1:8"], "s": "earth", "lv": 0, "ex": null}, {"id": "eE2", "u": "성단", "t": "essay", "q": "주계열 맞추기로 성단까지의 거리를 구하는 과정을 서술하고, 이 방법이 나이가 많은 성단에 적용하기 어려운 이유를 쓰시오.", "kp": ["성단 별들의 색지수–겉보기 등급(m)으로 색등급도 작성", "표준 주계열(색지수–절대 등급 M)과 비교", "수직 방향으로 이동해 맞춘 등급 차이 = 거리 지수 m − M", "m − M = 5 log d − 5 로 거리 계산", "늙은 성단: 주계열 범위가 좁고, 성단 별/비성단 별 구별이 어려움"], "sol": "성단에 속한 별들의 색지수와 겉보기 등급으로 색등급도를 작성한 뒤, 이를 색지수–절대 등급으로 나타낸 표준 주계열과 비교한다. 성단의 별들은 거리가 같으므로 성단의 주계열은 표준 주계열을 수직 방향으로 평행 이동한 것과 같고, 두 주계열을 겹치게 맞출 때의 등급 차이 m − M이 거리 지수이다. 이를 m − M = 5 log d − 5에 대입해 거리를 구한다. 나이가 많은 성단은 질량이 큰 별이 이미 주계열을 벗어나 주계열의 범위가 좁고, 성단에 속한 별과 속하지 않은 별을 구별하기 어려워 적용하기 어렵다.", "ref": ["c1:9", "c1:18"], "s": "earth", "lv": 0, "ex": null}, {"id": "eE3", "u": "우리은하", "t": "essay", "q": "섀플리가 태양이 우리은하의 중심이 아니라는 결론을 얻은 과정을 서술하시오.", "kp": ["구상 성단 속 세페이드 변광성의 주기 → 주기–광도 관계로 절대 등급", "겉보기 등급과 비교해 구상 성단까지 거리 계산 (+ 시지름 이용)", "관측 방향 + 거리로 구상 성단의 3차원 공간 분포 작성", "구상 성단은 은하면 위아래로 고르게, 특정 방향에 집중", "분포의 중심 = 은하 중심이 태양에서 멀리 떨어짐"], "sol": "섀플리는 구상 성단에서 관측한 세페이드 변광성의 변광 주기를 주기–광도 관계에 적용해 절대 등급을 구하고, 겉보기 등급과 비교해 구상 성단까지의 거리를 구했다(변광성이 없는 성단은 시지름을 이용했다). 관측된 방향과 거리로 구상 성단의 공간 분포를 그려 보니, 구상 성단은 은하면 위아래로 고르게 퍼져 있으면서 특정 방향에 집중되어 있었고 그 분포의 중심은 태양에서 멀리 떨어져 있었다. 구상 성단 분포의 중심을 우리은하의 중심으로 보면, 태양은 은하의 중심에 있지 않다는 결론을 얻는다.", "ref": ["c2:3", "c2:7"], "s": "earth", "lv": 0, "ex": null}, {"id": "eE4", "u": "성단", "t": "essay", "q": "산개 성단과 구상 성단의 색과 금속 함량비가 다른 이유를 형성 시기와 구성 별의 특징으로 설명하시오.", "kp": ["산개: 최근에 같은 분자 구름에서 형성 → 젊음", "산개: 질량·광도가 큰 고온의 주계열성이 남아 있어 푸른색", "산개: 이전 세대 별이 만든 무거운 원소를 포함한 가스 → 금속 함량 높음(종족 Ⅰ)", "구상: 100억 년 이상 전 형성 → 무거운 별은 진화해 사라짐", "구상: 적색 거성·저질량 주계열성 → 붉은색, 초기 우주 가스 → 금속 함량 낮음(종족 Ⅱ)"], "sol": "산개 성단은 은하 원반의 분자 구름에서 비교적 최근에 형성되어 질량과 광도가 큰 고온의 주계열성이 아직 남아 있으므로 푸른색을 띤다. 또한 이전 세대 별들이 만든 무거운 원소가 섞인 가스에서 태어나 금속 함량비가 높은 종족 Ⅰ이다. 반면 구상 성단은 100억 년 이상 전에 금속이 거의 없던 초기 우주의 가스에서 형성되어 금속 함량비가 낮은 종족 Ⅱ이며, 질량이 큰 별은 이미 진화해 주계열을 벗어났고 적색 거성과 질량이 작은 주계열성이 대부분이라 붉은색을 띤다.", "ref": ["c1:2", "c1:3", "ne:n1"], "s": "earth", "lv": 0, "ex": null}, {"id": "eE5", "u": "궤도 역학", "t": "essay", "q": "지표에서의 탈출 속도(11.2 km/s)보다 고도 3600 km에 떠 있는 탐사선의 탈출 속도(약 8.97 km/s)가 작은 이유를 역학적 에너지로 설명하시오.", "kp": ["탈출 조건: 역학적 에너지 KE + PE = 0 (무한히 먼 곳에서 속도 0)", "중력 퍼텐셜 에너지 PE = −GMm/r", "r이 클수록 PE가 0에 가까움(덜 음수)", "0까지 올리는 데 필요한 운동 에너지 감소", "$v_{\\text{esc}} = \\sqrt{2GM/r}$ → r↑ 이면 $v_{\\text{esc}}$↓"], "sol": "탈출하려면 무한히 먼 곳에서 속도가 0이 되도록 역학적 에너지(운동 에너지 + 중력 퍼텐셜 에너지)가 0 이상이어야 한다. 중력 퍼텐셜 에너지는 −GMm/r로, 지구 중심에서 멀어질수록 0에 가까운(덜 음수인) 값을 가진다. 따라서 고도가 높은 곳에서는 역학적 에너지를 0으로 만들기 위해 추가로 필요한 운동 에너지가 더 작고, $v_{\\text{esc}} = \\sqrt{2GM/r}$에서 r이 커질수록 탈출 속도가 작아진다.", "ref": ["e4:2", "e4:1"], "s": "earth", "lv": 0, "ex": null}, {"id": "eE6", "u": "우리은하", "t": "essay", "q": "허블의 안드로메다 관측이 섀플리–커티스 대논쟁을 끝낼 수 있었던 이유를 서술하시오.", "kp": ["대논쟁: 안드로메다가 우리은하 내부 vs 외부 은하", "1924 허블: 윌슨산 2.5 m 망원경으로 안드로메다에서 세페이드 발견", "주기–광도 관계로 거리 ≈ 90만 광년(오늘날 약 250만 광년)", "섀플리가 추정한 우리은하 크기(약 30만 광년)보다 큼", "따라서 안드로메다는 우리은하 밖의 외부 은하"], "sol": "대논쟁의 쟁점은 안드로메다 성운이 우리은하 안의 천체인지 독립된 외부 은하인지였다. 1924년 허블은 윌슨산 천문대 2.5 m 망원경으로 안드로메다 성운에서 세페이드 변광성을 발견하고, 주기–광도 관계를 적용해 거리가 약 90만 광년임을 밝혔다. 이는 섀플리가 생각한 우리은하의 최대 크기(약 30만 광년)보다 훨씬 커서, 안드로메다가 명백히 우리은하 밖의 외부 은하임이 증명되었다.", "ref": ["c2:12", "c2:11"], "s": "earth", "lv": 0, "ex": null}, {"id": "x01", "u": "결정격자 계산", "t": "mc", "lv": 1, "fig": "cell_sc", "q": "그림은 단순입방(SC) 단위세포이다. 단위세포 하나에 실제로 포함된 원자 수는?", "c": ["1개", "2개", "4개", "8개"], "a": 0, "ex": "꼭짓점 원자는 8개 단위세포가 공유하므로 1/8씩 → 8 × 1/8 = 1개예요.", "ref": ["r1:5", "r2:68"], "s": "chem", "cx": ["꼭짓점 8개 × 1/8 = 1개예요.", "2개는 BCC(꼭짓점 1 + 체심 1)예요.", "4개는 FCC예요.", "꼭짓점 원자는 8개 단위세포가 나눠 가져서 통째로 세면 안 돼요."]}, {"id": "x02", "u": "결정격자 계산", "t": "mc", "lv": 1, "fig": "cell_bcc", "q": "그림은 체심입방(BCC) 단위세포이다. 단위세포 속 원자 수와 배위수를 바르게 짝지은 것은?", "c": ["2개, 8", "2개, 6", "1개, 8", "4개, 12"], "a": 0, "ex": "꼭짓점 8 × 1/8 + 체심 1 = 2개. 체심 원자는 꼭짓점 8개와 맞닿아 배위수 8이에요.", "ref": ["r1:5", "r2:68"], "s": "chem", "cx": ["1 + 1 = 2개이고, 체심 원자가 꼭짓점 8개와 닿아 배위수 8이에요.", "배위수 6은 SC예요.", "체심 원자를 빠뜨려 1개로 셌어요.", "FCC의 값이에요."]}, {"id": "x03", "u": "결정격자 계산", "t": "num", "lv": 1, "fig": "cell_fcc", "q": "그림은 면심입방(FCC) 단위세포이다. 단위세포 하나에 포함된 원자 수는?", "a": 4.0, "tol": 0.001, "unit": "개", "ex": "꼭짓점 8 × 1/8 = 1, 면 중심 6 × 1/2 = 3 → 총 4개.", "ref": ["r1:6", "r2:69"], "s": "chem"}, {"id": "x04", "u": "결정격자 계산", "t": "mc", "lv": 2, "fig": "cell_fcc", "q": "그림의 면심입방 구조에서 원자끼리 서로 맞닿는 방향과, 모서리 길이 a와 원자 반지름 r의 관계는?", "c": ["면 대각선 방향, $\\sqrt2\\,a=4r$", "몸 대각선 방향, $\\sqrt3\\,a=4r$", "모서리 방향, $a=2r$", "면 대각선 방향, $\\sqrt3\\,a=4r$"], "a": 0, "ex": "면 중심 원자가 그 면의 네 꼭짓점 원자와 닿으므로 면 대각선($\\sqrt{2}\\,a$)에 반지름이 4개 들어가요.", "ref": ["r1:6", "r2:69"], "s": "chem", "cx": ["면 중심 원자가 꼭짓점 원자와 면 대각선에서 닿아요 →$\\sqrt{2}\\,a = 4r$이에요.", "BCC의 접촉 방향과 관계예요.", "SC의 관계예요.", "방향은 맞지만 면 대각선의 길이는 $\\sqrt{2}\\,a$예요."]}, {"id": "x05", "u": "결정격자 계산", "t": "num", "lv": 2, "fig": "cell_bcc", "q": "그림과 같은 체심입방 구조 금속의 단위세포 모서리 길이가 0.300 nm일 때 원자 반지름은 몇 nm인가?", "a": 0.1299, "tol": 0.01, "unit": "nm", "ex": "$\\sqrt3a=4r$ → $r=\\dfrac{\\sqrt3\\times0.300}{4}=0.130$ nm.", "ref": ["r1:5"], "s": "chem"}, {"id": "x06", "u": "결정격자 계산", "t": "num", "lv": 2, "fig": "cell_sc", "q": "그림의 단순입방 구조의 충전율(쌓임 비율)은 몇 %인가? (소수 첫째 자리)", "a": 52.36, "tol": 0.01, "unit": "%", "ex": "원자 1개, $a=2r$ → $\\dfrac{\\frac43\\pi r^3}{(2r)^3}=\\dfrac{\\pi}{6}=0.524$ → 52.4% (빈 공간 47.6%).", "ref": ["r1:5", "r2:68"], "s": "chem"}, {"id": "x07", "u": "이온 결정", "t": "num", "lv": 2, "fig": "cell_nacl", "q": "그림은 NaCl 단위세포이다. Na⁺는 모서리 중앙 12곳과 체심에 있다. 단위세포 속 Na⁺의 수는?", "a": 4.0, "tol": 0.001, "unit": "개", "ex": "모서리 중앙은 4개 단위세포가 공유 → 12 × 1/4 = 3, 체심 1 → 4개. Cl⁻도 8 × 1/8 + 6 × 1/2 = 4개라 1:1이에요.", "ref": ["r1:18", "r2:76"], "s": "chem"}, {"id": "x08", "u": "이온 결정", "t": "mc", "lv": 1, "fig": "cell_nacl", "q": "그림의 NaCl 결정에서 체심에 있는 Na⁺를 둘러싼 가장 가까운 Cl⁻의 수(배위수)는?", "c": ["6", "4", "8", "12"], "a": 0, "ex": "체심의 Na⁺는 6개 면 중심의 Cl⁻에 둘러싸여요 → 정팔면체 자리, 배위수 6.", "ref": ["r1:18", "r1:16"], "s": "chem", "cx": ["면 중심 6곳의 Cl⁻가 둘러싸는 정팔면체 → 배위수 6이에요.", "배위수 4는 정사면체 자리(ZnS)예요.", "배위수 8은 CsCl이에요.", "12는 금속 최조밀 쌓임의 배위수예요."]}, {"id": "x09", "u": "이온 결정", "t": "num", "lv": 3, "fig": "cell_nacl", "q": "그림의 NaCl 단위세포 모서리 길이가 0.564 nm일 때 NaCl의 밀도는 약 몇 g/cm³인가? (NaCl 58.44 g/mol, $N_A=6.022\\times10^{23}$)", "a": 2.164, "tol": 0.015, "unit": "g/cm³", "ex": "$\\rho=\\dfrac{4\\times58.44}{6.022\\times10^{23}\\times(5.64\\times10^{-8})^3}\\approx2.16$ g/cm³.", "ref": ["r1:18"], "s": "chem"}, {"id": "x10", "u": "이온 결정", "t": "mc", "lv": 1, "fig": "cell_cscl", "q": "그림은 CsCl 단위세포이다. Cs⁺의 배위수와 이 구조에 대한 설명으로 옳은 것은?", "c": ["배위수 8, Cl⁻의 단순입방 격자의 정육면체 자리를 Cs⁺가 차지 (체심입방 구조 아님)", "배위수 6, 정팔면체 자리", "배위수 8, 체심입방 금속 구조와 같다", "배위수 4, 정사면체 자리"], "a": 0, "ex": "꼭짓점과 체심의 입자가 서로 다르므로 BCC가 아니라 \"단순입방 격자 2개가 겹친 구조\"예요. Cs⁺ 1개, Cl⁻ 1개.", "ref": ["r1:17", "r1:18"], "s": "chem", "cx": ["Cl⁻ 정육면체 중심에 Cs⁺ → 배위수 8이고, 서로 다른 입자라 BCC가 아니에요.", "정팔면체 자리는 NaCl이에요.", "배위수는 맞지만, 꼭짓점과 체심이 다른 이온이라 BCC 금속과 달라요.", "정사면체 자리는 ZnS예요."]}, {"id": "x11", "u": "결정격자 계산", "t": "mc", "lv": 2, "fig": "cell_perov", "q": "그림과 같이 A는 꼭짓점, B는 체심, X는 면 중심에 있는 결정의 실험식은?", "c": ["ABX₃", "ABX₆", "A₈BX₆", "AB₂X₃"], "a": 0, "ex": "A: 8 × 1/8 = 1, B: 1, X: 6 × 1/2 = 3 → ABX₃ (페로브스카이트형).", "ref": ["r1:6"], "s": "chem", "cx": ["A 8×1/8=1, B 1, X 6×1/2=3 → ABX₃예요.", "면 중심을 공유하지 않은 것으로 셌어요(6×1/2=3이에요).", "꼭짓점과 면 중심을 통째로 셌어요.", "B는 1개, X는 3개예요."]}, {"id": "x12", "u": "결정격자 계산", "t": "mc", "lv": 2, "fig": "cell_nial", "q": "그림과 같이 Y 원자는 꼭짓점, Z 원자는 면 중심에 있는 합금의 조성은? (Ni–Al 초합금 문제 응용)", "c": ["YZ₃", "Y₃Z", "YZ", "Y₄Z₃"], "a": 0, "ex": "Y: 1, Z: 3 → YZ₃. Al이 꼭짓점, Ni가 면 중심이면 Ni₃Al이에요.", "ref": ["r1:40"], "s": "chem", "cx": ["Y 8×1/8=1, Z 6×1/2=3 → YZ₃예요.", "Y와 Z가 바뀌었어요.", "Z는 3개예요.", "꼭짓점을 1/8로 나누지 않았어요."]}, {"id": "x13", "u": "결정격자 계산", "t": "mc", "lv": 2, "fig": "cell_edge", "q": "그림과 같이 P는 꼭짓점, Q는 모든 모서리의 중앙에 있는 결정의 실험식은?", "c": ["PQ₃", "PQ₁₂", "PQ₆", "P₂Q₃"], "a": 0, "ex": "모서리 중앙은 4개의 단위세포가 공유 → 12 × 1/4 = 3. P = 1 → PQ₃.", "ref": ["r1:16"], "s": "chem", "cx": ["P 1, Q 12×1/4=3 → PQ₃예요.", "모서리 중앙 원자도 공유돼요(1/4).", "모서리는 1/2이 아니라 1/4로 나눠야 해요.", "P는 1개예요."]}, {"id": "x14", "u": "이온 결정", "t": "mc", "lv": 2, "fig": "lattice2d", "q": "그림은 이온성 화합물 MₓAᵧ의 2차원 구조이다. 빨간 사각형을 단위 세포로 할 때 실험식은? (2차원에서 꼭짓점은 4개, 모서리 중앙은 2개의 단위 세포가 공유)", "c": ["MA₃", "MA₂", "MA", "M₂A₃"], "a": 0, "ex": "M: 꼭짓점 4 × 1/4 = 1. A: 모서리 중앙 4 × 1/2 = 2, 가운데 1 → 3. 그래서 MA₃.", "ref": ["r1:41"], "s": "chem", "cx": ["M 4×1/4=1, A 4×1/2 + 1 = 3 → MA₃예요.", "가운데 A 1개를 빠뜨렸어요.", "A를 1개로 셌어요.", "M은 1개예요."]}, {"id": "x15", "u": "반응엔탈피·헤스", "t": "num", "lv": 2, "fig": "hess_co", "q": "그림의 엔탈피 도표에서 $\\mathrm{C(s)+O_2(g)\\to CO_2(g)}$ 의 반응 엔탈피 ΔH₃는 몇 kJ인가?", "a": -393.5, "tol": 0.005, "unit": "kJ", "ex": "헤스 법칙: ΔH₃ = ΔH₁ + ΔH₂ = −110.5 + (−283.0) = −393.5 kJ.", "ref": ["q:21", "nc:n2"], "s": "chem"}, {"id": "x16", "u": "반응엔탈피·헤스", "t": "num", "lv": 2, "fig": "hess_co", "q": "그림을 보고, CO(g) 2 mol이 완전 연소할 때 방출하는 열량은 몇 kJ인지 구하시오. (양수로)", "a": 566.0, "tol": 0.005, "unit": "kJ", "ex": "CO + ½O₂ → CO₂ ΔH = −283.0 kJ이므로 2 mol이면 566 kJ 방출.", "ref": ["q:21"], "s": "chem"}, {"id": "x17", "u": "반응엔탈피·헤스", "t": "num", "lv": 2, "fig": "hess_form", "q": "그림은 C₂H₄(g) + H₂(g)와 C₂H₆(g)의 생성 엔탈피를 나타낸 것이다. $\\mathrm{C_2H_4(g)+H_2(g)\\to C_2H_6(g)}$의 ΔH는 몇 kJ인가?", "a": -137.0, "tol": 0.005, "unit": "kJ", "ex": "ΔH = ΔHf°(C₂H₆) − [ΔHf°(C₂H₄) + ΔHf°(H₂)] = −84.7 − (52.3 + 0) = −137.0 kJ.", "ref": ["q:19"], "s": "chem"}, {"id": "x18", "u": "반응엔탈피·헤스", "t": "mc", "lv": 1, "fig": "hess_form", "q": "그림에 대한 설명으로 옳은 것은?", "c": ["C₂H₄의 생성 반응은 흡열 반응이고, C₂H₆의 생성 반응은 발열 반응이다", "C₂H₄가 C₂H₆보다 엔탈피가 낮다", "H₂(g)의 표준 생성 엔탈피는 +52.3 kJ이다", "C₂H₄ + H₂ → C₂H₆는 흡열 반응이다"], "a": 0, "ex": "원소(기준 0)보다 위에 있는 C₂H₄는 ΔHf > 0(흡열), 아래 있는 C₂H₆는 ΔHf < 0(발열)이에요. H₂는 원소라 0이에요.", "ref": ["q:19"], "s": "chem", "cx": ["원소(0)보다 위인 C₂H₄는 ΔHf>0(흡열), 아래인 C₂H₆는 ΔHf<0(발열)이에요.", "C₂H₄가 더 위(엔탈피가 높음)에 있어요.", "H₂는 원소라 ΔHf°=0이에요.", "위에서 아래로 가는 반응이라 발열이에요."]}, {"id": "x19", "u": "반응엔탈피·헤스", "t": "num", "lv": 2, "fig": "struct_ch4", "q": "그림의 반응에서 평균 결합 엔탈피(kJ/mol)가 C–H 413, O=O 495, C=O 799, O–H 467일 때 반응 엔탈피는 몇 kJ인가?", "a": -824.0, "tol": 0.005, "unit": "kJ", "ex": "끊는 결합: 4(C–H) + 2(O=O) = 1652 + 990 = 2642. 만드는 결합: 2(C=O) + 4(O–H) = 1598 + 1868 = 3466. ΔH = 2642 − 3466 = −824 kJ.", "ref": ["q:22"], "s": "chem"}, {"id": "x20", "u": "반응엔탈피·헤스", "t": "mc", "lv": 1, "fig": "struct_ch4", "q": "그림의 반응에서 결합 엔탈피로 ΔH를 구할 때 끊어지는 결합을 모두 옳게 나타낸 것은?", "c": ["C–H 4개, O=O 2개", "C–H 4개, O=O 1개", "C=O 2개, O–H 4개", "C–H 2개, O=O 2개"], "a": 0, "ex": "반응물 CH₄의 C–H 4개와 O₂ 2분자의 O=O 2개가 끊어지고, 생성물 쪽 C=O 2개와 O–H 4개가 만들어져요.", "ref": ["q:22"], "s": "chem", "cx": ["CH₄의 C–H 4개, 2O₂의 O=O 2개가 끊어져요.", "O₂는 2분자예요(계수 2).", "이건 생성될 때 만들어지는 결합이에요.", "CH₄의 C–H는 4개예요."]}, {"id": "x21", "u": "이상기체 과정", "t": "num", "lv": 2, "fig": "pv_paths", "q": "그림에서 경로 ACB(일정 압력 2 atm에서 팽창 → 일정 부피에서 냉각)를 따라갈 때 계가 받은 일은 몇 L·atm인가?", "a": -40.0, "tol": 0.001, "unit": "L·atm", "ex": "A→C: $w=-P\\Delta V=-2\\times(30-10)=-40$ L·atm, C→B: 부피 일정 w = 0 → 합 −40 L·atm (−4050 J).", "ref": ["q:13"], "s": "chem"}, {"id": "x22", "u": "이상기체 과정", "t": "num", "lv": 2, "fig": "pv_paths", "q": "그림에서 경로 ADB를 따라갈 때 계가 받은 일은 몇 L·atm인가?", "a": -20.0, "tol": 0.001, "unit": "L·atm", "ex": "A→D: 부피 일정 w = 0, D→B: $-1\\times(30-10)=-20$ L·atm. 일은 P–V 그래프 아래 넓이예요.", "ref": ["q:13"], "s": "chem"}, {"id": "x23", "u": "이상기체 과정", "t": "num", "lv": 3, "fig": "pv_paths", "q": "그림의 기체가 단원자 이상기체일 때, 경로 ACB에서 계가 흡수한 열 q는 몇 L·atm인가?", "a": 55.0, "tol": 0.005, "unit": "L·atm", "ex": "ΔU = $\\tfrac32(P_BV_B-P_AV_A)$ = 3/2(30 − 20) = 15 L·atm, q = ΔU − w = 15 − (−40) = 55 L·atm (≈5570 J).", "ref": ["q:13"], "s": "chem"}, {"id": "x24", "u": "이상기체 과정", "t": "mc", "lv": 1, "fig": "pv_paths", "q": "그림의 두 경로 ACB와 ADB를 비교한 것으로 옳은 것은?", "c": ["ΔU는 같지만 w와 q는 다르다", "w는 같고 ΔU는 다르다", "q는 같고 w는 다르다", "ΔU, w, q 모두 같다"], "a": 0, "ex": "ΔU는 상태함수라 처음·나중 상태(A, B)만으로 정해져요. w와 q는 경로함수예요.", "ref": ["q:13", "q:5"], "s": "chem", "cx": ["ΔU는 상태함수라 같고, w와 q는 경로함수라 달라요.", "P–V 아래 넓이가 달라 w는 달라요. ΔU는 같아요.", "ΔU가 같고 w가 다르니 q도 달라요.", "w와 q는 경로마다 달라요."]}, {"id": "x25", "u": "카르노", "t": "mc", "lv": 1, "fig": "pv_carnot", "q": "그림은 카르노 순환 A→B→C→D→A이다. 고온 열원에서 열을 흡수하는 과정은?", "c": ["A → B", "B → C", "C → D", "D → A"], "a": 0, "ex": "A→B는 $T_{h}$에서의 등온 가역 팽창 → ΔU = 0, w < 0이므로 q > 0 (열 흡수). C→D($T_{c}$ 등온 압축)에서는 열을 방출해요.", "ref": ["q:27"], "s": "chem", "cx": ["$T_{h}$에서의 등온 팽창 → ΔU=0, w<0 → q>0(흡열)이에요.", "단열 과정이라 q=0이에요.", "$T_{c}$ 등온 압축 → 열을 방출해요.", "단열 압축이라 q=0이에요."]}, {"id": "x26", "u": "카르노", "t": "mc", "lv": 1, "fig": "pv_carnot", "q": "그림의 카르노 순환에서 열의 출입이 없는(단열) 과정만 모은 것은?", "c": ["B → C, D → A", "A → B, C → D", "A → B, B → C", "C → D, D → A"], "a": 0, "ex": "B→C는 단열 팽창($T_{h}$ → $T_{c}$), D→A는 단열 압축($T_{c}$ → $T_{h}$)이에요.", "ref": ["q:27"], "s": "chem", "cx": ["B→C(단열 팽창), D→A(단열 압축)예요.", "이 둘은 등온 과정이에요(열 출입이 있음).", "A→B는 등온이에요.", "C→D는 등온이에요."]}, {"id": "x27", "u": "카르노", "t": "mc", "lv": 2, "fig": "pv_carnot", "q": "그림의 순환을 한 바퀴 돌았을 때에 대한 설명으로 옳은 것은?", "c": ["ΔU = 0이고, 순환이 둘러싼 넓이가 계가 외부에 한 알짜 일이다", "ΔU > 0이다", "알짜 일은 0이다", "흡수한 열과 방출한 열의 크기가 같다"], "a": 0, "ex": "처음 상태로 돌아오므로 ΔU = 0 → 알짜 $−w = q_{h} + q_{c}$ ($q_{c} < 0$). 흡수한 열의 일부만 일로 바뀌어요.", "ref": ["q:27", "q:30"], "s": "chem", "cx": ["처음 상태로 돌아오니 ΔU=0이고, 폐곡선 넓이가 알짜 일이에요.", "상태함수 변화는 0이에요.", "폐곡선 넓이만큼 일을 해요.", "|$q_{h}$| > |$q_{c}$|이고, 그 차이가 일이에요."]}, {"id": "x28", "u": "깁스 자유에너지", "t": "num", "lv": 2, "fig": "g_vs_t", "q": "그림은 어떤 반응의 ΔG°를 온도에 따라 나타낸 것이다(ΔH°, ΔS°는 일정). 이 반응의 ΔS°는 몇 J/K인가?", "a": 80.0, "tol": 0.02, "unit": "J/K", "ex": "ΔG° = ΔH° − TΔS°. T = 0에서 ΔG° = ΔH° = +40 kJ, T* = 500 K에서 0 → ΔS° = 40/500 = 0.080 kJ/K = 80 J/K. 기울기 = −ΔS°.", "ref": ["q:41"], "s": "chem"}, {"id": "x29", "u": "깁스 자유에너지", "t": "mc", "lv": 2, "fig": "g_vs_t", "q": "그림의 반응에 대한 설명으로 옳은 것은?", "c": ["ΔH° > 0, ΔS° > 0이며 750 K에서 자발적이다", "ΔH° < 0, ΔS° < 0이다", "250 K에서 자발적이다", "모든 온도에서 비자발적이다"], "a": 0, "ex": "y절편(ΔH°) = +40 kJ, 기울기 음수 → ΔS° > 0. T > 500 K에서 ΔG° < 0이라 750 K에서 자발적이에요.", "ref": ["q:41"], "s": "chem", "cx": ["y절편 +40(ΔH>0), 기울기 음(ΔS>0) → T>500 K에서 자발이니 750 K에서 자발이에요.", "부호가 둘 다 반대예요.", "500 K보다 낮으면 ΔG>0이라 비자발이에요.", "500 K보다 높으면 자발이에요."]}, {"id": "x30", "u": "상평형", "t": "mc", "lv": 1, "fig": "phase_water", "q": "그림은 물의 상평형 그림이다. 점 a와 점 b에 해당하는 것을 바르게 짝지은 것은?", "c": ["a: 삼중점, b: 임계점", "a: 임계점, b: 삼중점", "a: 정상 녹는점, b: 정상 끓는점", "a: 삼중점, b: 정상 끓는점"], "a": 0, "ex": "a는 세 곡선이 만나 세 상이 공존하는 삼중점(0.01 ℃, 4.58 torr), b는 액체–기체 곡선이 끝나는 임계점(374 ℃, 218 atm)이에요.", "ref": ["r1:29", "r2:85"], "s": "chem", "cx": ["a는 세 상이 공존하는 삼중점, b는 액–기 곡선이 끝나는 임계점이에요.", "서로 바뀌었어요.", "정상 녹는점·끓는점은 1 atm 선 위의 점이에요.", "b는 곡선의 끝(임계점)이에요."]}, {"id": "x31", "u": "상평형", "t": "mc", "lv": 1, "fig": "phase_water", "q": "그림에서 점 c, d, e의 상태를 바르게 짝지은 것은?", "c": ["c: 고체, d: 기체, e: 액체", "c: 액체, d: 고체, e: 기체", "c: 고체, d: 액체, e: 기체", "c: 기체, d: 기체, e: 액체"], "a": 0, "ex": "고체–액체 경계선 왼쪽은 고체, 액체–기체 곡선 위쪽은 액체, 아래쪽은 기체 영역이에요.", "ref": ["r1:29"], "s": "chem", "cx": ["c는 고체 영역, d는 기체 영역, e는 액체 영역이에요.", "c는 고–액 선 왼쪽이라 고체예요.", "d와 e가 바뀌었어요.", "c는 고체예요."]}, {"id": "x32", "u": "상평형", "t": "mc", "lv": 2, "fig": "phase_water", "q": "그림의 점 c에서 압력을 일정하게 유지하며 가열하면, 상태는 어떻게 변하는가? (점 c의 압력은 삼중점보다 높고 1 atm보다 낮다)", "c": ["고체 → 액체 → 기체", "고체 → 기체(승화)", "고체 → 초임계 유체", "변화 없음"], "a": 0, "ex": "압력이 삼중점보다 높으면 가열할 때 고체–액체 선과 액체–기체 선을 차례로 만나요. 삼중점보다 낮은 압력에서만 승화해요.", "ref": ["r1:30", "r1:31"], "s": "chem", "cx": ["삼중점보다 높은 압력이라 녹은 뒤 끓어요.", "승화는 삼중점보다 낮은 압력에서 일어나요.", "초임계는 임계점 너머예요.", "가열하면 경계선을 지나요."]}, {"id": "x33", "u": "상평형", "t": "mc", "lv": 2, "fig": "phase_water", "q": "그림에서 고체–액체 경계선이 왼쪽으로 기울어 있다(기울기 음). 이로부터 알 수 있는 것은?", "c": ["압력이 높아지면 얼음의 녹는점이 낮아진다", "압력이 높아지면 녹는점이 높아진다", "얼음의 밀도가 물보다 크다", "물은 1 atm에서 승화한다"], "a": 0, "ex": "기울기 음수 = 녹을 때 부피 감소 = 얼음 밀도 < 물 밀도. 그래서 압력이 커지면 녹는점이 낮아져요(스케이트).", "ref": ["r1:32", "r2:88"], "s": "chem", "cx": ["기울기가 음이면 압력을 높일 때 녹는점이 낮아져요(얼음이 더 가벼움).", "반대예요(기울기 양일 때).", "얼음이 물보다 가벼워요.", "1 atm은 물의 삼중점보다 높아 녹아요."]}, {"id": "x34", "u": "상평형", "t": "mc", "lv": 1, "fig": "phase_co2", "q": "그림은 CO₂의 상평형 그림이다. 1 atm에서 고체 CO₂를 가열할 때 일어나는 변화는?", "c": ["고체에서 바로 기체로 승화한다 (−78 ℃)", "고체 → 액체 → 기체", "고체 → 액체에서 멈춘다", "초임계 유체가 된다"], "a": 0, "ex": "1 atm이 삼중점 압력(5.1 atm)보다 낮아서 액체 상을 지나지 않아요.", "ref": ["r1:33", "r2:86"], "s": "chem", "cx": ["1 atm < 삼중점 5.1 atm → −78 ℃에서 승화해요.", "5.1 atm보다 높을 때의 변화예요.", "액체가 되지 않아요.", "임계점(31 ℃, 73 atm)보다 훨씬 낮은 조건이에요."]}, {"id": "x35", "u": "상평형", "t": "mc", "lv": 2, "fig": "phase_co2", "q": "그림의 CO₂와 물의 상평형 그림을 비교한 것으로 옳은 것은?", "c": ["CO₂는 고체–액체 경계선 기울기가 양이라 압력이 높을수록 녹는점이 높다", "CO₂는 고체가 액체보다 밀도가 작다", "CO₂의 삼중점 압력은 1 atm보다 낮다", "CO₂는 임계점이 없다"], "a": 0, "ex": "고체 CO₂가 액체보다 조밀하므로 녹을 때 ΔV > 0 → 기울기 양(+)이에요. 물과 반대예요.", "ref": ["r1:33"], "s": "chem", "cx": ["CO₂는 고체가 더 조밀해 기울기가 양이라 압력이 높을수록 녹는점이 높아요.", "고체가 더 조밀해요(물과 반대).", "5.1 atm으로 1 atm보다 높아요.", "임계점이 있어요(31 ℃)."]}, {"id": "x36", "u": "상평형", "t": "mc", "lv": 1, "fig": "heating", "q": "그림은 1 atm에서 얼음을 일정하게 가열한 가열 곡선이다. 물이 기화하는 구간과 그 구간이 가장 긴 이유는?", "c": ["D – 기화 엔탈피가 융해 엔탈피보다 훨씬 크기 때문", "B – 융해 엔탈피가 가장 크기 때문", "C – 물의 비열이 크기 때문", "E – 수증기의 비열이 크기 때문"], "a": 0, "ex": "구간 B(0 ℃)는 융해, D(100 ℃)는 기화. 상변화 동안 온도는 일정해요. $\\Delta H_{\\text{vap}}$(40.7) ≫ $\\Delta H_{\\text{fus}}$(6.01 kJ/mol)라 D가 길어요.", "ref": ["r2:80", "r2:79"], "s": "chem", "cx": ["D(100 ℃ 평탄 구간)가 기화예요. $\\Delta H_{\\text{vap}}$ ≫ $\\Delta H_{\\text{fus}}$라 가장 길어요.", "B는 융해이고, 융해열은 기화열보다 작아요.", "C는 액체 가열 구간이라 상변화가 아니에요.", "E는 수증기 가열 구간이에요."]}, {"id": "x37", "u": "상평형", "t": "num", "lv": 3, "fig": "heating", "q": "그림에서 0 ℃의 얼음 18 g을 100 ℃의 수증기로 만드는 데(구간 B + C + D) 필요한 열은 약 몇 kJ인가? (ΔH_융해 = 6.01 kJ/mol, 물의 비열 4.184 J/g·℃, ΔH_기화 = 40.7 kJ/mol)", "a": 54.2, "tol": 0.01, "unit": "kJ", "ex": "18 g = 1 mol. B: 6.01 kJ, C: 18 × 4.184 × 100 = 7.53 kJ, D: 40.7 kJ → 합 54.2 kJ.", "ref": ["r2:80"], "s": "chem"}, {"id": "x38", "u": "고체 구조", "t": "num", "lv": 2, "q": "파장 1.54 Å의 X선을 쪼였을 때 면 간격 2.00 Å인 원자면에서 1차 반사가 일어나는 각 θ는 약 몇 도인가?", "a": 22.65, "tol": 0.01, "unit": "°", "ex": "$\\sin\\theta=\\dfrac{n\\lambda}{2d}=\\dfrac{1.54}{4.00}=0.385$ → θ ≈ 22.6°.", "ref": ["r1:2"], "s": "chem"}, {"id": "x39", "u": "이온 결정", "t": "mc", "lv": 2, "q": "Cs⁺(169 pm)와 Cl⁻(181 pm)의 반지름비로 예측한 CsCl의 배위수는?", "c": ["8", "6", "4", "12"], "a": 0, "ex": "169/181 = 0.93 → 0.732 이상 → 정육면체 자리(배위수 8).", "ref": ["r1:17", "r1:18"], "s": "chem", "cx": ["0.93 > 0.732 → 정육면체 자리, 배위수 8이에요.", "0.414~0.732일 때예요.", "0.225~0.414일 때예요.", "이온 결정에서 12는 나오지 않아요."]}, {"id": "x40", "u": "이온 결정", "t": "mc", "lv": 2, "q": "Zn²⁺(74 pm)와 S²⁻(184 pm)의 반지름비로 예측한 ZnS의 배위수와 자리는?", "c": ["4 – 정사면체 자리", "6 – 정팔면체 자리", "8 – 정육면체 자리", "12"], "a": 0, "ex": "74/184 = 0.40 → 0.225 ~ 0.414 → 정사면체 자리(배위수 4). 섬아연석은 사면체 자리의 절반을 채워요.", "ref": ["r1:17", "r2:77"], "s": "chem", "cx": ["0.40 → 0.225~0.414 → 정사면체, 배위수 4예요.", "0.414 이상일 때예요.", "0.732 이상일 때예요.", "나오지 않는 값이에요."]}, {"id": "x41", "u": "이온 결정", "t": "mc", "lv": 2, "q": "형석(CaF₂)에서 Ca²⁺는 면심입방 배열을 하고 F⁻는 정사면체 구멍을 모두 채운다. Ca²⁺의 배위수는?", "c": ["8", "4", "6", "12"], "a": 0, "ex": "단위세포에 Ca²⁺ 4, F⁻ 8 (1:2). F⁻는 Ca²⁺ 4개에 둘러싸여(배위수 4), 비가 1:2이므로 Ca²⁺는 F⁻ 8개에 둘러싸여요.", "ref": ["r1:17"], "s": "chem", "cx": ["Ca:F = 1:2이고 F의 배위수가 4이므로 Ca의 배위수는 4×2 = 8이에요.", "F⁻의 배위수예요.", "팔면체 자리의 배위수예요.", "FCC 금속의 배위수예요."]}, {"id": "x42", "u": "엔트로피·제2법칙", "t": "mc", "lv": 1, "q": "$\\mathrm{CaCO_3(s)\\to CaO(s)+CO_2(g)}$ 의 ΔS의 부호와 그 이유는?", "c": ["양(+) – 고체에서 기체가 생성되므로", "음(−) – 몰수가 줄어서", "0 – 원자 수가 같아서", "음(−) – 흡열 반응이라서"], "a": 0, "ex": "기체 몰수가 0 → 1로 늘어나면 ΔS > 0이에요.", "ref": ["q:35"], "s": "chem", "cx": ["기체가 0 → 1 mol로 늘어나 ΔS>0이에요.", "기체 몰수는 늘어나요.", "원자 수가 아니라 상태(기체 생성)가 중요해요.", "흡열 여부와 ΔS의 부호는 별개예요."]}, {"id": "x43", "u": "엔트로피·제2법칙", "t": "num", "lv": 2, "q": "298 K에서 ΔH = −100 kJ인 반응이 일어날 때 주위의 엔트로피 변화는 몇 J/K인가?", "a": 335.6, "tol": 0.01, "unit": "J/K", "ex": "$\\Delta S_{surr}=-\\Delta H/T=100000/298=+336$ J/K.", "ref": ["q:34"], "s": "chem"}, {"id": "x44", "u": "엔트로피·제2법칙", "t": "num", "lv": 3, "q": "300 K에서 어떤 반응의 ΔS_계 = −50 J/K, ΔH = −20 kJ이다. ΔS_전체는 몇 J/K인가?", "a": 16.67, "tol": 0.02, "unit": "J/K", "ex": "$\\Delta S_{\\text{surr}} = 20000/300$ = +66.7 J/K → $\\Delta S_{\\text{total}}$ = −50 + 66.7 = +16.7 J/K > 0 → 자발적. (ΔG = −20 − 300(−0.05) = −5 kJ로도 확인)", "ref": ["q:34", "q:37"], "s": "chem"}, {"id": "x45", "u": "제1법칙·열용량", "t": "num", "lv": 1, "q": "기체가 500 J의 열을 흡수하면서 외부에 200 J의 일을 했다. 내부에너지 변화 ΔU는 몇 J인가?", "a": 300.0, "tol": 0.001, "unit": "J", "ex": "q = +500 J, 계가 일을 했으므로 w = −200 J → ΔU = 300 J.", "ref": ["q:6"], "s": "chem"}, {"id": "x46", "u": "제1법칙·열용량", "t": "num", "lv": 1, "q": "기체를 압축하면서 계에 300 J의 일을 해 주었더니 계가 주위로 100 J의 열을 방출했다. ΔU는 몇 J인가?", "a": 200.0, "tol": 0.001, "unit": "J", "ex": "w = +300 J, q = −100 J → ΔU = +200 J.", "ref": ["q:6"], "s": "chem"}, {"id": "x47", "u": "제1법칙·열용량", "t": "num", "lv": 2, "q": "기체가 일정한 외부 압력 2.0 atm에 대항해 3.0 L에서 8.0 L로 팽창했다. 계가 받은 일은 몇 J인가? (1 L·atm = 101.3 J)", "a": -1013.0, "tol": 0.01, "unit": "J", "ex": "$w=-P_{ex}\\Delta V=-2.0\\times5.0=-10$ L·atm = −1013 J.", "ref": ["q:5", "q:6"], "s": "chem"}, {"id": "x48", "u": "제1법칙·열용량", "t": "num", "lv": 1, "q": "커피컵 열량계의 물 50.0 g의 온도가 4.00 ℃ 올라갔다. 물이 흡수한 열은 몇 J인가? (물의 비열 4.184 J/g·℃)", "a": 836.8, "tol": 0.01, "unit": "J", "ex": "q = mcΔT = 50.0 × 4.184 × 4.00 = 837 J. 일정 압력이므로 이 열이 반응의 −ΔH와 같아요.", "ref": ["q:7", "nc:n2"], "s": "chem"}, {"id": "x49", "u": "반응엔탈피·헤스", "t": "num", "lv": 2, "q": "A → B (ΔH₁ = +30 kJ), B → C (ΔH₂ = −50 kJ)일 때 C → A 의 ΔH는 몇 kJ인가?", "a": 20.0, "tol": 0.001, "unit": "kJ", "ex": "A → C는 +30 − 50 = −20 kJ. 역반응 C → A는 부호를 바꿔 +20 kJ.", "ref": ["q:21"], "s": "chem"}, {"id": "x50", "u": "깁스 자유에너지", "t": "num", "lv": 2, "q": "벤젠의 $\\Delta H_{\\text{vap}} = 30.8$ kJ/mol, $\\Delta S_{\\text{vap}} = 87.2$ J/K·mol일 때 정상 끓는점은 약 몇 K인가?", "a": 353.2, "tol": 0.01, "unit": "K", "ex": "끓는점에서는 평형이라 ΔG = 0 → T = ΔH/ΔS = 30800/87.2 = 353 K (80 ℃).", "ref": ["q:38", "q:41"], "s": "chem"}, {"id": "x51", "u": "카르노", "t": "num", "lv": 2, "q": "저온 열원이 300 K인 가역 카르노 기관의 효율이 25%가 되려면 고온 열원의 온도는 몇 K여야 하는가?", "a": 400.0, "tol": 0.001, "unit": "K", "ex": "$0.25=1-300/T_h$ → $T_h=400$ K.", "ref": ["q:30"], "s": "chem"}, {"id": "x52", "u": "상평형", "t": "mc", "lv": 2, "q": "CHEMTAK 필기의 과냉각 실험에서, 과냉각된 액체에 충격을 주면 일어나는 현상은?", "c": ["갑자기 결정이 생기며 온도가 어는점까지 다시 올라간다", "온도가 계속 내려가며 기체가 된다", "온도가 변하지 않고 액체로 남는다", "초임계 유체가 된다"], "a": 0, "ex": "어는점 아래 액체(준안정 상태)에 결정핵이 생기면 응고가 급격히 일어나고, 응고열 때문에 온도가 어는점으로 올라가요.", "ref": ["r2:81", "r2:80"], "s": "chem", "cx": ["결정핵이 생기면 급격히 응고하고, 응고열로 온도가 어는점까지 올라가요.", "기화와는 무관해요.", "준안정 상태가 깨져요.", "초임계와 무관해요."]}, {"id": "x53", "u": "고체 구조", "t": "mc", "lv": 1, "q": "CHEMTAK 필기에 정리된 액정에 대한 설명으로 옳지 않은 것은?", "c": ["액정은 결정성 고체이므로 등방성이다", "액체처럼 흐르지만 분자 배열 방향성이 있어 비등방성이다", "네마틱·스멕틱·콜레스테릭 상이 있다", "LCD에 이용된다"], "a": 0, "ex": "액정은 액체지만 분자가 한 방향으로 정렬되어 있어 비등방성을 보여요.", "ref": ["r2:63", "r2:64"], "s": "chem", "cx": ["액정은 액체이고 비등방성이에요 → 옳지 않아 정답이에요.", "옳은 설명이에요.", "옳은 설명이에요.", "옳은 설명이에요."]}, {"id": "x54", "u": "고체 구조", "t": "mc", "lv": 1, "q": "다음 중 등방성(isotropic)이 아닌 것은?", "c": ["석영 결정", "유리", "헬륨 기체", "등축정계 결정"], "a": 0, "ex": "기체, 대부분의 액체, 비결정성 고체, 등축정계 결정은 등방성이에요. 석영(육방정계)은 비등방성이에요.", "ref": ["r2:59", "r2:61"], "s": "chem", "cx": ["석영은 육방정계라 방향에 따라 성질이 달라요 → 비등방성이라 정답이에요.", "유리는 비결정성이라 등방성이에요.", "기체는 등방성이에요.", "등축정계는 등방성이에요."]}, {"id": "x55", "u": "고체 구조", "t": "mc", "lv": 2, "q": "금속 결합의 세기를 비교한 것으로 옳은 것은? (전자바다 모형)", "c": ["Fe가 K보다 결합이 강해 녹는점이 높다 – 양이온 전하가 크고 자유 전자가 많기 때문", "K가 Fe보다 결합이 강하다", "금속 결합은 방향성이 있어 전성이 없다", "양이온 크기가 클수록 결합이 강하다"], "a": 0, "ex": "양이온이 작고 전하(원자가 전자 수)가 클수록 자유 전자와의 정전기적 인력이 커서 결합이 강해요.", "ref": ["r1:8", "r2:73"], "s": "chem", "cx": ["Fe는 양이온 전하가 크고 작으며 자유 전자가 많아 결합이 강해요(녹는점 1538 ℃ vs K 63 ℃).", "반대예요.", "금속 결합은 방향성이 없어 전성·연성이 커요.", "양이온이 작을수록 결합이 강해요."]}, {"id": "y01", "u": "젖당 오페론", "t": "mc", "lv": 1, "fig": "lac_map", "q": "그림은 lac 오페론 주변의 DNA를 나타낸 것이다. (가)는 cAMP–CAP 복합체가 결합하는 부위이다. (가)의 이름과 조절 방식은?", "c": ["CAP 결합부위 – 양성 조절", "주작동부위 – 음성 조절", "프로모터 – RNA 중합효소 결합", "CAP 결합부위 – 음성 조절"], "a": 0, "ex": "cAMP–CAP이 붙으면 RNA 중합효소의 프로모터 결합이 촉진되므로 양성 조절이에요.", "ref": ["nb:n9", "bio6:17"], "s": "bio", "cx": ["(가)는 CAP 결합부위이고, cAMP–CAP이 붙어 전사를 도와요 → 양성 조절이에요.", "작동부위는 억제인자가 붙는 곳이에요.", "프로모터는 RNA 중합효소가 붙는 곳이에요.", "CAP은 활성화(양성) 조절을 해요."]}, {"id": "y02", "u": "젖당 오페론", "t": "mc", "lv": 1, "fig": "lac_map", "q": "그림의 (나)는 lac 억제인자가 가장 강하게 결합하는 부위이다. (나)는?", "c": ["O₁ (주작동부위)", "O₂", "O₃", "CAP 결합부위"], "a": 0, "ex": "O₁은 프로모터와 겹치거나 바로 근처에 있어서, 억제인자가 붙으면 RNA 중합효소의 결합을 막아요.", "ref": ["bio6:19", "nb:n9"], "s": "bio", "cx": ["주작동부위 O₁에 가장 강하게 붙어요.", "보조 작동부위예요(lacZ 안).", "보조 작동부위예요(lacI 쪽).", "cAMP–CAP이 붙는 곳이에요."]}, {"id": "y03", "u": "젖당 오페론", "t": "mc", "lv": 1, "fig": "lac_map", "q": "그림에 나타난 부위 중 lac 오페론(전사 단위)에 포함되지 않는 것은?", "c": ["lacI", "P", "(나)", "lacY"], "a": 0, "ex": "오페론 = 프로모터 + 작동부위 + 구조유전자. lacI는 자신의 프로모터($P_{I}$)로 따로 항상 발현되는 조절유전자예요.", "ref": ["bio6:15"], "s": "bio", "cx": ["lacI는 자체 프로모터를 가진 별도 유전자예요 → 오페론에 포함되지 않아 정답이에요.", "프로모터는 오페론에 포함돼요.", "작동부위는 오페론에 포함돼요.", "구조유전자라 오페론에 포함돼요."]}, {"id": "y04", "u": "젖당 오페론", "t": "mc", "lv": 2, "fig": "lac_map", "q": "그림에서 보조작동부위 O₂가 위치하는 곳은?", "c": ["lacZ 유전자 내부", "lacI 유전자 앞", "lacA 뒤", "CAP 결합부위 안"], "a": 0, "ex": "O₂는 lacZ 안(하류), O₃는 lacI 끝 쪽(상류)에 있어요. 억제인자가 O₁과 O₂/O₃에 함께 붙어 DNA 고리를 만들어요.", "ref": ["bio6:20", "nb:n9"], "s": "bio", "cx": ["O₂는 lacZ 유전자 내부(하류)에 있어요.", "O₃가 lacI 쪽(CAP 결합부위 상류)에 있어요.", "lacA 뒤에는 작동부위가 없어요.", "CAP 결합부위는 별도의 부위예요."]}, {"id": "y05", "u": "트립토판 오페론", "t": "mc", "lv": 1, "fig": "trp_leader", "q": "그림은 trp 리더 mRNA의 영역 1~4를 나타낸 것이다. [Trp]가 높을 때 형성되어 전사를 일찍 끝내는 구조는?", "c": ["3:4 종결자", "2:3 항종결자", "1:2 머리핀만", "1:4 쌍"], "a": 0, "ex": "리보솜이 영역 1을 빠르게 지나 영역 2를 덮으면, 영역 3과 4가 머리핀(3:4)을 만들고 뒤의 U 연속과 함께 rho 비의존 종결이 일어나요.", "ref": ["nb:n10"], "s": "bio", "cx": ["Trp가 많으면 리보솜이 2를 덮어 3:4 종결자가 생겨요.", "Trp가 부족할 때 생기는 구조예요.", "리보솜이 없을 때 1:2가 생기지만, 3:4도 함께 생겨요.", "1:4는 생기지 않아요."]}, {"id": "y06", "u": "트립토판 오페론", "t": "mc", "lv": 1, "fig": "trp_leader", "q": "그림의 리더 mRNA 영역 1에 있는 5′-UGG UGG-3′가 감쇠 조절에서 중요한 이유는?", "c": ["트립토판 코돈이라 Trp-tRNA의 양에 따라 리보솜의 진행 속도가 달라지기 때문", "종결코돈이기 때문", "RNA 중합효소의 결합 부위이기 때문", "억제단백질이 결합하는 서열이기 때문"], "a": 0, "ex": "mRNA 코돈 5′-UGG-3′ = 트립토판. (DNA 비주형(암호·센스) 가닥은 5′-TGG-3′, 주형(비암호·안티센스) 가닥은 3′-ACC-5′) Trp-tRNA^Trp가 부족하면 리보솜이 여기서 멈춰요.", "ref": ["nb:n10"], "s": "bio", "cx": ["Trp 코돈이 연속으로 있어 Trp-tRNA가 부족하면 리보솜이 여기서 멈춰요 → 센서 역할이에요.", "종결코돈은 5′-UGA-3′ 등이에요. 5′-UGG-3′는 Trp 코돈이에요.", "중합효소는 프로모터에 결합해요.", "억제단백질은 DNA의 작동부위에 결합해요."]}, {"id": "y07", "u": "트립토판 오페론", "t": "mc", "lv": 3, "fig": "trp_leader", "q": "그림의 리더 서열에서 영역 2를 결실시킨 돌연변이 대장균에 대한 예측으로 옳은 것은?", "c": ["항종결자(2:3)를 만들 수 없어 [Trp]가 낮아도 3:4 종결자가 생겨 전사가 대부분 일찍 끝난다", "[Trp]와 관계없이 전사가 항상 끝까지 진행된다", "억제단백질이 작동부위에 결합하지 못한다", "감쇠가 [Trp]에 더 민감해진다"], "a": 0, "ex": "영역 2가 없으면 리보솜이 영역 1에서 멈춰도 영역 3을 묶어 둘 수 없어서, 3:4 종결자가 항상 형성돼요.", "ref": ["nb:n10"], "s": "bio", "cx": ["2가 없으면 항종결자를 만들 수 없어 → 3:4 종결자만 생겨 거의 항상 종결돼요.", "오히려 종결이 늘어나요.", "억제단백질 단계와는 별개예요.", "[Trp]를 감지하는 능력이 사라져요."]}, {"id": "y08", "u": "트립토판 오페론", "t": "mc", "lv": 3, "fig": "trp_leader", "q": "그림의 영역 4에 돌연변이가 생겨 영역 3과 상보적으로 결합하지 못하게 되었다. 감쇠 조절의 결과는?", "c": ["종결자(3:4)가 형성되지 않아 [Trp]가 높아도 감쇠에 의한 전사 종결이 일어나지 않는다", "[Trp]와 관계없이 항상 전사가 종결된다", "2:3 항종결자도 형성되지 않는다", "리보솜이 영역 1에서 항상 멈춘다"], "a": 0, "ex": "감쇠는 3:4 머리핀이 있어야 일어나요. 다만 억제단백질에 의한 1단계 억제는 여전히 작동해요.", "ref": ["nb:n10"], "s": "bio", "cx": ["3:4 종결자를 만들 수 없어 감쇠에 의한 종결이 사라져요(항상 끝까지 전사).", "반대예요.", "2와 3은 여전히 짝지을 수 있어요.", "리보솜이 멈추는 것은 [Trp]가 결정해요."]}, {"id": "y09", "u": "젖당 오페론", "t": "mc", "lv": 1, "fig": "diauxic", "q": "그림은 포도당과 젖당이 함께 있는 배지에서 대장균의 생장 곡선이다. 구간 Ⅰ에서 lac 오페론의 전사가 매우 적은 주된 이유는?", "c": ["포도당이 있어 cAMP 농도가 낮고, cAMP–CAP 복합체가 형성되지 않기 때문", "젖당이 없어서 억제인자가 결합해 있기 때문", "lacI가 발현되지 않기 때문", "RNA 중합효소가 없기 때문"], "a": 0, "ex": "박신 표: Ⅰ 구간은 포도당 ○, AC off, cAMP 적음, CAP off. 젖당이 있어 억제는 풀려도 CAP이 없어 전사가 약해요.", "ref": ["nb:n6", "nb:n9"], "s": "bio", "cx": ["포도당이 있으면 cAMP↓ → CAP 활성화가 없어 전사가 적어요(이화물 억제).", "배지에 젖당이 있어요.", "lacI는 구성적으로 발현돼요.", "RNA 중합효소는 있어요."]}, {"id": "y10", "u": "젖당 오페론", "t": "mc", "lv": 2, "fig": "diauxic", "q": "그림의 구간 Ⅲ에서 lac 오페론의 상태로 옳은 것은?", "c": ["억제인자는 알로락토오스와 결합해 떨어져 있고, cAMP–CAP이 결합해 전사가 최대이다", "억제인자가 O₁에 결합해 있다", "cAMP 농도가 낮다", "포도당을 이용해 생장한다"], "a": 0, "ex": "포도당이 고갈되고 젖당만 남은 상태라 음성 조절 해제 + 양성 조절이 함께 일어나요.", "ref": ["nb:n6"], "s": "bio", "cx": ["젖당 → 알로락토오스가 억제인자를 떼어 내고, 포도당이 없어 cAMP–CAP이 결합 → 최대 전사예요.", "억제인자는 떨어져 있어요.", "cAMP가 높아요.", "Ⅲ 구간은 젖당을 이용해요."]}, {"id": "y11", "u": "젖당 오페론", "t": "mc", "lv": 2, "fig": "diauxic", "q": "그림의 구간 Ⅱ에서 생장이 잠시 정체되는 이유는?", "c": ["포도당이 고갈된 뒤 젖당 분해 효소(β-갈락토시다아제 등)를 새로 합성하는 데 시간이 필요하기 때문", "젖당이 독성이 있기 때문", "cAMP가 생장을 억제하기 때문", "억제인자가 과다하게 만들어지기 때문"], "a": 0, "ex": "필기에 쓴 대로 \"젖당 분해 효소 만드는 구간\"이에요.", "ref": ["nb:n6", "nb:n9"], "s": "bio", "cx": ["포도당이 떨어진 뒤 lac 효소를 새로 만들 시간이 필요해서 정체돼요.", "젖당은 독성이 없어요.", "cAMP는 오히려 lac 전사를 도와요.", "억제인자는 유도물질로 떨어져요."]}, {"id": "y12", "u": "젖당 오페론", "t": "mc", "lv": 2, "fig": "binding", "q": "그림은 억제인자 농도에 따른 작동부위 결합률이다. (가)~(다)를 바르게 짝지은 것은?", "c": ["(가) O⁺, (나) Oᶜ, (다) O 결손", "(가) Oᶜ, (나) O⁺, (다) O 결손", "(가) O 결손, (나) Oᶜ, (다) O⁺", "(가) O⁺, (나) O 결손, (다) Oᶜ"], "a": 0, "ex": "정상(O⁺)은 낮은 농도에서도 잘 붙고(Kd 작음), Oᶜ는 높은 농도가 되어야 붙고(Kd 큼), O 결손은 결합 자체가 없어요.", "ref": ["nb:n7", "bio6:19"], "s": "bio", "cx": ["O⁺는 낮은 농도에서 결합, Oᶜ는 높은 농도에서 결합, 결손은 결합 없음이에요.", "O⁺와 Oᶜ가 바뀌었어요.", "순서가 뒤집혔어요.", "Oᶜ와 결손이 바뀌었어요."]}, {"id": "y13", "u": "젖당 오페론", "t": "mc", "lv": 3, "fig": "binding", "q": "그림의 (나)에 해당하는 작동부위를 가진 대장균에서 lacI 유전자를 매우 많이 발현시키면(억제인자 과량) 어떻게 될까?", "c": ["억제인자가 Oᶜ에도 결합하게 되어 구성적 발현이 상당 부분 억제된다", "억제인자는 여전히 전혀 결합하지 못한다", "전사가 오히려 증가한다", "CAP이 결합하지 못한다"], "a": 0, "ex": "심화 3: \"오퍼레이터에 이상이 생기면 낮은 억제자 농도에서는 결합이 안 되고, 높은 억제자 농도에서는 극복된다.\"", "ref": ["nb:n7"], "s": "bio", "cx": ["Oᶜ도 친화력이 낮을 뿐이라 농도가 매우 높으면 결합해 억제돼요.", "결합률이 0이 아니에요.", "억제인자가 늘면 전사는 줄어요.", "CAP과 관계없어요."]}, {"id": "y14", "u": "유전자와 단백질", "t": "mc", "lv": 2, "fig": "growth_table", "q": "표는 어떤 물질의 합성 경로에 관여하는 돌연변이주 Ⅰ~Ⅲ의 생장 결과이다(X, Y, Z는 중간산물 또는 최종산물). 합성 경로의 순서로 옳은 것은?", "c": ["선구물질 → X → Y → Z", "선구물질 → Z → Y → X", "선구물질 → Y → X → Z", "선구물질 → X → Z → Y"], "a": 0, "ex": "Z는 모든 균주를 살리므로 최종산물이에요. 더 많은 돌연변이주를 살리는 물질일수록 경로의 뒤쪽이에요: Z(3개) > Y(2개) > X(1개) → X → Y → Z.", "ref": ["bio5:8", "nb:n1"], "s": "bio", "cx": ["살리는 돌연변이주 수: Z(3) > Y(2) > X(1) → X → Y → Z예요.", "거꾸로예요.", "X가 가장 앞이에요.", "Y와 Z가 바뀌었어요(Z가 최종산물)."]}, {"id": "y15", "u": "유전자와 단백질", "t": "mc", "lv": 2, "fig": "growth_table", "q": "표의 돌연변이주 Ⅱ에 결손된 효소가 촉매하는 단계는?", "c": ["X → Y", "선구물질 → X", "Y → Z", "X → Z"], "a": 0, "ex": "Ⅱ는 X로는 못 자라고 Y부터 자라므로 X → Y 단계가 막혔어요.", "ref": ["bio5:8"], "s": "bio", "cx": ["Ⅱ는 X로는 못 자라고 Y부터 자라요 → X→Y 단계가 막혔어요.", "Ⅲ가 아니라 Ⅰ에 해당하는 단계예요(Ⅰ은 X부터 자람).", "Ⅲ의 결손 단계예요.", "경로에 X→Z 단계는 없어요."]}, {"id": "y16", "u": "젖당 오페론", "t": "mc", "lv": 2, "q": "필기(박신)에 따르면 I⁺ P⁻ O⁺ Z⁺ 대장균의 β-갈락토시다아제 발현 양상은?", "c": ["불능 (젖당이 있어도 없어도 off)", "구성성", "유도성", "포도당이 있을 때만 발현"], "a": 0, "ex": "프로모터(P⁻)가 망가지면 RNA 중합효소가 결합하지 못해 전사 자체가 안 돼요.", "ref": ["nb:n6"], "s": "bio", "cx": ["프로모터 결손(P⁻)이면 중합효소가 붙지 못해 항상 꺼져요 → 불능이에요.", "구성성은 Oᶜ나 I⁻일 때예요.", "프로모터가 없어 유도되지 않아요.", "포도당과 관계없이 꺼져 있어요."]}, {"id": "y17", "u": "젖당 오페론", "t": "mc", "lv": 2, "q": "F′ I⁻ O⁺ Z⁺ / I⁻ O⁺ Z⁺ 의 β-갈락토시다아제 발현 양상은?", "c": ["구성성", "유도성", "불능", "젖당 있을 때만 발현"], "a": 0, "ex": "양쪽 모두 I⁻라 기능하는 억제인자가 전혀 없어요.", "ref": ["nb:n6"], "s": "bio", "cx": ["두 가닥 모두 I⁻ → 기능하는 억제인자가 없어 항상 발현돼요 → 구성성이에요.", "억제인자가 없어 유도 조절이 되지 않아요.", "Z⁺가 있어요.", "억제인자가 없어 젖당이 없어도 발현돼요."]}, {"id": "y18", "u": "젖당 오페론", "t": "mc", "lv": 3, "q": "F′ Iˢ O⁺ Z⁺ / I⁺ O⁺ Z⁺ 의 β-갈락토시다아제 발현 양상은?", "c": ["불능 (젖당이 있어도 발현되지 않음)", "유도성", "구성성", "절반만 유도"], "a": 0, "ex": "Iˢ 억제인자는 알로락토오스와 결합하지 못해 작동부위에서 떨어지지 않고, trans로 양쪽 O⁺에 모두 결합해요 → Iˢ는 우성(super-repressor).", "ref": ["nb:n9"], "s": "bio", "cx": ["Iˢ는 트랜스 우성이라 양쪽 O⁺에 붙어서 떨어지지 않아요 → 불능이에요.", "I⁺가 있어도 Iˢ가 우성이에요.", "억제인자가 있어 구성성이 아니에요.", "Iˢ가 양쪽 모두 막아요."]}, {"id": "y19", "u": "젖당 오페론", "t": "mc", "lv": 3, "q": "F′ I⁺ O⁺ Z⁻ / I⁻ Oᶜ Z⁺ 의 β-갈락토시다아제 발현 양상은?", "c": ["구성성", "유도성", "불능", "젖당이 없을 때만 발현"], "a": 0, "ex": "기능하는 Z⁺는 Oᶜ와 같은 염색체 DNA에 있어요(cis) → 억제인자(I⁺ 유래)가 있어도 결합 못 해 구성성.", "ref": ["nb:n6", "bio6:21"], "s": "bio", "cx": ["Oᶜ–Z⁺가 같은 가닥(시스)이라 I⁺가 있어도 항상 발현돼요 → 구성성이에요.", "Oᶜ 때문에 억제가 안 돼요.", "Z⁺가 있어요.", "젖당이 있든 없든 발현돼요."]}, {"id": "y20", "u": "젖당 오페론", "t": "mc", "lv": 2, "q": "포도당과 젖당이 모두 있을 때 lac 오페론의 상태로 옳은 것은?", "c": ["억제인자는 떨어졌지만 cAMP–CAP이 없어 낮은 수준으로만 전사된다", "억제인자와 CAP이 모두 결합해 전사가 최대이다", "억제인자가 결합해 전사가 전혀 없다", "CAP만 결합해 전사가 최대이다"], "a": 0, "ex": "포도당 ○ → cAMP↓ → CAP off / 젖당 ○ → 억제 해제. 결과는 기저 수준보다 약간 높은 전사예요.", "ref": ["nb:n5", "nb:n9"], "s": "bio", "cx": ["젖당 → 억제인자가 떨어지지만 포도당 때문에 cAMP↓ → 낮은 수준이에요.", "포도당이 있어 CAP이 결합하지 않아요.", "젖당이 억제인자를 떼어 내요.", "포도당이 있어 CAP이 결합하지 않아요."]}, {"id": "y21", "u": "젖당 오페론", "t": "mc", "lv": 2, "q": "포도당과 젖당이 모두 없을 때 lac 오페론의 상태로 옳은 것은?", "c": ["cAMP–CAP은 결합하지만 억제인자가 O₁에 결합해 있어 전사가 거의 일어나지 않는다", "전사가 최대이다", "억제인자가 떨어져 있다", "CAP과 억제인자 모두 결합하지 않는다"], "a": 0, "ex": "포도당 ✗ → cAMP↑ → CAP 결합(양성), 하지만 젖당 ✗ → 억제인자 결합(음성) → 전사 억제.", "ref": ["nb:n5", "nb:n9"], "s": "bio", "cx": ["포도당이 없어 CAP은 결합하지만, 젖당이 없어 억제인자가 막고 있어요.", "억제인자가 붙어 있어 최대가 아니에요.", "유도물질이 없어 억제인자가 붙어 있어요.", "포도당이 없어 CAP은 결합해요."]}, {"id": "y22", "u": "젖당 오페론", "t": "txt", "lv": 1, "q": "ATP로부터 cAMP를 만드는 효소의 이름은? (단답)", "a": ["아데닐산고리화효소", "아데닐산 고리화효소", "아데닐레이트사이클레이스", "adenylatecyclase", "AC", "아데닐산사이클라아제", "아데닐릴고리화효소"], "ex": "포도당이 고갈되면 아데닐산 고리화효소(AC)가 활성화되어 cAMP가 늘어나요.", "ref": ["nb:n9"], "s": "bio"}, {"id": "y23", "u": "중심원리·전사", "t": "txt", "lv": 1, "q": "rho(ρ) 단백질이 결합하는, 새로 합성된 RNA의 C가 풍부한 부위의 이름은? (단답, 영문 3글자)", "a": ["rut", "rut부위", "rutsite"], "ex": "rut = rho utilization site.", "ref": ["bio6:3", "nb:n2"], "s": "bio"}, {"id": "y24", "u": "중심원리·전사", "t": "txt", "lv": 1, "q": "대장균 프로모터의 −35 부위 공통 서열은? (비주형(암호화·센스) DNA 가닥, 5′→3′ 방향으로 염기 6개)", "a": ["TTGACA", "5'-TTGACA-3'", "5′-TTGACA-3′", "5'TTGACA3'"], "ex": "비주형(암호화·센스) DNA 가닥 기준 −35: 5′-TTGACA-3′, −10: 5′-TATAAT-3′(프리브노 상자). 주형(비암호·안티센스) 가닥으로는 −35가 3′-AACTGT-5′예요.", "ref": ["nb:n2"], "s": "bio"}, {"id": "y25", "u": "젖당 오페론", "t": "txt", "lv": 1, "q": "하나의 mRNA에 여러 구조유전자가 함께 전사되어 있는 원핵생물 mRNA의 구조를 무엇이라 하는가? (단답)", "a": ["폴리시스트론", "다시스트론", "polycistronic", "폴리시스트론성", "폴리시스트론mRNA"], "ex": "그래서 하나의 조절부위로 여러 유전자를 한꺼번에 조절할 수 있어요.", "ref": ["bio6:16"], "s": "bio"}, {"id": "y26", "u": "중심원리·전사", "t": "mc", "lv": 1, "q": "원핵생물에서 번역이 시작될 때, mRNA의 SD 서열(5′-AGGAGG-3′)과 상보적으로 결합하는 것은?", "c": ["리보솜 소단위체의 16S rRNA", "tRNA의 안티코돈", "σ 인자", "5′ cap"], "a": 0, "ex": "그 뒤 개시코돈 5′-AUG-3′(mRNA)에 개시 tRNA(fMet)가 결합해요. 진핵생물은 5′ cap을 인식해요.", "ref": ["nb:n3"], "s": "bio", "cx": ["mRNA의 SD 서열 5′-AGGAGG-3′는 16S rRNA의 3′ 끝(3′-UCCUCC-5′)과 상보적으로 결합해 리보솜 위치를 잡아요.", "안티코돈은 코돈과 결합해요.", "σ는 전사(DNA 프로모터)에 쓰여요.", "5′ cap은 진핵생물의 구조예요."]}, {"id": "y27", "u": "중심원리·전사", "t": "mc", "lv": 1, "q": "리보솜에서 펩타이드 결합이 형성된 뒤 아미노산을 내준 tRNA가 빠져나가는 자리는?", "c": ["E 자리", "A 자리", "P 자리", "SD 자리"], "a": 0, "ex": "A 자리는 새 아미노아실-tRNA, P 자리는 폴리펩타이드가 달린 tRNA, E 자리는 출구(Exit)예요.", "ref": ["nb:n3"], "s": "bio", "cx": ["E(Exit) 자리로 빈 tRNA가 나가요.", "A 자리는 새 아미노아실-tRNA가 들어오는 곳이에요.", "P 자리는 펩티딜-tRNA가 있는 곳이에요.", "SD는 mRNA의 서열이지 리보솜의 자리가 아니에요."]}, {"id": "y28", "u": "중심원리·전사", "t": "num", "lv": 1, "q": "64종류의 코돈 중 아미노산을 지정하는 코돈은 몇 종류인가?", "a": 61.0, "tol": 0.001, "unit": "종류", "ex": "종결코돈(mRNA, 5′→3′) UAA, UAG, UGA 3개를 빼면 61개예요. 20종의 아미노산을 여러 코돈이 중복으로 지정해요.", "ref": ["nb:n3"], "s": "bio"}, {"id": "y29", "u": "발현 조절 기초", "t": "mc", "lv": 2, "q": "진핵세포의 전사 개시에 대한 설명으로 옳지 않은 것은?", "c": ["RNA 중합효소 Ⅱ는 단독으로 프로모터를 인식해 결합한다", "보편전사인자(GTF)가 먼저 핵심 프로모터에 결합한다", "인핸서는 프로모터에서 멀리 떨어져 있어도 DNA가 휘어 작용한다", "활성인자가 결합하면 전사 개시 복합체 형성이 촉진된다"], "a": 0, "ex": "진핵 RNA 중합효소는 보편전사인자의 도움을 받아야 핵심 프로모터에 결합할 수 있어요(전사 개시 복합체).", "ref": ["bio6:9", "nb:n4"], "s": "bio", "cx": ["진핵생물의 RNA 중합효소 Ⅱ는 보편전사인자 없이 프로모터를 인식하지 못해요 → 옳지 않아 정답이에요.", "옳은 설명이에요(TFIID–TBP).", "옳은 설명이에요.", "옳은 설명이에요."]}, {"id": "y30", "u": "유전자와 단백질", "t": "mc", "lv": 2, "q": "야생형 붉은빵곰팡이에 X선을 쬔 뒤 바로 최소배지에 포자를 뿌려 키우면 영양요구성 돌연변이주를 얻을 수 없는 이유는?", "c": ["영양요구성 돌연변이주는 최소배지에서 자라지 못하므로, 먼저 완전배지에서 키운 뒤 최소배지에 옮겨 선별해야 하기 때문", "최소배지에서는 X선이 효과가 없기 때문", "최소배지에서는 모든 포자가 죽기 때문", "돌연변이주는 완전배지에서도 자라지 못하기 때문"], "a": 0, "ex": "완전배지 ○ / 최소배지 ✗인 균주가 바로 우리가 찾는 영양요구성 돌연변이주예요.", "ref": ["bio5:6", "bio5:7"], "s": "bio", "cx": ["영양요구성 돌연변이주는 최소배지에서 죽으니, 완전배지에서 먼저 키운 뒤 옮겨 심어 선별해요.", "X선 효과는 배지와 무관해요.", "야생형은 최소배지에서 자라요.", "완전배지에서는 자라요."]}, {"id": "z01", "s": "earth", "u": "성단", "t": "mc", "lv": 2, "fig": "cmd_two", "q": "그림은 두 성단 A, B의 색등급도를 표준 주계열과 함께 나타낸 것이다(점은 전향점). 두 성단을 비교한 것으로 옳은 것은?", "c": ["B가 A보다 나이가 많다", "A가 B보다 나이가 많다", "두 성단의 나이는 같다", "A의 전향점 별이 B의 전향점 별보다 질량이 작다"], "a": 0, "ex": "B의 전향점이 더 어둡고 붉은 쪽(오른쪽 아래)에 있어요 → 더 가벼운 별만 남음 → 더 늙었어요.", "ref": ["c1:6", "c1:8"], "cx": ["B의 전향점이 더 오른쪽 아래(어둡고 붉음)에 있어요 → 더 늙었어요.", "반대예요. A의 전향점이 더 밝아서 A가 더 젊어요.", "전향점 위치가 달라서 나이가 달라요.", "A의 전향점이 더 밝으니 A 쪽 별의 질량이 더 커요."]}, {"id": "z02", "s": "earth", "u": "성단", "t": "mc", "lv": 2, "fig": "cmd_two", "q": "그림의 성단 A에 대한 설명으로 가장 적절한 것은?", "c": ["질량이 크고 푸른 주계열성이 남아 있어 비교적 젊은 산개 성단일 가능성이 크다", "나이가 100억 년 이상인 구상 성단이다", "금속 함량비가 매우 낮은 종족 Ⅱ이다", "주계열성이 모두 사라졌다"], "a": 0, "ex": "전향점이 왼쪽 위(밝고 푸른 쪽)에 있으면 젊은 성단이에요.", "ref": ["c1:8", "c1:2"], "cx": ["전향점이 밝고 푸른 쪽에 있어 젊은 산개 성단의 특징이에요.", "구상 성단은 전향점이 오른쪽 아래(늙음)에 있어요.", "젊은 성단은 금속 함량이 높은 종족 Ⅰ이에요.", "주계열이 아직 길게 남아 있어요."]}, {"id": "z03", "s": "earth", "u": "궤도 역학", "t": "mc", "lv": 1, "fig": "orbit", "q": "그림의 A에서 접선 방향으로 속도 v로 진입할 때, $v_c<v<\\sqrt2v_c$ 이면 어떤 궤도가 되는가?", "c": ["E₂", "E₁", "C", "P"], "a": 0, "ex": "원궤도 속도보다 빠르지만 탈출 속도보다 느리면 A가 근지점인 타원(E₂)이에요.", "ref": ["e4:4", "e4:3"], "cx": ["$v_{c} < v <\\sqrt{2}\\,v_{c}$ → A가 근지점인 타원 E₂예요.", "E₁은 $v < v_{c}$일 때예요.", "C는 $v = v_{c}$일 때예요.", "P는 $v =\\sqrt{2}\\,v_{c}$일 때예요."]}, {"id": "z04", "s": "earth", "u": "궤도 역학", "t": "mc", "lv": 1, "fig": "orbit", "q": "그림에서 A가 원지점인 궤도와, 그 궤도가 되기 위한 진입 속도 조건은?", "c": ["E₁, $0 < v < v_{c}$", "E₂, $v_{c} < v <\\sqrt{2}\\,v_{c}$", "C, $v = v_{c}$", "H, $v >\\sqrt{2}\\,v_{c}$"], "a": 0, "ex": "원궤도 속도보다 느리면 지구 쪽으로 떨어지는 타원이 되어, 출발점 A가 가장 먼 점이 돼요.", "ref": ["e4:4"], "cx": ["원궤도 속도보다 느리면 안쪽으로 떨어지는 타원(E₁)이 되고, A가 원지점이에요.", "E₂에서는 A가 근지점이에요.", "원 궤도는 원지점·근지점이 없어요.", "쌍곡선은 탈출 궤도예요."]}, {"id": "z05", "s": "earth", "u": "궤도 역학", "t": "mc", "lv": 1, "fig": "orbit", "q": "그림에서 지구 중력권을 벗어나는 궤도를 모두 고른 것은?", "c": ["P, H", "E₂, P", "C, E₂, P", "H만"], "a": 0, "ex": "$v =\\sqrt{2}\\,v_{c}$(탈출 속도) → 포물선 P, $v >\\sqrt{2}\\,v_{c}$ → 쌍곡선 H. 둘 다 돌아오지 않아요.", "ref": ["e4:4", "e4:5"], "cx": ["포물선(P)과 쌍곡선(H)은 다시 돌아오지 않는 탈출 궤도예요.", "E₂는 닫힌 타원이에요.", "C와 E₂는 닫힌 궤도예요.", "P도 탈출 궤도예요."]}, {"id": "z06", "s": "earth", "u": "우리은하", "t": "num", "lv": 2, "fig": "pl_graph", "q": "그림은 어떤 세페이드 변광성의 주기–광도 관계이다. 주기가 10일이고 평균 겉보기 등급이 11.5인 세페이드까지의 거리는 몇 pc인가?", "a": 10000.0, "tol": 0.02, "unit": "pc", "ex": "그래프에서 P = 10일 → M = −3.5. $m-M=15=5\\log d-5$ → $\\log d=4$ → $d=10^4$ pc = 10 kpc.", "ref": ["c2:2", "c2:3"]}, {"id": "z07", "s": "earth", "u": "우리은하", "t": "num", "lv": 3, "fig": "pl_graph", "q": "그림의 관계를 이용할 때, 주기 100일, 평균 겉보기 등급 18.5인 세페이드까지의 거리는 약 몇 kpc인가?", "a": 631.0, "tol": 0.02, "unit": "kpc", "ex": "P = 100일 → M = −5.5. m − M = 24 → $\\log d=5.8$ → $d\\approx6.31\\times10^5$ pc ≈ 631 kpc.", "ref": ["c2:2"]}, {"id": "z08", "s": "earth", "u": "우리은하", "t": "mc", "lv": 1, "fig": "pl_graph", "q": "그림에서 알 수 있는 사실로 옳은 것은?", "c": ["변광 주기가 긴 세페이드일수록 광도가 크다", "주기가 길수록 어둡다", "주기와 광도는 관계없다", "절대 등급이 클수록 주기가 길다"], "a": 0, "ex": "주기가 길수록 M이 작아져요(더 밝음).", "ref": ["c2:2"], "cx": ["그래프에서 주기가 길수록 M이 작아져요(밝아져요).", "반대예요.", "뚜렷한 비례 관계가 있어요.", "M이 클수록 어두우니, 주기가 길수록 M은 작아요."]}, {"id": "z09", "s": "earth", "u": "성단", "t": "num", "lv": 2, "fig": "ms_fit", "q": "그림은 어떤 성단의 주계열(m)과 표준 주계열(M)을 같은 색지수에 대해 나타낸 것이다. 이 성단까지의 거리는 몇 pc인가?", "a": 100.0, "tol": 0.02, "unit": "pc", "ex": "같은 색지수에서 두 주계열의 등급 차 m − M = 5 → $\\log d=2$ → $d=100$ pc.", "ref": ["c1:9", "c1:18"]}, {"id": "z10", "s": "earth", "u": "성단", "t": "mc", "lv": 2, "fig": "ms_fit", "q": "그림에서 성단이 지금보다 더 멀리 있었다면 성단 주계열(빨간 점선)은 어떻게 나타났겠는가?", "c": ["더 아래(등급이 큰 쪽)로 이동해 표준 주계열과의 간격이 커진다", "더 위로 이동한다", "왼쪽으로 이동한다", "변하지 않는다"], "a": 0, "ex": "거리가 멀수록 겉보기 등급이 커지므로(어두워짐) m − M이 커져요.", "ref": ["c1:9"], "cx": ["멀수록 겉보기 등급이 커져(어두워져) 아래로 이동하고 m−M이 커져요.", "가까워질 때 위로 이동해요.", "색지수는 거리와 무관해요(성간 적색화는 무시).", "거리에 따라 m이 변해요."]}, {"id": "z11", "s": "earth", "u": "우리은하", "t": "mc", "lv": 1, "fig": "gc_map", "q": "그림은 섀플리가 구한 구상 성단의 공간 분포를 단순화한 것이다(★: 태양). 이로부터 추정한 태양에서 은하 중심까지의 거리는?", "c": ["약 9 kpc", "0 kpc (태양이 중심)", "약 30 kpc", "약 90 kpc"], "a": 0, "ex": "구상 성단이 은하 중심 주위에 대칭으로 분포한다고 보면, 분포 중심(x ≈ 9 kpc)이 은하 중심이에요.", "ref": ["c2:7", "c2:15"], "cx": ["구상 성단 분포의 중심이 x ≈ 9 kpc예요.", "섀플리 이전의 생각이에요. 분포 중심이 태양이 아니에요.", "30 kpc는 은하 원반의 지름 정도예요.", "너무 멀어요."]}, {"id": "z12", "s": "earth", "u": "궤도 역학", "t": "num", "lv": 2, "q": "지표 근처 원궤도 속도를 7.9 km/s라 할 때, 지표로부터 높이가 지구 반지름의 3배(h = 3R)인 곳의 원궤도 속도는 몇 km/s인가?", "a": 3.95, "tol": 0.01, "unit": "km/s", "ex": "r = 4R → $v=7.9/\\sqrt4=3.95$ km/s.", "ref": ["e4:1"]}, {"id": "z13", "s": "earth", "u": "궤도 역학", "t": "num", "lv": 2, "q": "지표에서의 탈출 속도가 11.2 km/s일 때, 지구 중심에서 4R인 곳에서의 탈출 속도는 몇 km/s인가?", "a": 5.6, "tol": 0.01, "unit": "km/s", "ex": "$v_{esc}\\propto1/\\sqrt r$ → 11.2/2 = 5.6 km/s.", "ref": ["e4:1", "e4:2"]}, {"id": "z14", "s": "earth", "u": "궤도 역학", "t": "num", "lv": 1, "q": "근지점 거리 10,000 km, 원지점 거리 40,000 km(모두 지구 중심 기준)인 타원 궤도의 긴반지름 a는 몇 km인가?", "a": 25000.0, "tol": 0.001, "unit": "km", "ex": "a = (10,000 + 40,000)/2 = 25,000 km.", "ref": ["e4:6"]}, {"id": "z15", "s": "earth", "u": "성단", "t": "num", "lv": 1, "q": "겉보기 등급 15, 절대 등급 0인 별까지의 거리는 몇 pc인가?", "a": 10000.0, "tol": 0.01, "unit": "pc", "ex": "$15=5\\log d-5$ → $\\log d=4$ → 10,000 pc.", "ref": ["c1:9"]}, {"id": "z16", "s": "earth", "u": "성단", "t": "num", "lv": 1, "q": "거리 지수(m − M)가 10인 성단까지의 거리는 몇 pc인가?", "a": 1000.0, "tol": 0.01, "unit": "pc", "ex": "$\\log d=(10+5)/5=3$ → 1000 pc.", "ref": ["c1:9"]}, {"id": "z17", "s": "earth", "u": "성단", "t": "mc", "lv": 1, "q": "B−V가 −0.1인 별 갑과 +1.2인 별 을에 대한 설명으로 옳은 것은?", "c": ["갑이 을보다 표면 온도가 높다", "을이 갑보다 표면 온도가 높다", "갑은 붉은색이다", "두 별의 표면 온도는 같다"], "a": 0, "ex": "B−V가 작을수록(음수일수록) 짧은 파장 쪽이 밝은 고온의 푸른 별이에요.", "ref": ["c1:3", "c1:4"], "cx": ["B−V가 작을수록(음수일수록) 고온의 푸른 별이에요.", "을(+1.2)은 저온의 붉은 별이에요.", "갑은 푸른색이에요.", "색지수가 다르니 표면 온도도 달라요."]}, {"id": "z18", "s": "earth", "u": "우리은하", "t": "num", "lv": 2, "q": "구상 성단 M3의 변광성 4개의 거리 지수가 16.3, 16.0, 15.9, 15.7일 때 평균 거리 지수는? (소수 둘째 자리)", "a": 15.975, "tol": 0.003, "unit": "", "ex": "(16.3 + 16.0 + 15.9 + 15.7)/4 = 15.975 ≈ 16.0.", "ref": ["c2:15"]}, {"id": "z19", "s": "earth", "u": "우리은하", "t": "mc", "lv": 3, "q": "성간 소광을 고려하지 않고 겉보기 등급만으로 세페이드 변광성까지의 거리를 구하면, 실제 거리와 비교해 어떻게 되는가?", "c": ["실제보다 멀게 구해진다", "실제보다 가깝게 구해진다", "같다", "거리를 구할 수 없다"], "a": 0, "ex": "소광 때문에 실제보다 어둡게(m이 크게) 보여서 m − M이 커지므로 거리가 과대 추정돼요.", "ref": ["ne:n1"], "cx": ["소광으로 더 어둡게(m 크게) 보여 m−M이 커지니 거리가 과대 추정돼요.", "반대예요.", "소광이 있으면 달라져요.", "구할 수는 있지만 오차가 생겨요."]}, {"id": "z20", "s": "earth", "u": "우리은하", "t": "mc", "lv": 2, "q": "구상 성단에서 발견되는 세페이드 변광성에 Ⅰ형의 주기–광도 관계를 적용하면 안 되는 이유는?", "c": ["구상 성단의 세페이드는 종족 Ⅱ인 Ⅱ형으로, 같은 주기에서 Ⅰ형보다 약 1.5등급 어둡기 때문", "구상 성단에는 세페이드가 없기 때문", "Ⅱ형이 Ⅰ형보다 밝기 때문", "구상 성단은 너무 가까워서"], "a": 0, "ex": "주기–광도 관계의 종류를 혼동한 것이 초기 거리 측정 오차(영점 오차)의 원인 중 하나였어요.", "ref": ["c2:3"], "cx": ["구상 성단은 Ⅱ형(종족 Ⅱ)이라 같은 주기에서 Ⅰ형보다 1.5등급 어두워요.", "구상 성단에도 세페이드(Ⅱ형)와 RR Lyrae가 있어요.", "Ⅱ형이 더 어두워요.", "가까워서가 아니라 종류가 다르기 때문이에요."]}, {"id": "z21", "s": "earth", "u": "우리은하", "t": "mc", "lv": 1, "q": "우리은하 각 구성 요소와 주로 분포하는 천체를 바르게 짝지은 것은?", "c": ["원반 – 젊은 별·산개 성단·성간 물질, 헤일로 – 늙은 별·구상 성단", "원반 – 구상 성단, 헤일로 – 산개 성단", "팽대부 – 산개 성단만", "헤일로 – 성간 물질이 가장 많음"], "a": 0, "ex": "성간 물질이 원반에 집중되어 있어서 원반과 나선팔에서 별이 만들어져요.", "ref": ["c2:9"], "cx": ["원반은 젊은 별·산개 성단·성간 물질, 헤일로는 늙은 별·구상 성단이에요.", "원반과 헤일로가 서로 바뀌었어요.", "팽대부는 늙은 별이 밀집한 곳이고, 산개 성단은 원반에 있어요.", "성간 물질은 원반에 집중되어 있어요."]}, {"id": "z22", "s": "earth", "u": "궤도 역학", "t": "num", "lv": 1, "q": "같은 위치에서 탈출 속도는 원궤도 속도의 몇 배인가? (소수 둘째 자리)", "a": 1.414, "tol": 0.005, "unit": "배", "ex": "$\\sqrt2\\approx1.41$배.", "ref": ["e4:1"]}, {"id": "w01", "s": "phys", "u": "다이오드 특성", "t": "num", "lv": 1, "fig": "circ_f", "q": "그림의 회로에서 다이오드를 이상적 다이오드로 볼 때 회로에 흐르는 전류는 몇 mA인가?", "a": 5.0, "tol": 0.001, "unit": "mA", "ex": "순방향 이상 다이오드는 단락 → $I=5/1000=5$ mA.", "ref": ["s2:14"]}, {"id": "w02", "s": "phys", "u": "다이오드 특성", "t": "num", "lv": 2, "fig": "circ_f", "q": "그림의 회로를 고정 전압 모델($V_{\\gamma} = 0.7$ V)로 해석할 때 저항 양단의 전압은 몇 V인가?", "a": 4.3, "tol": 0.005, "unit": "V", "ex": "5 − 0.7 = 4.3 V (전류 4.3 mA).", "ref": ["s1:2"]}, {"id": "w03", "s": "phys", "u": "다이오드 특성", "t": "mc", "lv": 1, "fig": "circ_r", "q": "그림의 회로(다이오드가 역방향)에서 저항에 흐르는 전류와 다이오드 양단 전압은? (이상적 다이오드)", "c": ["0 A, 5 V", "5 mA, 0 V", "4.3 mA, 0.7 V", "0 A, 0 V"], "a": 0, "ex": "역방향이라 개방(i = 0) → 저항 전압 0 → 전원 전압 5 V가 모두 다이오드에 걸려요.", "ref": ["s2:14"], "cx": ["역방향 → 개방 → 전류 0 → 전원 전압 5 V가 모두 다이오드에 걸려요.", "이상 다이오드가 순방향일 때의 값이에요.", "고정 전압 모델 순방향일 때의 값이에요.", "전류는 0이지만 다이오드에는 5 V가 걸려요."]}, {"id": "w04", "s": "phys", "u": "다이오드 특성", "t": "num", "lv": 2, "fig": "circ_2f", "q": "그림의 회로를 고정 전압 모델(각 다이오드 0.7 V)로 해석할 때 저항 양단 전압은 몇 V인가?", "a": 3.6, "tol": 0.005, "unit": "V", "ex": "5 − 0.7 − 0.7 = 3.6 V (전류 3.6 mA).", "ref": ["s1:2"]}, {"id": "w05", "s": "phys", "u": "다이오드 특성", "t": "mc", "lv": 2, "fig": "circ_fr", "q": "그림의 회로에서 D₁은 순방향, D₂는 역방향이다. 이에 대한 설명으로 옳은 것은? (이상적 다이오드)", "c": ["D₂가 개방되어 전류가 흐르지 않고, D₂ 양단에 5 V가 걸린다", "D₁이 개방되어 D₁에 5 V가 걸린다", "전류 5 mA가 흐른다", "두 다이오드에 각각 2.5 V씩 걸린다"], "a": 0, "ex": "직렬 회로에서 하나라도 역방향이면 전류가 0이에요. 전류가 없으니 R과 D₁의 전압은 0이고 D₂에 전원 전압이 다 걸려요.", "ref": ["s2:14"], "cx": ["D₂가 역방향이라 개방 → 전류 0 → D₂에 5 V가 걸려요.", "D₁은 순방향이라 개방이 아니에요.", "직렬 중 하나라도 개방이면 전류가 0이에요.", "전류가 0이므로 전압은 개방된 D₂에만 걸려요."]}, {"id": "w06", "s": "phys", "u": "다이오드 특성", "t": "num", "lv": 3, "fig": "circ_ex", "q": "그림의 회로를 구간 선형 모델($V_{\\gamma} = 0.7$ V, $R_{f} = 20$ Ω)로 해석할 때, 500 Ω 저항에서 소비되는 전력은 약 몇 mW인가?", "a": 34.2, "tol": 0.02, "unit": "mW", "ex": "$i=4.3/520=8.27$ mA → $P=i^2R=(8.27\\times10^{-3})^2\\times500=34.2$ mW.", "ref": ["s1:3"]}, {"id": "w07", "s": "phys", "u": "정류·평활", "t": "mc", "lv": 2, "fig": "bridge", "q": "그림의 브리지 정류회로에서 a가 b보다 전위가 높은 반주기에 켜지는(순방향) 다이오드는?", "c": ["D₁, D₄", "D₂, D₃", "D₁, D₂", "D₃, D₄"], "a": 0, "ex": "a → D₁ → 출력 X → 부하 → 출력 Y → D₄ → b. 다이오드 화살표(삼각형) 방향으로만 전류가 흘러요.", "ref": ["s2:17"], "cx": ["a → D₁ → X → 부하 → Y → D₄ → b예요.", "b가 높을 때 켜지는 쌍이에요.", "D₂는 b에서 나가는 경로에 있어요.", "D₃는 b가 높을 때 a로 돌아오는 경로예요."]}, {"id": "w08", "s": "phys", "u": "정류·평활", "t": "mc", "lv": 2, "fig": "bridge", "q": "그림의 브리지 정류회로에서 b가 a보다 전위가 높은 반주기에 켜지는 다이오드는?", "c": ["D₂, D₃", "D₁, D₄", "D₂, D₄", "D₁, D₃"], "a": 0, "ex": "b → D₂ → X → 부하 → Y → D₃ → a.", "ref": ["s2:17"], "cx": ["b → D₂ → X → 부하 → Y → D₃ → a예요.", "a가 높을 때 켜지는 쌍이에요.", "D₄는 Y에서 b로 가는 다이오드라 b가 높을 때는 역방향이에요.", "D₁은 a에서 나가는 다이오드예요."]}, {"id": "w09", "s": "phys", "u": "정류·평활", "t": "mc", "lv": 2, "fig": "bridge", "q": "그림의 회로에서 부하에 흐르는 전류의 방향은?", "c": ["두 반주기 모두 X → 부하 → Y 방향이다", "두 반주기 모두 Y → X 방향이다", "반주기마다 방향이 바뀐다", "전류가 흐르지 않는다"], "a": 0, "ex": "어느 반주기든 전류가 출력 단자 X로 들어가 부하를 지나 Y로 나와요. 그래서 X가 항상 (+) 단자예요.", "ref": ["s2:16", "s2:17"], "cx": ["어느 반주기든 X로 들어가 부하를 지나 Y로 나가요 → X가 항상 (+)예요.", "방향이 반대예요.", "방향이 바뀌지 않는 게 정류예요.", "항상 한 쌍이 켜져 전류가 흘러요."]}, {"id": "w10", "s": "phys", "u": "정류·평활", "t": "mc", "lv": 3, "fig": "bridge", "q": "그림의 회로에서 D₄가 끊어져(개방) 동작하지 않는다면 부하의 출력은 어떻게 되는가?", "c": ["b가 높은 반주기에만 전류가 흘러 반파 정류처럼 된다", "a가 높은 반주기에만 전류가 흐른다", "출력이 전혀 없다", "전파 정류가 그대로 유지된다"], "a": 0, "ex": "D₄는 a가 높은 반주기의 경로(D₁ → 부하 → D₄)에 있어요. 이 경로가 끊기고 D₂–D₃ 경로만 남아요.", "ref": ["s2:17"], "cx": ["D₄가 끊기면 a가 높을 때의 경로가 막히고 b 쪽 경로(D₂, D₃)만 남아요.", "a가 높을 때는 D₄가 필요해서 막혀요.", "다른 쌍은 정상이라 출력이 있어요.", "한쪽 경로가 없어져 반파가 돼요."]}, {"id": "w11", "s": "phys", "u": "정류·평활", "t": "mc", "lv": 1, "fig": "waves", "q": "그림의 (가)~(다)는 사인파 교류를 넣었을 때 세 회로의 출력이다. 반파 정류, 브리지 정류, 브리지 정류 + 평활 축전기의 출력을 순서대로 고른 것은?", "c": ["(가), (나), (다)", "(나), (가), (다)", "(다), (나), (가)", "(가), (다), (나)"], "a": 0, "ex": "반파는 (+) 반주기만(가), 브리지는 모든 반주기가 (+)(나), 축전기가 있으면 굴곡(리플)만 남은 직류에 가까운 파형(다)이에요.", "ref": ["s2:15", "s2:17", "s2:19"], "cx": ["반파(가), 브리지(나), 브리지+축전기(다) 순서예요.", "(가)와 (나)가 바뀌었어요.", "순서가 뒤집혔어요.", "(나)와 (다)가 바뀌었어요."]}, {"id": "w12", "s": "phys", "u": "정류·평활", "t": "mc", "lv": 2, "fig": "waves", "q": "그림에서 입력 교류의 진동수가 f일 때 (나)와 (다)의 리플 진동수는?", "c": ["2f", "f", "f/2", "4f"], "a": 0, "ex": "전파 정류는 한 주기에 봉우리가 2개라 2f예요. (가)는 f예요.", "ref": ["s2:19"], "cx": ["전파 정류는 한 주기에 봉우리가 2개 → 2f예요.", "f는 반파 정류 (가)의 리플이에요.", "진동수가 줄지 않아요.", "4배가 되지는 않아요."]}, {"id": "w13", "s": "phys", "u": "정류·평활", "t": "num", "lv": 2, "fig": "ripple", "q": "그림은 평활회로의 출력 전압이다. 리플 비율 $r_{\\text{pp}}$는 몇 %인가?", "a": 8.0, "tol": 0.01, "unit": "%", "ex": "$V_{ripple}=7.8-7.2=0.6$ V, $r_{pp}=0.6/7.5\\times100=8$%.", "ref": ["s2:19"]}, {"id": "w14", "s": "phys", "u": "정류·평활", "t": "mc", "lv": 2, "fig": "ripple", "q": "그림의 리플을 더 작게 만드는 방법으로 옳은 것은?", "c": ["평활 축전기의 전기 용량(또는 부하 저항)을 더 크게 한다", "축전기를 떼어 낸다", "다이오드를 하나 뺀다", "입력 진동수를 낮춘다"], "a": 0, "ex": "시간 상수 RC가 클수록 방전이 느려져 전압이 덜 떨어져요. 진동수를 높여도 리플이 줄어요.", "ref": ["s2:19", "s2:20"], "cx": ["RC가 클수록 방전이 느려 전압이 덜 떨어져요.", "축전기를 빼면 리플이 커져요.", "다이오드를 빼면 반파가 되어 리플이 더 커져요.", "진동수를 낮추면 방전 시간이 길어져 리플이 커져요."]}, {"id": "w15", "s": "phys", "u": "에너지 띠", "t": "mc", "lv": 1, "fig": "bands", "q": "그림 (가)~(다)는 고체의 에너지 띠 구조이다. 반도체, 도체, 절연체를 순서대로 고른 것은?", "c": ["(가), (나), (다)", "(나), (가), (다)", "(다), (가), (나)", "(가), (다), (나)"], "a": 0, "ex": "띠 간격이 작으면 반도체(가), 띠가 겹치면 도체(나), 띠 간격이 크면 절연체(다)예요.", "ref": ["s2:4"], "cx": ["작은 간격(가) = 반도체, 겹침(나) = 도체, 큰 간격(다) = 절연체예요.", "(가)와 (나)가 바뀌었어요.", "(다)는 간격이 가장 커서 절연체예요.", "(나)와 (다)가 바뀌었어요."]}, {"id": "w16", "s": "phys", "u": "다이오드 특성", "t": "mc", "lv": 1, "fig": "iv3", "q": "그림 (가)~(다)는 다이오드 근사 모델의 전류–전압 특성이다. 이상적 모델, 고정 전압 모델, 구간 선형 모델을 순서대로 고른 것은?", "c": ["(나), (가), (다)", "(가), (나), (다)", "(다), (가), (나)", "(나), (다), (가)"], "a": 0, "ex": "이상적: 0 V에서 수직(나), 고정 전압: $V_{\\gamma}$에서 수직(가), 구간 선형: $V_{\\gamma}$부터 기울기 $1/R_{f}$로 증가(다).", "ref": ["s1:2"], "cx": ["이상적: 0 V에서 수직(나), 고정 전압: $V_{\\gamma}$에서 수직(가), 구간 선형: 기울기가 있음(다).", "(가)와 (나)가 바뀌었어요.", "(다)는 기울기가 있어 구간 선형이에요.", "(가)와 (다)가 바뀌었어요."]}, {"id": "w17", "s": "phys", "u": "도핑", "t": "mc", "lv": 1, "fig": "dope_n", "q": "그림은 Si 결정에 원소 X를 도핑한 모습이다(결합에 참여하지 않는 전자가 남음). X와 반도체의 종류는?", "c": ["인(P) 같은 15족 원소, N형", "붕소(B) 같은 13족 원소, P형", "저마늄(Ge), 진성 반도체", "인(P), P형"], "a": 0, "ex": "원자가 전자가 5개라 4개는 결합에 쓰이고 1개가 남아 운반자가 돼요.", "ref": ["s2:6"], "cx": ["남는 전자가 있으니 15족(5개) → N형이에요.", "13족이면 전자가 남지 않고 빈 자리(양공)가 생겨요.", "Ge는 14족이라 전자가 남지 않아요.", "P(인)를 넣으면 N형이에요."]}, {"id": "w18", "s": "phys", "u": "도핑", "t": "mc", "lv": 1, "fig": "dope_p", "q": "그림은 Si 결정에 원소 X를 도핑한 모습이다(결합 전자 하나가 빈 자리가 있음). 이 반도체의 주된 전하 운반자는?", "c": ["양공 – X는 13족(B 등), P형", "전자 – X는 15족, N형", "양공 – X는 15족, N형", "이온 – X는 18족"], "a": 0, "ex": "원자가 전자가 3개라 결합에 전자 하나가 부족한 양공이 생겨요.", "ref": ["s2:5"], "cx": ["빈 자리 = 양공 → 13족(B 등) → P형이에요.", "15족이면 전자가 남아요.", "양공이 생기는 건 13족이에요.", "18족은 결합하지 않아요."]}, {"id": "w19", "s": "phys", "u": "다이오드 특성", "t": "num", "lv": 2, "q": "300 K에서 열전압 $V_t=kT/e$는 약 몇 mV인가? ($k=1.38\\times10^{-23}$ J/K, $e=1.60\\times10^{-19}$ C)", "a": 25.9, "tol": 0.02, "unit": "mV", "ex": "$V_t=\\dfrac{1.38\\times10^{-23}\\times300}{1.60\\times10^{-19}}=0.0259$ V ≈ 25.9 mV (상온 약 25 mV).", "ref": ["s2:13"]}, {"id": "w20", "s": "phys", "u": "다이오드 특성", "t": "num", "lv": 3, "q": "이상인자 η = 1, $V_t$ = 25 mV인 다이오드에 순방향 전압을 50 mV 높이면 전류는 약 몇 배가 되는가? (충분히 켜져 있음)", "a": 7.39, "tol": 0.02, "unit": "배", "ex": "$e^{50/25}=e^2\\approx7.39$배.", "ref": ["s2:13"]}, {"id": "w21", "s": "phys", "u": "계측기", "t": "num", "lv": 1, "q": "오실로스코프의 수직 감도가 2 V/div일 때, 사인파의 최고점과 최저점 사이가 4칸이었다. 이 신호의 $V_{pp}$는 몇 V인가?", "a": 8.0, "tol": 0.001, "unit": "V", "ex": "4 div × 2 V/div = 8 V (진폭 4 V).", "ref": ["s2:25"]}, {"id": "w22", "s": "phys", "u": "계측기", "t": "num", "lv": 1, "q": "오실로스코프의 수평(시간) 감도가 0.2 s/div일 때 한 주기가 5칸이었다. 신호의 진동수는 몇 Hz인가?", "a": 1.0, "tol": 0.001, "unit": "Hz", "ex": "T = 5 × 0.2 = 1.0 s → f = 1/T = 1 Hz.", "ref": ["s2:25"]}, {"id": "w23", "s": "phys", "u": "PN접합", "t": "mc", "lv": 2, "q": "PN 접합의 공핍층 안의 전기장 방향으로 옳은 것은?", "c": ["N쪽(양이온)에서 P쪽(음이온)을 향한다", "P쪽에서 N쪽을 향한다", "전기장이 없다", "접합면과 나란한 방향이다"], "a": 0, "ex": "공핍층에는 N쪽에 양이온(주개), P쪽에 음이온(받개)이 남아 전기장이 N → P 방향이에요. 이 전기장이 전자와 양공의 추가 확산을 막아요.", "ref": ["s2:10"], "cx": ["N쪽 양이온 → P쪽 음이온 방향, 즉 (+) → (−)예요.", "방향이 반대예요.", "이온이 남아 있어 전기장이 있어요.", "접합면에 수직인 방향이에요."]}, {"id": "w24", "s": "phys", "u": "PN접합", "t": "mc", "lv": 1, "q": "다이오드 기호에서 삼각형(화살표) 쪽 단자와 막대 쪽 단자를 바르게 짝지은 것은?", "c": ["삼각형 쪽: 애노드(P형), 막대 쪽: 캐소드(N형)", "삼각형 쪽: 캐소드(N형), 막대 쪽: 애노드(P형)", "둘 다 P형", "둘 다 N형"], "a": 0, "ex": "전류는 삼각형이 가리키는 방향(애노드 → 캐소드)으로만 흘러요. 1N4007 실물에서는 은색 띠가 캐소드예요.", "ref": ["s2:9"], "cx": ["삼각형 쪽이 애노드(P), 막대 쪽이 캐소드(N)예요. 전류는 삼각형 방향으로 흘러요.", "두 단자가 바뀌었어요.", "한쪽은 N형이에요.", "한쪽은 P형이에요."]}, {"id": "w25", "s": "phys", "u": "에너지 띠", "t": "mc", "lv": 2, "q": "원자 1개의 전자 에너지가 $E_n=-E_0/n^2$인 이유와 관련된 설명으로 옳은 것은?", "c": ["전자가 핵의 쿨롱 퍼텐셜 우물에 갇혀 있어 에너지가 양자화되기 때문", "전자가 자유롭게 움직이기 때문", "에너지가 연속적이기 때문", "원자가 많이 모여 있기 때문"], "a": 0, "ex": "$U(r)=\\dfrac{1}{4\\pi\\varepsilon_0}\\dfrac{qQ}{r}$의 퍼텐셜 우물에 갇힌 전자는 불연속 준위를 가져요. 원자가 모이면 준위가 띠가 돼요.", "ref": ["s2:2", "s2:3"], "cx": ["쿨롱 퍼텐셜 우물에 갇힌 전자는 에너지가 불연속(양자화)돼요.", "자유 전자라면 에너지가 연속적이에요.", "연속이 아니라 불연속이에요.", "원자 1개에 대한 이야기예요. 여러 원자가 모이면 띠가 돼요."]}];
const KB=[{"id": "k_b1", "s": "bio", "t": "1유전자 1효소설 (비들·테이텀)", "kw": ["비들", "테이텀", "붉은빵곰팡이", "1유전자1효소", "1유전자 1효소설", "최소배지", "완전배지", "영양요구성", "오르니틴", "시트룰린", "아르지닌", "돌연변이주", "X선", "반수체"], "b": "<ul><li>붉은빵곰팡이(핵상 <b>n</b> → 돌연변이가 바로 표현형) 포자에 <b>X선</b> → 돌연변이 유발</li>\n<li>완전배지 ○ / 최소배지 ✗ 인 <b>영양요구성 돌연변이주</b> 선별</li>\n<li>최소배지 = 포도당 + 무기염류 + 비오틴(Vit B8). 처음 합성되는 비필수아미노산 = <b>글루탐산</b></li>\n<li>선구물질 →(a)→ 오르니틴 →(b)→ 시트룰린 →(c)→ 아르지닌</li>\n<li>Ⅰ형: 오르니틴부터 ○ (a 결손) / Ⅱ형: 시트룰린부터 ○ (b 결손) / Ⅲ형: 아르지닌만 ○ (c 결손)</li>\n<li><b>규칙</b>: 결손 효소의 <u>바로 다음 산물</u>부터 넣으면 자람. 최종산물은 모든 돌연변이를 살림</li>\n<li>가정: X선으로 <b>하나의 변이만</b> 생긴다 (여러 개면 해석이 꼬임)</li></ul>\n", "ref": ["bio5:6", "bio5:8", "nb:n1"]}, {"id": "k_b2", "s": "bio", "t": "유전자 개념의 변화", "kw": ["개로드", "알캅톤뇨증", "1유전자1단백질", "1유전자1폴리펩타이드", "1유전자1기능성분자", "헤모글로빈", "miRNA", "중심원리", "가설", "변화"], "b": "<ol><li><b>개로드</b>: 알캅톤뇨증 → 대사 장애 = 특정 효소 결핍, 열성 유전</li>\n<li><b>1유전자 1효소설</b> (비들·테이텀, 붉은빵곰팡이)</li>\n<li><b>1유전자 1단백질설</b>: 효소 아닌 단백질(케라틴, 인슐린)도 유전자가 암호화</li>\n<li><b>1유전자 1폴리펩타이드설</b>: 헤모글로빈 = α₂β₂, α·β는 다른 유전자</li>\n<li><b>1유전자 1기능성분자설</b>(현대): miRNA, rRNA, tRNA 발견 → 산물이 폴리펩타이드만은 아님</li></ol>\n시기별 헤모글로빈: 배아 ζ₂ε₂ → 태아 α₂γ₂ → 성인 α₂β₂ (태아형이 산소 친화력↑)\n", "ref": ["bio5:2", "bio5:11", "bio5:12", "nb:n1"]}, {"id": "k_b3", "s": "bio", "t": "원핵 RNA 중합효소와 프로모터", "kw": ["RNA중합효소", "시그마", "σ", "핵심효소", "완전효소", "보조인자", "프로모터", "프리브노", "TATAAT", "TTGACA", "-10", "-35", "전사개시"], "b": "<ul><li>완전효소 = 핵심효소(α₂ββ′ω) + <b>σ(보조인자)</b></li>\n<li>σ가 프로모터 인식: <b>−35: 5′-TTGACA-3′</b>, <b>−10: 5′-TATAAT-3′(프리브노 상자)</b> — 비주형(암호화·센스) DNA 가닥 기준</li>\n<li>개시 후 σ는 떨어져 재사용, 핵심효소가 신장</li>\n<li>RNA 중합효소는 주형(안티센스, −)가닥을 3′→5′로 읽고 RNA를 <b>5′→3′</b>로 합성, 프라이머 불필요</li></ul>\n", "ref": ["nb:n2", "nb:n3"]}, {"id": "k_b4", "s": "bio", "t": "원핵 전사 종결 (rho 의존/비의존)", "kw": ["rho", "로", "ρ", "전사종결", "종결", "rut", "헬리케이스", "머리핀", "GC", "역반복", "U", "비의존", "의존"], "b": "<b>① rho 의존</b>: ρ가 새 RNA의 <b>rut 부위</b>(C 풍부)에 결합 → <b>ATP</b> 쓰며 RNA를 타고 이동 → 멈춘 중합효소에서 <b>헬리케이스</b> 활성으로 RNA–DNA 분리<br>\n<b>② rho 비의존</b>: 단백질 없이 DNA 서열만으로 종결. <b>GC 풍부 역반복서열</b> → RNA 머리핀 → 중합효소 정지 + 뒤의 <b>U 연속</b>(A–U 약함) → RNA 이탈\n", "ref": ["bio6:3", "bio6:4", "nb:n4"]}, {"id": "k_b5", "s": "bio", "t": "RNA 2·3차구조, 리보자임, 폴리솜", "kw": ["머리핀", "2차구조", "3차구조", "리보자임", "폴리솜", "폴리리보솜", "5cap", "polyA", "eIF4E", "eIF4G", "번역효율"], "b": "<ul><li>단일가닥 핵산에 자기상보적 서열 → <b>머리핀(2차구조)</b></li>\n<li>RNA는 복잡한 3차구조 → 단백질처럼 촉매 = <b>리보자임</b></li>\n<li>진핵 폴리솜: 5′ cap–eIF4E–eIF4G–PABP–poly(A) 연결 → mRNA 고리 → <b>번역 효율↑</b></li></ul>\n", "ref": ["bio6:2", "bio6:5"]}, {"id": "k_b6", "s": "bio", "t": "번역과 tRNA·리보솜 (1학기 복습)", "kw": ["번역", "tRNA", "리보솜", "코돈", "안티코돈", "개시코돈", "AUG", "종결코돈", "UAA", "UAG", "UGA", "A자리", "P자리", "E자리", "SD", "16S"], "b": "<ul><li>코돈 = 연속된 염기 3개 → 4³ = 64종 (아미노산 20)</li>\n<li>코돈은 mRNA 기준 5′→3′: 개시코돈 5′-AUG-3′(메싸이오닌), 종결코돈 5′-UAA-3′·5′-UAG-3′·5′-UGA-3′</li>\n<li>tRNA: 3′ 말단 5′-…CCA-3′에 아미노산 결합, 안티코돈이 코돈과 상보결합</li>\n<li>리보솜 A자리(새 aa-tRNA), P자리(폴리펩타이드 tRNA), E자리(출구)</li>\n<li>원핵: mRNA의 SD 서열에 16S rRNA가 결합해 개시</li></ul>\n", "ref": ["nb:n3"]}, {"id": "k_b7", "s": "bio", "t": "구성성·유도성·억제성 유전자", "kw": ["구성성", "유도성", "억제성", "하우스키핑", "이화", "동화", "유도물질", "억제물질", "유전자종류"], "b": "<table class=\"t\"><tr><th>종류</th><th>특징</th><th>예</th></tr>\n<tr><td>구성성</td><td>지속적으로 발현 (하우스키핑)</td><td>tRNA, rRNA, RNA pol</td></tr>\n<tr><td>유도성</td><td><b>이화</b>경로, 기질이 있을 때만 발현</td><td>젖당 분해 효소</td></tr>\n<tr><td>억제성</td><td><b>동화</b>경로, 최종산물이 있으면 발현 중단</td><td>트립토판 합성 효소</td></tr></table>\n", "ref": ["bio6:7"]}, {"id": "k_b8", "s": "bio", "t": "진핵 조절 영역 (프로모터·인핸서·사일런서)", "kw": ["프로모터", "핵심프로모터", "조절프로모터", "TATA", "인핸서", "사일런서", "활성인자", "억제인자", "전사인자", "진핵", "GTF"], "b": "<ul><li>유전자 = 구조 유전자 + 조절 영역</li>\n<li>프로모터 = 핵심 프로모터(TFIIB −35, <b>TATA(5′-TATAAA-3′, 비주형(암호화·센스) DNA 가닥) −25</b>, Inr +1, DPE +30) + 조절 프로모터(GC, CAAT, OCT 박스)</li>\n<li>RNA 중합효소 + 보편전사인자(GTF)가 핵심 프로모터에 결합</li>\n<li><b>인핸서</b>: 전사 효율↑, 전사 활성화 인자(activator) 결합</li>\n<li><b>사일런서</b>: 전사 억제, 전사 억제 인자(repressor) 결합 — DNA가 휘어 멀리서도 작용</li></ul>\n", "ref": ["bio6:8", "bio6:9", "bio6:10"]}, {"id": "k_b9", "s": "bio", "t": "전사 개시 조절 4가지 (양성/음성 × 유도/억제)", "kw": ["양성조절", "음성조절", "유도성", "억제성", "활성인자", "억제인자", "activator", "repressor", "보조억제물질", "4가지"], "b": "<table class=\"t\"><tr><th></th><th>유도성 (기질 신호)</th><th>억제성 (산물 신호)</th></tr>\n<tr><td><b>음성</b> (억제인자)</td><td>기질이 억제인자 <b>비활성화</b> → ON (lac)</td><td>산물이 억제인자 <b>활성화</b> → OFF (trp)</td></tr>\n<tr><td><b>양성</b> (활성인자)</td><td>기질이 활성인자 <b>활성화</b> → ON</td><td>산물이 활성인자 <b>비활성화</b> → OFF</td></tr></table>\n", "ref": ["bio6:11", "bio6:12", "bio6:13"]}, {"id": "k_b10", "s": "bio", "t": "오페론과 원핵 조절의 특징", "kw": ["오페론", "작동부위", "작동유전자", "오퍼레이터", "operator", "조절유전자", "구조유전자", "폴리시스트론", "원핵조절"], "b": "<ul><li>오페론 = <b>프로모터 + 작동부위 + 구조유전자</b> (조절유전자는 <u>포함 ✗</u>)</li>\n<li>조절유전자: 항상 발현 → 억제단백질 → 작동부위에 결합 → RNA pol 결합 방해</li>\n<li>원핵 특징: ① 전사속도 = 프로모터에 대한 RNA pol 친화력 ② <b>폴리시스트론</b> ③ 한 조절부위에 한 종류 단백질 ④ 조절부위는 구조유전자 바로 앞</li></ul>\n", "ref": ["bio6:14", "bio6:15", "bio6:16"]}, {"id": "k_b11", "s": "bio", "t": "젖당(lac) 오페론 구조와 작동", "kw": ["젖당", "락토스", "lac", "젖당오페론", "lacZ", "lacY", "lacA", "lacI", "β-갈락토시다아제", "갈락토시다아제", "투과효소", "아세틸기", "알로락토오스", "IPTG", "유도체"], "b": "<ul><li>구조: P<sub>I</sub>–lacI–O₃ … CAP 결합부위–P–<b>O₁</b>–lacZ(O₂ 포함)–lacY–lacA</li>\n<li>lacZ: β-갈락토시다아제 / lacY: 투과효소 / lacA: 아세틸기 전이효소</li>\n<li>젖당(β1-4) 유입 → β-갈락토시다아제가 일부를 <b>알로락토오스(β1-6)</b>로 → 억제인자에 결합 → O₁에서 떨어짐 → 전사</li>\n<li><b>IPTG</b>: 유도하지만 분해되지 않는 인공 유도물질</li>\n<li>심화 2: on/off가 아니라 <b>more/less</b> — 기저 수준으로 소량 발현</li></ul>\n", "ref": ["bio6:17", "bio6:18", "nb:n5", "nb:n7"]}, {"id": "k_b12", "s": "bio", "t": "CAP–cAMP와 포도당 효과 (이중생장)", "kw": ["CAP", "cAMP", "아데닐산고리화효소", "AC", "포도당", "이화물억제", "이중생장", "생장곡선", "PTS", "양성조절", "정체기"], "b": "<ul><li>포도당↓ → AC 활성 → <b>cAMP↑</b> → cAMP–CAP이 CAP 결합부위에 → DNA 휨 → RNA pol 결합 촉진 (양성)</li>\n<li>포도당↑ → PTS(포도당 수송)로 AC 활성 억제 → cAMP↓ → CAP 불활성</li>\n<li>이중생장: Ⅰ(포도당 ○, AC off, cAMP 적음) → Ⅱ(정체: 포도당 ✗, cAMP 많음, 젖당 분해 효소 합성 중) → Ⅲ(젖당 이용)</li>\n<li>포도당 ○·젖당 ○: 억제는 풀렸지만 CAP이 없어 약하게만 전사 / 포도당 ✗·젖당 ○: 최대 전사</li></ul>\n", "ref": ["nb:n9", "nb:n6", "nb:n5"]}, {"id": "k_b13", "s": "bio", "t": "작동부위 O₁·O₂·O₃, Oᶜ, cis/trans", "kw": ["O1", "O2", "O3", "주작동부위", "보조작동부위", "Oc", "구성적", "cis", "trans", "고리", "억제배수", "Kd"], "b": "<ul><li><b>O₁</b>: 주작동부위(가장 강하게 결합) / <b>O₂·O₃</b>: 보조 — O₁과 함께 결합하면 <b>DNA 고리</b> → 억제 크게↑</li>\n<li>억제 배수: O₁ 단독 ≈18배, O₁+O₂ ≈700배, O₁+O₃ ≈440배, O₁+O₂+O₃ ≈1300배</li>\n<li><b>Oᶜ</b>: 억제인자 친화력↓ → 구성적 발현 (낮은 농도에서 결합 ✗, 높은 농도에서는 극복). O 결손은 결합 자체 ✗</li>\n<li>작동부위 = <b>cis</b> (같은 DNA만 조절), 억제단백질 = <b>trans</b> (확산되어 다른 DNA에도)</li></ul>\n", "ref": ["bio6:19", "bio6:20", "bio6:21", "nb:n7"]}, {"id": "k_b14", "s": "bio", "t": "유도성/구성성/불능 판정법", "kw": ["유도성", "구성성", "불능", "판정", "부분이배체", "F′", "Iˢ", "Id", "I-", "I+", "우성", "열성", "유전자형"], "b": "<b>순서</b>: ① 기능하는 Z⁺가 어느 DNA에 있나? ② 그 DNA의 O가 Oᶜ면 → <b>구성성</b> ③ O⁺면 세포 안 억제단백질로 판단<br>\n<ul><li>I⁻ (억제인자 없음) → 구성성, 열성</li>\n<li>Iˢ (알로락토오스 결합 ✗) → <b>불능</b>, 우성 (Iˢ > I⁻)</li>\n<li>Iᵈ (작동부위 결합 ✗) → 구성성 (필기: Iᵈ > I⁻)</li>\n<li>예) F′ I⁻O⁺Z⁺ / I⁺O⁺Z⁺ → 유도성, F′ I⁺OᶜZ⁻ / I⁺O⁺Z⁺ → 유도성 (함정!)</li></ul>\n", "ref": ["nb:n6", "nb:n9", "bio6:21"]}, {"id": "k_b15", "s": "bio", "t": "트립토판(trp) 오페론과 감쇠", "kw": ["트립토판", "trp", "trpR", "trpL", "리더", "감쇠", "attenuation", "감쇠자", "종결자", "항종결자", "123", "184", "62", "UGG", "억제성"], "b": "<ul><li>구조: trpR(멀리) … P–O–trpL(리더+감쇠자)–trpE·D·C·B·A</li>\n<li>1단계 <b>억제</b>: Trp(보조억제물질) + 비활성 억제단백질 → 활성 → O 결합 → 전사 약 70배↓</li>\n<li>2단계 <b>감쇠</b>: 리더 mRNA 영역 1에 5′-UGG UGG-3′(Trp 코돈)\n  <ul><li>[Trp]↑: 리보솜 빠름 → <b>3:4 종결자</b> → 짧은 mRNA(~140 nt)</li>\n  <li>[Trp]↓: 리보솜 영역 1에서 정지 → <b>2:3 항종결자</b> → 전사 계속</li>\n  <li>번역 없음: 1:2 + 3:4 → 종결</li></ul></li>\n<li>원핵은 전사·번역 동시 진행이라 가능</li></ul>\n", "ref": ["nb:n10"]}, {"id": "k_b16", "s": "bio", "t": "서술 기출 – 작동자 실험과 억제단백질 도메인", "kw": ["서술", "기출", "작동자1", "작동자2", "작동자3", "도메인", "사량체", "이량체", "억제단백질", "70배", "2배"], "b": "<ul><li>O₁(+11) 변이 → 억제 전혀 ✗ → <b>주작동자</b></li>\n<li>O₂(+412) 또는 O₃(−82) 하나 변이 → 2배 감소, 둘 다 → 70배 감소 → 보조작동자, 서로 대체 가능, O₁과 함께 결합해 <b>DNA 고리</b></li>\n<li>억제단백질 도메인: DNA 결합 / 유도체(젖당) 결합 / 다량체(2·4량체) 형성</li></ul>\n", "ref": ["nb:n8"]}, {"id": "k_c1", "s": "chem", "t": "계·주위, 크기/세기 성질, 상태/경로함수", "kw": ["계", "주위", "열린계", "닫힌계", "고립계", "크기성질", "세기성질", "상태함수", "경로함수", "가역", "비가역"], "b": "<ul><li>열린계(물질○ 에너지○) / 닫힌계(물질✗ 에너지○) / 고립계(둘 다 ✗, 우주)</li>\n<li>크기 성질: V, m, U, H (양에 비례) / 세기 성질: T, P, 밀도</li>\n<li>상태함수: U, H, S, G, P, V, T / 경로함수: <b>q, w</b> (하지만 q+w는 경로 무관)</li>\n<li>가역: 무한소 변화로 방향 바뀜, 연속 평형 / 자발적 변화는 모두 비가역</li></ul>\n", "ref": ["q:3", "q:4", "q:5", "nc:n1"]}, {"id": "k_c2", "s": "chem", "t": "열역학 제1법칙과 일의 부호", "kw": ["제1법칙", "내부에너지", "ΔU", "q+w", "일", "부호", "팽창", "압축", "PV일", "Lam", "L·atm"], "b": "$\\Delta U=q+w$, $w=-P_{ex}\\Delta V$<br>\n<ul><li>팽창 ΔV>0 → w<0 (계가 일함) / 압축 → w>0</li>\n<li>발열 q<0, 흡열 q>0</li>\n<li>1 L·atm = 101.325 J</li>\n<li>$\\Delta U_{계}=-\\Delta U_{주위}$ → 우주 에너지 보존</li></ul>\n", "ref": ["q:5", "q:6", "nc:n1"]}, {"id": "k_c3", "s": "chem", "t": "열용량, 열량계, 엔탈피", "kw": ["열용량", "비열", "cp", "cv", "정압", "정적", "열량계", "봄열량계", "커피컵", "엔탈피", "ΔH", "ΔU", "Δn"], "b": "<ul><li>$q_v=nc_v\\Delta T=\\Delta U$ (봄 열량계, w=0) / $q_p=nc_p\\Delta T=\\Delta H$ (커피컵 열량계)</li>\n<li>$H=U+PV$, $\\Delta H=\\Delta U+\\Delta n_gRT$ (고체·액체만이면 ΔH≈ΔU)</li>\n<li>이상기체: $c_p-c_v=R$, 단원자 $c_v=\\tfrac32R$, $c_p=\\tfrac52R$ (이원자 이상은 회전·진동으로 더 큼)</li>\n<li>$c_{p} > c_{v}$: 일정 압력에선 팽창 일에도 에너지 사용</li>\n<li>물의 비열이 큰 이유: 수소결합</li></ul>\n", "ref": ["q:7", "q:8", "q:9", "q:11", "nc:n1", "nc:n2"]}, {"id": "k_c4", "s": "chem", "t": "이상기체 등온·단열 과정", "kw": ["등온", "단열", "가역", "이상기체", "감마", "γ", "PVγ", "nRTln", "등온팽창", "단열팽창", "비교"], "b": "<table class=\"t\"><tr><th></th><th>가역 등온</th><th>가역 단열</th></tr>\n<tr><td>조건</td><td>ΔU=0, q=−w</td><td>q=0, w=ΔU</td></tr>\n<tr><td>일</td><td>$-nRT\\ln\\frac{V_2}{V_1}$</td><td>$nc_v\\Delta T$</td></tr>\n<tr><td>관계</td><td>PV=일정</td><td>$PV^\\gamma$=일정, $T_2=T_1(P_2/P_1)^{(\\gamma-1)/\\gamma}$</td></tr>\n<tr><td>예 (5 mol, 298 K, 10→1 atm)</td><td>122 L, 298 K, w=−28.5 kJ</td><td>48.7 L, 119 K, w=−11.2 kJ</td></tr></table>\n가역 일이 최대: 10 atm·1 L → 1 atm·10 L에서 가역 −23.0 L·atm vs 비가역 −9 L·atm\n", "ref": ["q:14", "q:16", "q:18", "nc:n1"]}, {"id": "k_c5", "s": "chem", "t": "반응 엔탈피와 헤스 법칙", "kw": ["반응엔탈피", "생성엔탈피", "ΔHf", "연소", "분해", "용해", "중화", "헤스", "총열량불변", "결합엔탈피", "결합에너지"], "b": "<ul><li>$\\Delta H^\\circ=\\sum\\Delta H_f^\\circ(\\text{생성물})-\\sum\\Delta H_f^\\circ(\\text{반응물})$, 가장 안정한 원소 ΔHf°=0</li>\n<li>결합 엔탈피: $\\Delta H=\\sum D(\\text{반응물})-\\sum D(\\text{생성물})$ ← <b>순서 반대</b></li>\n<li>헤스 법칙: H가 상태함수 → 경로 무관 (승화열 = 융해열 + 기화열)</li>\n<li>연소: 항상 발열 / 분해 = −생성 / 중화(강산-강염기) ≈ −57.7 kJ/mol 일정</li></ul>\n", "ref": ["q:19", "q:20", "q:21", "q:22", "nc:n2"]}, {"id": "k_c6", "s": "chem", "t": "엔트로피와 제2·3법칙", "kw": ["엔트로피", "무질서도", "볼츠만", "klnW", "제2법칙", "제3법칙", "자발", "트루톤", "주위엔트로피", "ΔS", "표준몰엔트로피"], "b": "<ul><li>$S=k\\ln W$, $dS=dq_{rev}/T$</li>\n<li>등온 팽창 $nR\\ln\\frac{V_2}{V_1}$ / 상전이 $\\Delta H/T$ / 가열 $nc\\ln\\frac{T_2}{T_1}$ ($\\Delta S_p>\\Delta S_v$) / 가역 단열 0</li>\n<li>트루톤: 몰 증발 엔트로피 ≈ 85 J/K·mol (물 109, 수소결합)</li>\n<li>$\\Delta S_{surr}=-\\Delta H_{sys}/T$ (온도 낮을수록 큼)</li>\n<li>제2법칙: 자발 → $\\Delta S_{\\text{total}} > 0$ / 제3법칙: 완전결정 0 K → S=0</li>\n<li>기체 몰수↑, 고→액→기, 용해, 확산 → ΔS>0</li></ul>\n", "ref": ["q:24", "q:31", "q:32", "q:33", "q:34", "q:35"]}, {"id": "k_c7", "s": "chem", "t": "카르노 순환과 효율", "kw": ["카르노", "효율", "열기관", "순환", "Th", "Tc", "1-Tc/Th", "클라우지우스"], "b": "<ul><li>등온 팽창($T_h$) → 단열 팽창 → 등온 압축($T_c$) → 단열 압축</li>\n<li>$\\eta=\\dfrac{-w}{q_h}=1-\\dfrac{T_c}{T_h}$ → 100%는 $T_c=0$ 또는 $T_h=\\infty$에서만</li>\n<li>$\\oint dq_{rev}/T=0$ → $q_{\\text{rev}}$/T가 상태함수 → 엔트로피 정의(클라우지우스)</li></ul>\n", "ref": ["q:27", "q:30"]}, {"id": "k_c8", "s": "chem", "t": "깁스 자유에너지", "kw": ["깁스", "자유에너지", "ΔG", "ΔH-TΔS", "자발성", "T*", "표준자유에너지", "ΔGf", "하버", "온도의존"], "b": "<ul><li>$\\Delta G=\\Delta H-T\\Delta S=-T\\Delta S_{total}$ (일정 T, P)</li>\n<li>ΔH−,ΔS+ 항상 자발 / ΔH+,ΔS− 절대 ✗ / 둘 다 − : T&lt;T* / 둘 다 + : T&gt;T* ($T^*=\\Delta H/\\Delta S$)</li>\n<li>물: 273 K ΔG=0(평형), 263 K ΔG≈−220 J (자발적으로 얼음)</li>\n<li>하버: ΔG°=−92.2−298(−0.1987)≈−33.0 kJ</li>\n<li>ΔG°는 속도와 무관 / ΔGf°<0 → 원소보다 안정</li></ul>\n", "ref": ["q:37", "q:38", "q:39", "q:40", "q:41"]}, {"id": "k_c9", "s": "chem", "t": "결정성 고체의 종류", "kw": ["결정성고체", "비결정성고체", "이온결정", "분자결정", "공유결정", "망상", "금속결정", "등방성", "비등방성", "액정", "유리", "석영"], "b": "<table class=\"t\"><tr><th></th><th>이온</th><th>분자</th><th>망상(공유)</th><th>금속</th></tr>\n<tr><td>입자</td><td>양·음이온</td><td>분자</td><td>원자</td><td>양이온+자유전자</td></tr>\n<tr><td>녹는점</td><td>높음</td><td>낮음</td><td>매우 높음</td><td>높음</td></tr>\n<tr><td>전도(고/액)</td><td>✗/○</td><td>✗/✗</td><td>✗(흑연○)</td><td>○/○</td></tr>\n<tr><td>예</td><td>NaCl</td><td>얼음, I₂, CO₂</td><td>다이아몬드, 석영</td><td>Cu, Fe</td></tr></table>\n비결정성(유리·고무): 녹는점 일정 ✗, 등방성. 액정: 액체지만 비등방성(네마틱·스멕틱·콜레스테릭)\n", "ref": ["r1:1", "r1:3", "r2:59", "r2:60", "r2:63"]}, {"id": "k_c10", "s": "chem", "t": "X선 회절과 브래그 식", "kw": ["X선", "XRD", "회절", "브래그", "Bragg", "2dsinθ", "보강간섭"], "b": "$n\\lambda=2d\\sin\\theta$ — 추가 경로 $2d\\sin\\theta$가 파장의 정수배일 때 보강<br>\n예) λ=1.54 Å, θ=19.3°, n=1 → d=2.33 Å\n", "ref": ["r1:2", "r2:65"]}, {"id": "k_c11", "s": "chem", "t": "단위세포 (SC·BCC·FCC·HCP)", "kw": ["단위세포", "단순입방", "체심입방", "면심입방", "육방최조밀", "SC", "BCC", "FCC", "HCP", "CCP", "배위수", "충전율", "최조밀쌓임", "ABAB", "ABC", "밀도"], "b": "<table class=\"t\"><tr><th></th><th>SC</th><th>BCC</th><th>FCC</th><th>HCP</th></tr>\n<tr><td>배위수</td><td>6</td><td>8</td><td>12</td><td>12</td></tr>\n<tr><td>입자 수</td><td>1</td><td>2</td><td>4</td><td>6</td></tr>\n<tr><td>a–r</td><td>a=2r</td><td>$\\sqrt{3}\\,a=4r$</td><td>$\\sqrt{2}\\,a=4r$</td><td>a=2r</td></tr>\n<tr><td>충전율</td><td>52%</td><td>68%</td><td>74%</td><td>74%</td></tr></table>\nhcp: ABAB (Mg, Zn) / ccp: ABCABC (Al, Fe, Cu, Ni)<br>밀도 $\\rho=\\dfrac{nM}{N_Aa^3}$\n", "ref": ["r1:5", "r1:6", "r1:7", "r2:68", "r2:69", "r2:70"]}, {"id": "k_c12", "s": "chem", "t": "금속 결합, 합금, 반도체", "kw": ["금속결합", "전자바다", "전성", "연성", "합금", "치환형", "침입형", "강철", "황동", "탄소함량", "반도체", "띠간격", "도체", "절연체"], "b": "<ul><li>전자바다 모형: 양이온 작고 원자가전자 많을수록 결합 강함 (Fe > K)</li>\n<li>치환형 합금: 황동(Cu+Zn) / 침입형: 강철(Fe+C) → 단단, 연성↓. 연강<0.2%, 중강 0.2~0.6%, 고탄소강 0.6~1.5%</li>\n<li>띠 간격: 도체 0 / 반도체 작음 / 절연체 큼. 온도↑ → 금속 전도도↓, 반도체↑</li></ul>\n", "ref": ["r1:8", "r1:9", "r1:13", "r2:73", "r2:74"]}, {"id": "k_c13", "s": "chem", "t": "망상 고체 (다이아몬드·흑연·실리카·유리·세라믹)", "kw": ["다이아몬드", "흑연", "sp3", "sp2", "π", "실리카", "SiO2", "석영", "유리", "규산염", "세라믹", "동소체"], "b": "<ul><li>다이아몬드: sp³ 정사면체, 큰 띠 간격 → 절연체, 밀도 3.5</li>\n<li>흑연: sp² 층, 남은 2p → 비편재 π → 전도, 층간 약함 → 미끄러움, 밀도 2.2</li>\n<li>SiO₂: Si 3p 커서 O와 π결합 ✗ → SiO₄ 사면체 망상</li>\n<li>석영 용융 후 급랭 → 유리(비결정). 세라믹: 두 상 불균일, 재용융 ✗</li></ul>\n", "ref": ["r1:10", "r1:11", "r1:12", "r1:13", "r2:71"]}, {"id": "k_c14", "s": "chem", "t": "이온 결정과 틈새 자리, 반지름비", "kw": ["이온결정", "틈새", "정사면체", "정팔면체", "정육면체", "반지름비", "한계반지름비", "NaCl", "CsCl", "ZnS", "CaF2", "형석", "섬아연석", "배위수", "쿨롱"], "b": "<table class=\"t\"><tr><th>배위수</th><th>자리</th><th>r⁺/r⁻</th><th>예</th></tr>\n<tr><td>4</td><td>사면체 (ccp에 8개)</td><td>0.225~0.414</td><td>ZnS(1/2), CaF₂(전부)</td></tr>\n<tr><td>6</td><td>팔면체 (ccp에 4개)</td><td>0.414~0.732</td><td>NaCl</td></tr>\n<tr><td>8</td><td>정육면체</td><td>0.732~1</td><td>CsCl</td></tr></table>\n한계값: $\\frac{\\sqrt6-2}{2}$, $\\sqrt2-1$, $\\sqrt3-1$. 녹는점 ∝ q⁺q⁻/r² (CaO > NaCl > KBr)\n", "ref": ["r1:15", "r1:16", "r1:17", "r1:18", "r2:76", "r2:77"]}, {"id": "k_c15", "s": "chem", "t": "상평형 그림 (물·CO₂)", "kw": ["상평형", "상평형그림", "삼중점", "임계점", "초임계", "승화", "녹는점", "끓는점", "물", "이산화탄소", "CO2", "드라이아이스", "스케이트", "빨래"], "b": "<table class=\"t\"><tr><th></th><th>물</th><th>CO₂</th></tr>\n<tr><td>고-액 기울기</td><td><b>음</b> (얼음 밀도 < 물)</td><td>양</td></tr>\n<tr><td>삼중점</td><td>0.01 ℃, 4.58 torr</td><td>−56.6 ℃, <b>5.1 atm</b></td></tr>\n<tr><td>임계점</td><td>374 ℃, 218 atm</td><td>31.1 ℃, 73 atm</td></tr>\n<tr><td>1 atm</td><td>0 ℃ 녹음</td><td>−78 ℃ 승화</td></tr></table>\n<ul><li>승화는 삼중점 압력보다 낮을 때만 / 임계 온도 이상은 액화 불가(초임계 유체)</li>\n<li>언 빨래가 마름: 열린계라 증기가 빠져나감</li></ul>\n", "ref": ["r1:29", "r1:32", "r1:33", "r2:85", "r2:86"]}, {"id": "k_c16", "s": "chem", "t": "클라페이론·클라우지우스–클라페이롱 식", "kw": ["클라페이론", "클라우지우스", "클라페이롱", "기울기", "dP/dT", "증기압", "승화곡선"], "b": "<ul><li>클라페이론: $\\dfrac{dP}{dT}=\\dfrac{\\Delta H}{T\\Delta V}$ ($\\Delta G_{\\alpha} = \\Delta G_{\\beta}$에서 유도)</li>\n<li>고-액: ΔV 작아 가파름, 물만 ΔV<0 → 음수</li>\n<li>증기를 이상기체로: $\\ln\\dfrac{P_2}{P_1}=-\\dfrac{\\Delta H}{R}\\left(\\dfrac1{T_2}-\\dfrac1{T_1}\\right)$</li>\n<li>ΔH_승화 > ΔH_기화 → 삼중점 근처 승화곡선이 더 가파름</li></ul>\n", "ref": ["r2:88", "r2:89"]}, {"id": "k_e1", "s": "earth", "t": "궤도 속도와 탈출 속도", "kw": ["궤도속도", "탈출속도", "우주속도", "7.9", "11.2", "vc", "vesc", "루트2", "원궤도", "다누리"], "b": "<ul><li>$v_c=\\sqrt{\\dfrac{GM}{r}}$ (구심력 = 만유인력), 지표 7.9 km/s</li>\n<li>$v_{esc}=\\sqrt{\\dfrac{2GM}{r}}=\\sqrt2v_c$ (역학적 에너지 = 0), 지표 11.2 km/s</li>\n<li>높이↑ → 둘 다 작아짐 (PE가 0에 가까워짐)</li>\n<li>예) r = 10,000 km: $v_{c}$ ≈ 6.34, $v_{\\text{esc}}$ ≈ 8.97 km/s, Δv = 2.63 km/s</li></ul>\n", "ref": ["e4:1", "e4:2"]}, {"id": "k_e2", "s": "earth", "t": "궤도 진입 속도와 궤도 모양", "kw": ["진입속도", "타원", "포물선", "쌍곡선", "근지점", "원지점", "긴반지름", "궤도모양", "vi"], "b": "$v_i=v_c\\sqrt{2-\\dfrac{r}{a}}$ (a: 긴반지름)<br>\n<ol><li>$0 < v < v_{c}$: 타원 (A 원지점)</li><li>$v=v_{c}$: 원</li><li>$v_{c} < v <\\sqrt{2}\\,v_{c}$: 타원 (A 근지점)</li><li>$v=\\sqrt{2}\\,v_{c}$: 포물선</li><li>$v >\\sqrt{2}\\,v_{c}$: 쌍곡선</li></ol>\n예) r=10,000, 원지점 40,000 km → a=25,000 → v≈8.02 km/s\n", "ref": ["e4:3", "e4:4", "e4:6"]}, {"id": "k_e3", "s": "earth", "t": "산개 성단 vs 구상 성단", "kw": ["산개성단", "구상성단", "성단", "종족", "금속함량", "원반", "헤일로", "푸른색", "붉은색"], "b": "<table class=\"t\"><tr><th></th><th>산개</th><th>구상</th></tr>\n<tr><td>별 수</td><td>수백~수천, 느슨</td><td>수만~수백만, 구형</td></tr>\n<tr><td>위치</td><td>원반(나선팔), 1000+</td><td>헤일로, 약 200</td></tr>\n<tr><td>나이·색</td><td>젊음, 푸른색</td><td>100억 년+, 붉은색</td></tr>\n<tr><td>금속</td><td>높음, 종족 Ⅰ</td><td>낮음, 종족 Ⅱ</td></tr></table>\n", "ref": ["c1:2", "c1:3", "ne:n1"]}, {"id": "k_e4", "s": "earth", "t": "색지수와 색등급도", "kw": ["색지수", "B-V", "UBV", "필터", "색등급도", "CM도", "HR도", "표면온도"], "b": "<ul><li>색지수 = 짧은 파장 등급 − 긴 파장 등급 = B−V</li>\n<li>고온 → B−V 작음(음수 가능), A0형 = 0</li>\n<li>색등급도(색지수–겉보기 등급) ≈ H-R도 (성단 별은 거리 같음)</li></ul>\n", "ref": ["c1:3", "c1:4", "c1:5"]}, {"id": "k_e5", "s": "earth", "t": "성단의 나이 – 전향점, 헤르츠스프룽 갭", "kw": ["전향점", "나이", "헤르츠스프룽갭", "준거성", "플레이아데스", "히아데스", "표준주계열", "ZAMS"], "b": "<ul><li>전향점 = 남은 주계열성 중 가장 무거운 별 → 나이 많을수록 <b>오른쪽 아래</b></li>\n<li>플레이아데스가 히아데스보다 젊음</li>\n<li>헤르츠스프룽 갭: 무거운 별(≳2M☉)이 준거성 단계를 매우 빨리 지나서 생김 (젊은 산개 성단)</li>\n<li>구상 성단: 준거성·적색 거성·수평·점근 거성 가지 뚜렷</li></ul>\n", "ref": ["c1:6", "c1:8"]}, {"id": "k_e6", "s": "earth", "t": "주계열 맞추기와 거리 지수", "kw": ["주계열맞추기", "거리지수", "m-M", "5logd", "거리", "프레세페", "pc"], "b": "<ul><li>성단 주계열(m)을 표준 주계열(M)에 수직으로 맞춘 차이 = 거리 지수</li>\n<li>$m-M=5\\log d-5$ → $d=10^{(m-M+5)/5}$</li>\n<li>젊은 성단, 최대 약 10 kpc. 늙은 성단은 주계열 범위가 좁아 어려움</li>\n<li>프레세페: 10.2 − 4.0 = 6.2 → d ≈ 174 pc</li></ul>\n", "ref": ["c1:9", "c1:18"]}, {"id": "k_e7", "s": "earth", "t": "맥동 변광성과 주기–광도 관계", "kw": ["세페이드", "변광성", "맥동변광성", "주기광도", "레빗", "섀플리", "RR", "거문고자리", "Ⅰ형", "Ⅱ형", "영점오차", "바데"], "b": "<ul><li>레빗: 마젤란성운 세페이드 → 광도 클수록 주기 김</li>\n<li>Ⅰ형(고전적, 원반, 종족 Ⅰ) vs Ⅱ형(W Vir, 구상·헤일로, 종족 Ⅱ): 같은 주기에서 <b>Ⅰ형이 1.5등급 밝음</b></li>\n<li>RR Lyrae: 주기 5~24시간, 구상 성단, 수평 가지</li>\n<li>HV 2063: 14.45−(−3.3) → d≈35.5 kpc (실제 50~60 kpc, 영점 오차 → 1952 바데 수정)</li>\n<li>M3: 평균 거리 지수 16.0 → d≈15,850 pc</li></ul>\n", "ref": ["c2:2", "c2:3", "c2:15"]}, {"id": "k_e8", "s": "earth", "t": "우리은하의 구조와 대논쟁", "kw": ["우리은하", "은하중심", "섀플리", "커티스", "대논쟁", "허블", "안드로메다", "M31", "막대나선", "팽대부", "블랙홀", "스피처", "가이아", "태양위치"], "b": "<ul><li>섀플리: 구상 성단 분포 중심 ≠ 태양 → 태양은 중심이 아님</li>\n<li>대논쟁(1920): 안드로메다 내부(섀플리) vs 외부 은하(커티스)</li>\n<li>허블(1924): M31 세페이드 → 약 90만 광년 > 우리은하 30만 광년 → 외부 은하</li>\n<li>막대나선 은하, 원반 지름 ≈30 kpc, 태양 ≈8.5(8.2) kpc, 중심 블랙홀 ≈400만 M☉</li>\n<li>막대 확인: 스피처(적외선 비대칭) + 가이아(연주 시차 별 지도). 원반은 휘어 있음</li></ul>\n", "ref": ["c2:7", "c2:9", "c2:10", "c2:11", "c2:12"]}, {"id": "k_p1", "s": "phys", "t": "에너지 띠 이론", "kw": ["에너지띠", "띠", "밴드", "띠간격", "원자가띠", "전도띠", "도체", "반도체", "절연체", "부도체", "페르미"], "b": "<ul><li>원자 1개: 불연속 준위 → 원자가 많으면 준위가 갈라져 <b>띠</b></li>\n<li>도체: 띠 겹침 / 반도체: 띠 간격 작음 / 절연체: 띠 간격 큼</li>\n<li>온도↑: 금속 저항↑, 반도체 저항↓</li></ul>\n", "ref": ["s2:2", "s2:3", "s2:4"]}, {"id": "k_p2", "s": "phys", "t": "도핑 – P형·N형 반도체", "kw": ["도핑", "P형", "N형", "양공", "정공", "전자", "붕소", "인", "3족", "5족", "받개", "주개", "홀효과", "중성", "다수운반자"], "b": "<table class=\"t\"><tr><th></th><th>P형</th><th>N형</th></tr>\n<tr><td>불순물</td><td>3족 B, Al, In</td><td>5족 P, As, Sb</td></tr>\n<tr><td>운반자</td><td>양공(+)</td><td>전자(−)</td></tr>\n<tr><td>준위</td><td>받개(원자가 띠 바로 위)</td><td>주개(전도띠 바로 아래)</td></tr></table>\n둘 다 전체는 <b>전기적 중성</b>. 운반자 부호는 <b>홀 효과</b>로 판별\n", "ref": ["s2:5", "s2:6", "s2:7", "s2:8"]}, {"id": "k_p3", "s": "phys", "t": "PN 접합과 다이오드", "kw": ["PN접합", "다이오드", "공핍층", "공간전하", "내부전위", "built-in", "0.7V", "순방향", "역방향", "바이어스", "항복", "애노드", "캐소드"], "b": "<ul><li>확산·재결합 → 이온만 남은 <b>공핍층</b> → 내부 전위 ≈ 0.7 V</li>\n<li>순방향(P에 +): 공핍층 얇아짐 → 전류 ($I=I_e+I_h$)</li>\n<li>역방향: 공핍층 넓어짐 → 전류 ≈ 0, 매우 큰 역전압 → 항복</li>\n<li>기호: 화살표 쪽 애노드(P), 막대 쪽 캐소드(N)</li></ul>\n", "ref": ["s2:9", "s2:10"]}, {"id": "k_p4", "s": "phys", "t": "다이오드 특성과 근사 모델", "kw": ["특성곡선", "이상적다이오드", "실제다이오드", "열전압", "Vt", "25mV", "이상인자", "역포화전류", "구간선형", "고정전압", "근사모델", "Rf", "턴온"], "b": "<ul><li>실제: $i_D=I_s(e^{v_D/\\eta V_t}-1)$, $V_t=kT/e\\approx25$ mV</li>\n<li>이상적: 순방향 <b>단락</b>(v=0), 역방향 <b>개방</b>(i=0) — PPT 글자 오류 주의</li>\n<li>구간 선형: $V_{\\gamma} + R_{f}$ + 이상 (기울기 $1/R_{f}$) / 고정 전압: $V_{\\gamma}$ + 이상 / 이상적</li>\n<li>예제: 5 V, 500 Ω, $R_{f}$ 20 Ω → i = 4.3/520 = 8.27 mA, $v_{D}$ ≈ 0.87 V</li></ul>\n", "ref": ["s2:13", "s2:14", "s1:2", "s1:3"]}, {"id": "k_p5", "s": "phys", "t": "정류회로와 평활회로, 리플", "kw": ["정류", "반파정류", "전파정류", "브리지", "평활", "축전기", "커패시터", "리플", "ripple", "리플비율", "리플진동수", "LED", "수행평가", "충전기"], "b": "<ul><li>반파: 다이오드 1개, (+) 반주기만</li>\n<li>브리지(전파): 다이오드 4개, 입력 극성 무관하게 출력 (+) (LED 퀴즈)</li>\n<li>평활: 부하에 축전기 <b>병렬</b> → 충전·방전</li>\n<li>$V_{ripple}=V_{max}-V_{min}$, $r_{pp}=\\frac{V_{ripple}}{V_{DC}}\\times100\\%$, $f_{ripple}=1/T_{ripple}$ (전파 = 입력의 2배)</li>\n<li>실험: LED 4개 브리지, Vpp 16 V·1 Hz 사인파, 300 Ω, 2200 μF (τ=0.66 s)</li></ul>\n", "ref": ["s2:15", "s2:16", "s2:17", "s2:18", "s2:19", "s2:20"]}, {"id": "k_p6", "s": "phys", "t": "함수발생기와 오실로스코프", "kw": ["함수발생기", "오실로스코프", "멀티미터", "Vertical", "Horizontal", "Trigger", "Vpp", "오프셋", "위상", "브레드보드"], "b": "<ul><li>오실로스코프: Vertical(전압 V/div), Horizontal(시간 s/div), Trigger(파형 고정)</li>\n<li>함수발생기: Sine·Square·Ramp·Pulse, Freq, Ampl(Vpp), Offset, Phase</li>\n<li>Vpp = 최댓값 − 최솟값 = 2 × 진폭</li>\n<li>반파 정류 실험: 브레드보드, 1N4007, 1 kΩ</li></ul>\n", "ref": ["s2:25", "s2:26", "s2:27", "s2:28", "s2:29"]}];
